local _, addon = ...
addon.localeData.deDE.racial = {
    GNOME = {
        HEROIC_STRIKE = { "Meine Waffe ist länger als mein Arm. Darum gibt es Hebelgesetze.", "*verlagert das Gewicht auf die vordere Ferse und schlägt aus dem ganzen Körper.*", "Wenn das klappt, schreibe ich eine Abhandlung darüber. Es gibt Argumente, die brauchen keinen zweiten Satz.", "*prüft einen lockeren Verschluss an der Rüstung; schiebt die Schulter nach und lässt den Stahl sprechen.*" },
        CHARGE = { "Die Strecke ist berechnet. Die Landung bleibt ein Feldversuch!", "*zieht den Kinnriemen straff und schießt unter einer ausgestreckten Waffe hindurch.*", "Bitte nichts anfassen, das ich gerade kalibriere! Ich komme! Das ist keine Warnung, sondern eine Wegbeschreibung!", "*tippt zweimal gegen eine verbogene Messskala; prescht mit einem lauten Scheppern durch die Lücke in der Reihe.*" },
        REND = { "Eine Rüstungsnaht ist nur so stark wie ihr schwächster Stich.", "*setzt die Schneide genau zwischen zwei lockere Platten.*", "Für Außenstehende sieht es nach Chaos aus. Für mich nach Daten. Ein Schneider wäre entsetzt. Ich bin zufrieden.", "*versteckt ein winziges Werkzeug im Handschuh; zieht die Klinge rasch zurück und sucht die nächste Öffnung.*" },
        HAMSTRING = { "Die Schrittlänge sinkt jetzt erheblich. Gern geschehen!", "*taucht tief ab und führt die Klinge knapp über dem Boden.*", "Ein wenig Wahnsinn ist noch keine fehlerhafte Konstruktion. Ich schlage nicht gern zweimal hinterher. Einmal genügt.", "*zieht die Schutzbrille vor die Augen; führt die Waffe knapp über den Boden und richtet sich sofort wieder auf.*" },
        THUNDER_CLAP = { "Ich wollte ein Warnsignal geben. Die Erde hat etwas überreagiert.", "*stampft mit dem Stiefel auf und staunt selbst über den aufwirbelnden Staub.*", "Wenn das klappt, schreibe ich eine Abhandlung darüber. Hört Ihr das? Die Erde erhebt Einspruch.", "*kritzelt im Laufen eine Zahl auf den Schild; reißt die Arme auseinander und lässt einen dumpfen Schlag durch die Reihen grollen.*" },
        CLEAVE = { "Zwei Gegner? Ausgezeichnet, dann lohnt sich der Schwung.", "*dreht die Hüfte und lässt die Waffe in einem breiten Bogen folgen.*", "Bitte nichts anfassen, das ich gerade kalibriere! Ich hoffe, Ihr habt alle genug Abstand. Ich nicht.", "*rückt ein viel zu kleines Schutzvisier zurecht; dreht auf der Ferse und nimmt den Schwung in den nächsten Bogen mit.*" },
        EXECUTE = { "Jetzt reicht ein einziger sauberer Schnitt. Kein zweiter Versuch.", "*wartet, bis die Deckung sinkt, und führt den Schlag ohne weiteres Zögern.*", "Für Außenstehende sieht es nach Chaos aus. Für mich nach Daten. Jetzt wird nicht mehr verhandelt.", "*prüft einen lockeren Verschluss an der Rüstung; fasst den Griff fester und schließt die letzte Lücke.*" },
        SUNDER_ARMOR = { "Interessante Nietung. Hat der Schmied auch eine Garantie gegeben?", "*setzt die Spitze seiner Waffe an einer bereits gelockerten Fuge an.*", "Ein wenig Wahnsinn ist noch keine fehlerhafte Konstruktion. Teurer Stahl ist noch keine gute Deckung.", "*tippt zweimal gegen eine verbogene Messskala; zieht mit der Schneide eine Linie entlang einer Naht im Metall.*" },
        SHIELD_BLOCK = { "Die Garantie gilt bis zum dritten Oger. Danach verhandeln wir.", "*tippt zweimal gegen eine verbogene Messskala; dreht die Schildkante in den kommenden Schlag und federt ihn ab.*", "Wenn das klappt, schreibe ich eine Abhandlung darüber. Ein gutes Schild hört zu, bevor es antwortet.", "*versteckt ein winziges Werkzeug im Handschuh; stemmt die Stiefel in den Boden und lässt die Deckung nicht nachgeben.*" },
        SHIELD_BASH = { "Ein sauberer Versuch braucht einen präzisen Treffer. Psst. Mal sehen, ob ich Euren Zauber unterbrechen kann.", "*versteckt ein winziges Werkzeug im Handschuh; rammt die Schildfläche nach vorn, genau zwischen zwei Silben.*", "Bitte nichts anfassen, das ich gerade kalibriere! Meine Antwort auf Magie hat einen Holzgriff.", "*zieht die Schutzbrille vor die Augen; rückt einen Schritt heran und stößt unvermittelt mit dem Schild zu.*" },
        TAUNT = { "Ein sauberer Versuch braucht einen präzisen Treffer. Hier drüben! Der Ärger hat heute meinen Namen.", "*zieht die Schutzbrille vor die Augen; klopft mit dem Schwertknauf dreimal provokant auf den Schild.*", "Für Außenstehende sieht es nach Chaos aus. Für mich nach Daten. Die anderen haben Wichtigeres zu tun. Ich nicht.", "*kritzelt im Laufen eine Zahl auf den Schild; tritt demonstrativ aus der Reihe und winkt die Gegner heran.*" },
        BATTLE_SHOUT = { "Die akustische Versuchsanordnung ist einsatzbereit. Schultern hoch, Reihen schließen! Heute fällt hier niemand allein!", "*kritzelt im Laufen eine Zahl auf den Schild; schlägt den Schwertknauf im Takt gegen den Schildrand.*", "Ein wenig Wahnsinn ist noch keine fehlerhafte Konstruktion. Ihr habt Beine zum Stehen und Herzen zum Durchhalten. Nutzt beides!", "*rückt ein viel zu kleines Schutzvisier zurecht; richtet sich vor den Verbündeten auf und hebt die Klinge hoch.*" },
        DEMORALIZING_SHOUT = { "Die akustische Versuchsanordnung ist einsatzbereit. Die Ersten von Euch zittern schon. Die Letzten merken es gleich!", "*rückt ein viel zu kleines Schutzvisier zurecht; lässt einen tiefen, rauen Schlachtruf aus voller Brust erschallen.*", "Wenn das klappt, schreibe ich eine Abhandlung darüber. Schaut Euch um. Für wen wollt Ihr eigentlich noch kämpfen?", "*prüft einen lockeren Verschluss an der Rüstung; zeigt mit der Klinge auf die wankende feindliche Linie.*" },
        REVENGE = { "Ein sauberer Versuch braucht einen präzisen Treffer. Danke für die Gelegenheit. Die kommt sofort zurück.", "*prüft einen lockeren Verschluss an der Rüstung; lenkt die Waffe ab und fährt in die entstandene Lücke.*", "Bitte nichts anfassen, das ich gerade kalibriere! Ich vergesse Gesichter. Schläge nicht.", "*tippt zweimal gegen eine verbogene Messskala; dreht sich aus der Abwehr direkt in den Gegenangriff.*" },
        OVERPOWER = { "Ein sauberer Versuch braucht einen präzisen Treffer. Da war eine Lücke. Ihr habt sie mir geschenkt.", "*tippt zweimal gegen eine verbogene Messskala; gleitet an der vorbeigehenden Waffe vorbei und nutzt den offenen Winkel.*", "Für Außenstehende sieht es nach Chaos aus. Für mich nach Daten. Wer danebenhaut, lädt mich ein.", "*versteckt ein winziges Werkzeug im Handschuh; nutzt eine missratene Bewegung für einen schnellen Gegenstoß.*" },
        MORTAL_STRIKE = { "Ein sauberer Versuch braucht einen präzisen Treffer. Ich spare mir den zweiten Versuch.", "*versteckt ein winziges Werkzeug im Handschuh; nimmt die Waffe fest in beide Hände und legt den ganzen Körper in einen einzigen Schlag.*", "Ein wenig Wahnsinn ist noch keine fehlerhafte Konstruktion. Manche Duelle enden mit einem Satz. Dieses nicht.", "*zieht die Schutzbrille vor die Augen; schreitet voran und führt den Stahl mit unerbittlicher Präzision.*" },
        WHIRLWIND = { "Die Simulation läuft besser mit echten Gegnern. Stellt Euch ruhig im Kreis auf. Es ist praktisch.", "*zieht die Schutzbrille vor die Augen; dreht sich mitsamt der Waffe durch eine Schneise im Gedränge.*", "Wenn das klappt, schreibe ich eine Abhandlung darüber. Ich teile gern. Heute Stahl.", "*kritzelt im Laufen eine Zahl auf den Schild; lässt die Klinge in weitem Schwung ringsum singen.*" },
        BLOODTHIRST = { "Eine kontrollierte Überlastung ist keine Fehlfunktion. Der Puls wird schneller. Die Hand bleibt ruhig.", "*kritzelt im Laufen eine Zahl auf den Schild; atmet scharf aus, reißt die Waffe hoch und setzt unerbittlich nach.*", "Bitte nichts anfassen, das ich gerade kalibriere! Nur weil ich zornig bin, bin ich noch lange nicht ungenau.", "*rückt ein viel zu kleines Schutzvisier zurecht; treibt mit wilden Augen, aber kontrolliertem Griff den Angriff voran.*" },
        INTERCEPT = { "Die Beschleunigung wurde natürlich vorher berechnet. Ein Vorsprung ist nur geliehene Zeit.", "*rückt ein viel zu kleines Schutzvisier zurecht; stürzt seitlich aus dem Kampfgetümmel und schneidet den Weg ab.*", "Für Außenstehende sieht es nach Chaos aus. Für mich nach Daten. Ihr rennt? Wie aufmerksam, ich wollte mich ohnehin bewegen.", "*prüft einen lockeren Verschluss an der Rüstung; stößt sich aus dem Stand ab und landet mitten in der Fluchtlinie.*" },
        PUMMEL = { "Ein sauberer Versuch braucht einen präzisen Treffer. Zu viele Worte. Zu wenig Deckung.", "*prüft einen lockeren Verschluss an der Rüstung; stört die Zauberbewegung mit einem raschen, gezielten Stoß.*", "Ein wenig Wahnsinn ist noch keine fehlerhafte Konstruktion. Wolltet Ihr noch etwas sagen? Nein? Gut.", "*tippt zweimal gegen eine verbogene Messskala; bringt den gegnerischen Arm mit einem knappen Schlag aus dem Takt.*" },
        SWEEPING_STRIKES = { "Die Simulation läuft besser mit echten Gegnern. Wenn schon Arbeit, dann richtig.", "*tippt zweimal gegen eine verbogene Messskala; lässt den ersten Hieb in einen zweiten Bogen übergehen.*", "Wenn das klappt, schreibe ich eine Abhandlung darüber. Mehrere Gegner? Spart Wege.", "*versteckt ein winziges Werkzeug im Handschuh; nimmt den Schwung nicht zurück, sondern führt ihn durch das Getümmel weiter.*" },
        DEATH_WISH = { "Eine kontrollierte Überlastung ist keine Fehlfunktion. Die Vernunft hat gesprochen. Ich habe ihr widersprochen.", "*versteckt ein winziges Werkzeug im Handschuh; lockert den Griff für einen Augenblick und stürzt sich entschlossen nach vorn.*", "Bitte nichts anfassen, das ich gerade kalibriere! Ich weiß, was ich riskiere. Die anderen vielleicht nicht.", "*zieht die Schutzbrille vor die Augen; wirft einen letzten Blick auf die eigene Deckung und entscheidet sich für den Angriff.*" },
        RECKLESSNESS = { "Eine kontrollierte Überlastung ist keine Fehlfunktion. Vorsicht war gestern. Heute wird gehandelt.", "*zieht die Schutzbrille vor die Augen; verliert jede Zurückhaltung, ohne die Waffe aus der Hand zu lassen.*", "Für Außenstehende sieht es nach Chaos aus. Für mich nach Daten. Morgen darf man mich dafür ausschimpfen. Wenn wir ein Morgen haben.", "*kritzelt im Laufen eine Zahl auf den Schild; setzt den ganzen Körper in eine wilde Folge von Angriffen.*" },
        LAST_STAND = { "Meine Sicherheitsvorkehrungen sind ausnahmsweise nützlich. Bis hierher und keinen Schritt weiter.", "*kritzelt im Laufen eine Zahl auf den Schild; stemmt sich mühsam auf und hebt den Schild noch einmal.*", "Ein wenig Wahnsinn ist noch keine fehlerhafte Konstruktion. Ich stehe noch. Das muss als Antwort genügen.", "*rückt ein viel zu kleines Schutzvisier zurecht; stellt sich trotz zitternder Beine erneut schützend in die Bresche.*" },
        SHIELD_WALL = { "Meine Sicherheitsvorkehrungen sind ausnahmsweise nützlich. Hinter mir. Keine Heldentaten auf eigene Rechnung!", "*rückt ein viel zu kleines Schutzvisier zurecht; zieht das Schild dicht heran und verhakt die Schulter in der Linie.*", "Wenn das klappt, schreibe ich eine Abhandlung darüber. Wer durch mich hindurch will, braucht einen langen Atem.", "*prüft einen lockeren Verschluss an der Rüstung; schließt die letzte Lücke zwischen Schild und Rüstung.*" },
        RETALIATION = { "Ein sauberer Versuch braucht einen präzisen Treffer. Wer austeilt, muss das Echo mögen.", "*prüft einen lockeren Verschluss an der Rüstung; öffnet die Deckung einen Spalt und beantwortet jeden Angriff mit Stahl.*", "Bitte nichts anfassen, das ich gerade kalibriere! Kommt nur. Ich habe für jeden einen Augenblick übrig.", "*tippt zweimal gegen eine verbogene Messskala; legt die Füße breit und wartet auf die ersten ungeduldigen Hiebe.*" },
        MOCKING_BLOW = { "Ein sauberer Versuch braucht einen präzisen Treffer. Seid Ihr tatsächlich gefährlich oder nur besonders laut?", "*tippt zweimal gegen eine verbogene Messskala; lässt die Spitze absichtlich zu tief sinken und lockt den Gegner näher.*", "Für Außenstehende sieht es nach Chaos aus. Für mich nach Daten. Oh, verzeiht. Ich hatte Euch für einen Übungsgegner gehalten.", "*versteckt ein winziges Werkzeug im Handschuh; setzt einen frechen Hieb und grinst hinter dem Schild hervor.*" },
        BERSERKER_RAGE = { "Eine kontrollierte Überlastung ist keine Fehlfunktion. Angst? Die hat heute keinen Platz in meinem Kopf.", "*versteckt ein winziges Werkzeug im Handschuh; schüttelt die Schultern aus, als würde eine unsichtbare Last abfallen.*", "Ein wenig Wahnsinn ist noch keine fehlerhafte Konstruktion. Meine Furcht darf draußen warten. Meine Wut kommt mit.", "*zieht die Schutzbrille vor die Augen; stößt die Luft aus, strafft den Nacken und hält den Blick fest.*" },
        BLOODRAGE = { "Eine kontrollierte Überlastung ist keine Fehlfunktion. Schmerz ist eine Nachricht. Ich antworte später.", "*zieht die Schutzbrille vor die Augen; schlägt die Faust gegen die Brust und sammelt neuen Kampfeswillen.*", "Wenn das klappt, schreibe ich eine Abhandlung darüber. Das Herz schlägt. Mehr muss es gerade nicht erklären.", "*kritzelt im Laufen eine Zahl auf den Schild; beißt die Zähne zusammen und spannt die Schultern unter der Rüstung.*" },
        DISARM = { "Ein sauberer Versuch braucht einen präzisen Treffer. Ihr habt ein schönes Schwert. Darf ich es kurz sehen?", "*kritzelt im Laufen eine Zahl auf den Schild; versucht, die gegnerische Waffe mit einer knappen Drehung aus der Hand zu hebeln.*", "Bitte nichts anfassen, das ich gerade kalibriere! Mal sehen, ob Ihr auch ohne Waffe so gesprächig seid.", "*rückt ein viel zu kleines Schutzvisier zurecht; versucht, den Griff der gegnerischen Waffe abzufangen und aus der Linie zu drehen.*" },
        INTIMIDATING_SHOUT = { "Die akustische Versuchsanordnung ist einsatzbereit. Lauft, solange Ihr noch wisst, wohin!", "*rückt ein viel zu kleines Schutzvisier zurecht; schleudert einen wilden Schrei über die Köpfe der Gegner hinweg.*", "Für Außenstehende sieht es nach Chaos aus. Für mich nach Daten. Das war die freundliche Warnung. Die zweite kommt mit Stahl.", "*prüft einen lockeren Verschluss an der Rüstung; schlägt donnernd gegen den Schild und bleckt die Zähne.*" },
        CHALLENGING_SHOUT = { "Die akustische Versuchsanordnung ist einsatzbereit. ALLE ZU MIR! Ich habe Platz für Euren ganzen Ärger!", "*prüft einen lockeren Verschluss an der Rüstung; reißt beide Arme auseinander und fordert die feindliche Reihe heraus.*", "Ein wenig Wahnsinn ist noch keine fehlerhafte Konstruktion. Lasst die anderen in Ruhe. Ich bin heute Euer Problem!", "*tippt zweimal gegen eine verbogene Messskala; schlägt mehrmals auf den Schild und brüllt die Gegner an.*" },
        SLAM = { "Ein sauberer Versuch braucht einen präzisen Treffer. Das ist kein Hammer. Es fühlt sich gleich aber so an.", "*tippt zweimal gegen eine verbogene Messskala; holt über die Schulter aus und lässt den Stahl mit voller Kraft niederfahren.*", "Wenn das klappt, schreibe ich eine Abhandlung darüber. Lieber ein sauberer Treffer als fünf halbe.", "*versteckt ein winziges Werkzeug im Handschuh; lässt die Waffe nach kurzem Zögern mit dem ganzen Gewicht folgen.*" },
        DEVASTATE = { "Ein sauberer Versuch braucht einen präzisen Treffer. Schon locker? Dann lösen wir den Rest auch noch.", "*versteckt ein winziges Werkzeug im Handschuh; schlägt hart auf eine bereits angeschlagene Stelle der Rüstung.*", "Bitte nichts anfassen, das ich gerade kalibriere! Ich sehe, der Schmied hat an der falschen Stelle gespart.", "*zieht die Schutzbrille vor die Augen; klopft prüfend gegen die offene Fuge und setzt entschlossen nach.*" },
        SHIELD_SLAM = { "Ein sauberer Versuch braucht einen präzisen Treffer. Ein Schild kann auch Türen schließen. Auf Nasenhöhe.", "*zieht die Schutzbrille vor die Augen; reißt den Schild aus der Deckung und stößt dessen Kante kraftvoll nach vorn.*", "Für Außenstehende sieht es nach Chaos aus. Für mich nach Daten. Wer sagt, Verteidigung sei höflich?", "*kritzelt im Laufen eine Zahl auf den Schild; macht einen kurzen Satz vorwärts und lässt den Schild sprechen.*" },
        CONCUSSION_BLOW = { "Ein sauberer Versuch braucht einen präzisen Treffer. Ich versuche, Euch aus dem Takt zu bringen.", "*kritzelt im Laufen eine Zahl auf den Schild; versucht, einen schweren Hieb in die Lücke zwischen zwei Bewegungen zu führen.*", "Ein wenig Wahnsinn ist noch keine fehlerhafte Konstruktion. Ich versuche, allen einen Augenblick Ruhe zu verschaffen.", "*rückt ein viel zu kleines Schutzvisier zurecht; verkürzt den Griff und schwingt mit überraschender Wucht.*" },
        VICTORY_RUSH = { "Die Beschleunigung wurde natürlich vorher berechnet. Einer weniger. Die anderen stehen noch.", "*rückt ein viel zu kleines Schutzvisier zurecht; nutzt den gewonnenen Atemzug, richtet sich auf und prescht weiter.*", "Wenn das klappt, schreibe ich eine Abhandlung darüber. Feiern können wir später. Da bewegt sich noch etwas.", "*prüft einen lockeren Verschluss an der Rüstung; klopft sich einmal auf die Brust und setzt sofort nach.*" },
        BATTLE_STANCE = { "Die Simulation läuft besser mit echten Gegnern. Zwischen Mut und Dummheit liegen manchmal nur zwei Fußbreit.", "*prüft einen lockeren Verschluss an der Rüstung; setzt die Stiefel schulterbreit auf und lässt die Waffe locker kreisen.*", "Bitte nichts anfassen, das ich gerade kalibriere! Ich bleibe beweglich. Der Rest darf sich entscheiden.", "*tippt zweimal gegen eine verbogene Messskala; wiegt das Gewicht zwischen Schildarm und Waffenhand aus.*" },
        DEFENSIVE_STANCE = { "Meine Sicherheitsvorkehrungen sind ausnahmsweise nützlich. Wer an meine Leute will, muss zuerst meinen Schild überzeugen.", "*tippt zweimal gegen eine verbogene Messskala; stellt die Beine breit und hält den Schild vor die Verbündeten.*", "Für Außenstehende sieht es nach Chaos aus. Für mich nach Daten. Heute gewinnt nicht, wer am lautesten brüllt.", "*versteckt ein winziges Werkzeug im Handschuh; senkt den Schwerpunkt und wird hinter der Deckung nahezu unbeweglich.*" },
        BERSERKER_STANCE = { "Eine kontrollierte Überlastung ist keine Fehlfunktion. Wer behauptet, Wut mache blind, hat nie richtig hingesehen.", "*versteckt ein winziges Werkzeug im Handschuh; atmet tief ein, hebt das Kinn und nimmt eine wilde Haltung ein.*", "Ein wenig Wahnsinn ist noch keine fehlerhafte Konstruktion. Die Welt wird plötzlich sehr einfach: vorwärts.", "*zieht die Schutzbrille vor die Augen; lockert die Schultern, lässt die Waffe sinken und reißt sie schlagartig hoch.*" },
        PIERCING_HOWL = { "Die akustische Versuchsanordnung ist einsatzbereit. Wenn Ihr den Ruf hört, seid Ihr schon zu nah.", "*zieht die Schutzbrille vor die Augen; heult so durchdringend, dass die Stimmen umher für einen Moment verstummen.*", "Wenn das klappt, schreibe ich eine Abhandlung darüber. Nein, das war kein Wolfsrudel. Nur ich.", "*kritzelt im Laufen eine Zahl auf den Schild; wirft den Kopf zurück und lässt einen rauen, langen Laut los.*" },
        SPEARING_STRIKE = { "Ein sauberer Versuch braucht einen präzisen Treffer. Die Lücke ist schmal. Meine Spitze nicht.", "*kritzelt im Laufen eine Zahl auf den Schild; führt die Waffe mit einem einzigen geraden Schritt nach vorn.*", "Bitte nichts anfassen, das ich gerade kalibriere! Rüstung ist stark. Winkel sind stärker.", "*rückt ein viel zu kleines Schutzvisier zurecht; dreht das Handgelenk, zielt auf die Schwachstelle und stößt vor.*" },
        TACTICAL_MASTERY = { "Das nennt man Problemlösung unter ungünstigen Versuchsbedingungen.", "*rückt ein viel zu kleines Schutzvisier zurecht; verändert unmerklich den Stand und bewahrt die Übersicht.*", "Für Außenstehende sieht es nach Chaos aus. Für mich nach Daten. Ein Schlachtfeld ist kein Würfelspiel. Es wird gelesen.", "*prüft einen lockeren Verschluss an der Rüstung; mustert Wege, Gegner und Rückzugsräume, ohne die Waffe zu senken.*" },
    },
    HUMAN = {
        HEROIC_STRIKE = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Wisst Ihr, warum meine Waffe so schwer ist? Sie widerspricht selten.", "*richtet das abgewetzte Wappen auf dem Schild aus; verlegt das Gewicht auf den vorderen Fuß und führt einen wuchtigen Hieb.*", "Die anderen verlassen sich auf mich. Ich werde sie nicht enttäuschen. Es gibt Argumente, die brauchen keinen zweiten Satz.", "*prüft mit kurzem Blick die Stellung der Verbündeten; schiebt die Schulter nach und lässt den Stahl sprechen.*" },
        CHARGE = { "Befehle sind gut. Vorangehen ist besser. Wenn der Weg versperrt ist, nehme ich eben den direkten.", "*prüft mit kurzem Blick die Stellung der Verbündeten; senkt die Schulter, stößt sich ab und wirbelt Staub auf.*", "Haltung bewahren. Auch wenn keiner mehr zusieht. Ich komme! Das ist keine Warnung, sondern eine Wegbeschreibung!", "*strafft einen Lederriemen am Unterarm; prescht mit einem lauten Scheppern durch die Lücke in der Reihe.*" },
        REND = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Rüstungsnähte sind kleine Geheimnisse. Ich bin neugierig.", "*strafft einen Lederriemen am Unterarm; führt die Schneide schräg über eine schlecht geschützte Stelle.*", "Ein Schlachtplan lebt länger, wenn ihn jemand verteidigt. Ein Schneider wäre entsetzt. Ich bin zufrieden.", "*nickt einem Kameraden knapp zu; zieht die Klinge rasch zurück und sucht die nächste Öffnung.*" },
        HAMSTRING = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Weglaufen? Das ist ein Plan mit Schwächen.", "*nickt einem Kameraden knapp zu; taucht tief unter der gegnerischen Deckung hindurch.*", "Unter dieser Rüstung steckt noch ein Versprechen. Ich schlage nicht gern zweimal hinterher. Einmal genügt.", "*setzt den Helm mit routiniertem Griff gerade; führt die Waffe knapp über den Boden und richtet sich sofort wieder auf.*" },
        THUNDER_CLAP = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Wenn der Boden bebt, brauchen wir keinen Trommler mehr.", "*setzt den Helm mit routiniertem Griff gerade; stampft mit solcher Wucht auf, dass Staub vom Boden springt.*", "Die anderen verlassen sich auf mich. Ich werde sie nicht enttäuschen. Hört Ihr das? Die Erde erhebt Einspruch.", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; reißt die Arme auseinander und lässt einen dumpfen Schlag durch die Reihen grollen.*" },
        CLEAVE = { "Erst das Gelände lesen, dann den Angriff führen. Wer nebeneinander antritt, teilt sich auch die Probleme.", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; schwingt die Waffe in einem breiten Bogen quer durch den Kampfraum.*", "Haltung bewahren. Auch wenn keiner mehr zusieht. Ich hoffe, Ihr habt alle genug Abstand. Ich nicht.", "*richtet das abgewetzte Wappen auf dem Schild aus; dreht auf der Ferse und nimmt den Schwung in den nächsten Bogen mit.*" },
        EXECUTE = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Ich habe Euch jede Gelegenheit zum Rückzug gelassen.", "*richtet das abgewetzte Wappen auf dem Schild aus; wartet einen Herzschlag ab und führt dann einen endgültig wirkenden Hieb.*", "Ein Schlachtplan lebt länger, wenn ihn jemand verteidigt. Jetzt wird nicht mehr verhandelt.", "*prüft mit kurzem Blick die Stellung der Verbündeten; fasst den Griff fester und schließt die letzte Lücke.*" },
        SUNDER_ARMOR = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Schöner Harnisch. Schade um die Nieten.", "*prüft mit kurzem Blick die Stellung der Verbündeten; setzt die Waffe gezielt an einer lockeren Rüstungskante an.*", "Unter dieser Rüstung steckt noch ein Versprechen. Teurer Stahl ist noch keine gute Deckung.", "*strafft einen Lederriemen am Unterarm; zieht mit der Schneide eine Linie entlang einer Naht im Metall.*" },
        SHIELD_BLOCK = { "Die Linie gehört uns, solange wir zusammenstehen. Da müsst Ihr schon anklopfen. Der Schild bleibt zu.", "*strafft einen Lederriemen am Unterarm; dreht die Schildkante in den kommenden Schlag und federt ihn ab.*", "Die anderen verlassen sich auf mich. Ich werde sie nicht enttäuschen. Ein gutes Schild hört zu, bevor es antwortet.", "*nickt einem Kameraden knapp zu; stemmt die Stiefel in den Boden und lässt die Deckung nicht nachgeben.*" },
        SHIELD_BASH = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Psst. Mal sehen, ob ich Euren Zauber unterbrechen kann.", "*nickt einem Kameraden knapp zu; rammt die Schildfläche nach vorn, genau zwischen zwei Silben.*", "Haltung bewahren. Auch wenn keiner mehr zusieht. Meine Antwort auf Magie hat einen Holzgriff.", "*setzt den Helm mit routiniertem Griff gerade; rückt einen Schritt heran und stößt unvermittelt mit dem Schild zu.*" },
        TAUNT = { "Diese Leute stehen unter meinem Schutz. Das ist keine Einladung zur Diskussion.", "*setzt den Helm mit routiniertem Griff gerade; klopft mit dem Schwertknauf dreimal provokant auf den Schild.*", "Ein Schlachtplan lebt länger, wenn ihn jemand verteidigt. Die anderen haben Wichtigeres zu tun. Ich nicht.", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; tritt demonstrativ aus der Reihe und winkt die Gegner heran.*" },
        BATTLE_SHOUT = { "Heute marschieren wir nicht für ein Banner, sondern füreinander!", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; schlägt den Schwertknauf im Takt gegen den Schildrand.*", "Unter dieser Rüstung steckt noch ein Versprechen. Ihr habt Beine zum Stehen und Herzen zum Durchhalten. Nutzt beides!", "*richtet das abgewetzte Wappen auf dem Schild aus; richtet sich vor den Verbündeten auf und hebt die Klinge hoch.*" },
        DEMORALIZING_SHOUT = { "Eine Stimme muss manchmal ein ganzes Banner ersetzen. Die Ersten von Euch zittern schon. Die Letzten merken es gleich!", "*richtet das abgewetzte Wappen auf dem Schild aus; lässt einen tiefen, rauen Schlachtruf aus voller Brust erschallen.*", "Die anderen verlassen sich auf mich. Ich werde sie nicht enttäuschen. Schaut Euch um. Für wen wollt Ihr eigentlich noch kämpfen?", "*prüft mit kurzem Blick die Stellung der Verbündeten; zeigt mit der Klinge auf die wankende feindliche Linie.*" },
        REVENGE = { "In meiner Ausbildung nannte man das eine Lehrstunde.", "*prüft mit kurzem Blick die Stellung der Verbündeten; lenkt die Waffe ab und fährt in die entstandene Lücke.*", "Haltung bewahren. Auch wenn keiner mehr zusieht. Ich vergesse Gesichter. Schläge nicht.", "*strafft einen Lederriemen am Unterarm; dreht sich aus der Abwehr direkt in den Gegenangriff.*" },
        OVERPOWER = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Da war eine Lücke. Ihr habt sie mir geschenkt.", "*strafft einen Lederriemen am Unterarm; gleitet an der vorbeigehenden Waffe vorbei und nutzt den offenen Winkel.*", "Ein Schlachtplan lebt länger, wenn ihn jemand verteidigt. Wer danebenhaut, lädt mich ein.", "*nickt einem Kameraden knapp zu; nutzt eine missratene Bewegung für einen schnellen Gegenstoß.*" },
        MORTAL_STRIKE = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Ich spare mir den zweiten Versuch.", "*nickt einem Kameraden knapp zu; nimmt die Waffe fest in beide Hände und legt den ganzen Körper in einen einzigen Schlag.*", "Unter dieser Rüstung steckt noch ein Versprechen. Manche Duelle enden mit einem Satz. Dieses nicht.", "*setzt den Helm mit routiniertem Griff gerade; schreitet voran und führt den Stahl mit unerbittlicher Präzision.*" },
        WHIRLWIND = { "Erst das Gelände lesen, dann den Angriff führen. Stellt Euch ruhig im Kreis auf. Es ist praktisch.", "*setzt den Helm mit routiniertem Griff gerade; dreht sich mitsamt der Waffe durch eine Schneise im Gedränge.*", "Die anderen verlassen sich auf mich. Ich werde sie nicht enttäuschen. Ich teile gern. Heute Stahl.", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; lässt die Klinge in weitem Schwung ringsum singen.*" },
        BLOODTHIRST = { "Zorn ohne Disziplin trifft die Falschen. Der Puls wird schneller. Die Hand bleibt ruhig.", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; atmet scharf aus, reißt die Waffe hoch und setzt unerbittlich nach.*", "Haltung bewahren. Auch wenn keiner mehr zusieht. Nur weil ich zornig bin, bin ich noch lange nicht ungenau.", "*richtet das abgewetzte Wappen auf dem Schild aus; treibt mit wilden Augen, aber kontrolliertem Griff den Angriff voran.*" },
        INTERCEPT = { "Befehle sind gut. Vorangehen ist besser. Ein Vorsprung ist nur geliehene Zeit.", "*richtet das abgewetzte Wappen auf dem Schild aus; stürzt seitlich aus dem Kampfgetümmel und schneidet den Weg ab.*", "Ein Schlachtplan lebt länger, wenn ihn jemand verteidigt. Ihr rennt? Wie aufmerksam, ich wollte mich ohnehin bewegen.", "*prüft mit kurzem Blick die Stellung der Verbündeten; stößt sich aus dem Stand ab und landet mitten in der Fluchtlinie.*" },
        PUMMEL = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Zu viele Worte. Zu wenig Deckung.", "*prüft mit kurzem Blick die Stellung der Verbündeten; stört die Zauberbewegung mit einem raschen, gezielten Stoß.*", "Unter dieser Rüstung steckt noch ein Versprechen. Wolltet Ihr noch etwas sagen? Nein? Gut.", "*strafft einen Lederriemen am Unterarm; bringt den gegnerischen Arm mit einem knappen Schlag aus dem Takt.*" },
        SWEEPING_STRIKES = { "Erst das Gelände lesen, dann den Angriff führen. Wenn schon Arbeit, dann richtig.", "*strafft einen Lederriemen am Unterarm; lässt den ersten Hieb in einen zweiten Bogen übergehen.*", "Die anderen verlassen sich auf mich. Ich werde sie nicht enttäuschen. Mehrere Gegner? Spart Wege.", "*nickt einem Kameraden knapp zu; nimmt den Schwung nicht zurück, sondern führt ihn durch das Getümmel weiter.*" },
        DEATH_WISH = { "Zorn ohne Disziplin trifft die Falschen. Die Vernunft hat gesprochen. Ich habe ihr widersprochen.", "*nickt einem Kameraden knapp zu; lockert den Griff für einen Augenblick und stürzt sich entschlossen nach vorn.*", "Haltung bewahren. Auch wenn keiner mehr zusieht. Ich weiß, was ich riskiere. Die anderen vielleicht nicht.", "*setzt den Helm mit routiniertem Griff gerade; wirft einen letzten Blick auf die eigene Deckung und entscheidet sich für den Angriff.*" },
        RECKLESSNESS = { "Zorn ohne Disziplin trifft die Falschen. Vorsicht war gestern. Heute wird gehandelt.", "*setzt den Helm mit routiniertem Griff gerade; verliert jede Zurückhaltung, ohne die Waffe aus der Hand zu lassen.*", "Ein Schlachtplan lebt länger, wenn ihn jemand verteidigt. Morgen darf man mich dafür ausschimpfen. Wenn wir ein Morgen haben.", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; setzt den ganzen Körper in eine wilde Folge von Angriffen.*" },
        LAST_STAND = { "Eine Linie ist erst verloren, wenn der letzte Mensch sie aufgibt.", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; stemmt sich mühsam auf und hebt den Schild noch einmal.*", "Unter dieser Rüstung steckt noch ein Versprechen. Ich stehe noch. Das muss als Antwort genügen.", "*richtet das abgewetzte Wappen auf dem Schild aus; stellt sich trotz zitternder Beine erneut schützend in die Bresche.*" },
        SHIELD_WALL = { "Die Linie gehört uns, solange wir zusammenstehen. Hinter mir. Keine Heldentaten auf eigene Rechnung!", "*richtet das abgewetzte Wappen auf dem Schild aus; zieht das Schild dicht heran und verhakt die Schulter in der Linie.*", "Die anderen verlassen sich auf mich. Ich werde sie nicht enttäuschen. Wer durch mich hindurch will, braucht einen langen Atem.", "*prüft mit kurzem Blick die Stellung der Verbündeten; schließt die letzte Lücke zwischen Schild und Rüstung.*" },
        RETALIATION = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Wer austeilt, muss das Echo mögen.", "*prüft mit kurzem Blick die Stellung der Verbündeten; öffnet die Deckung einen Spalt und beantwortet jeden Angriff mit Stahl.*", "Haltung bewahren. Auch wenn keiner mehr zusieht. Kommt nur. Ich habe für jeden einen Augenblick übrig.", "*strafft einen Lederriemen am Unterarm; legt die Füße breit und wartet auf die ersten ungeduldigen Hiebe.*" },
        MOCKING_BLOW = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Seid Ihr tatsächlich gefährlich oder nur besonders laut?", "*strafft einen Lederriemen am Unterarm; lässt die Spitze absichtlich zu tief sinken und lockt den Gegner näher.*", "Ein Schlachtplan lebt länger, wenn ihn jemand verteidigt. Oh, verzeiht. Ich hatte Euch für einen Übungsgegner gehalten.", "*nickt einem Kameraden knapp zu; setzt einen frechen Hieb und grinst hinter dem Schild hervor.*" },
        BERSERKER_RAGE = { "Zorn ohne Disziplin trifft die Falschen. Angst? Die hat heute keinen Platz in meinem Kopf.", "*nickt einem Kameraden knapp zu; schüttelt die Schultern aus, als würde eine unsichtbare Last abfallen.*", "Unter dieser Rüstung steckt noch ein Versprechen. Meine Furcht darf draußen warten. Meine Wut kommt mit.", "*setzt den Helm mit routiniertem Griff gerade; stößt die Luft aus, strafft den Nacken und hält den Blick fest.*" },
        BLOODRAGE = { "Zorn ohne Disziplin trifft die Falschen. Schmerz ist eine Nachricht. Ich antworte später.", "*setzt den Helm mit routiniertem Griff gerade; schlägt die Faust gegen die Brust und sammelt neuen Kampfeswillen.*", "Die anderen verlassen sich auf mich. Ich werde sie nicht enttäuschen. Das Herz schlägt. Mehr muss es gerade nicht erklären.", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; beißt die Zähne zusammen und spannt die Schultern unter der Rüstung.*" },
        DISARM = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Ihr habt ein schönes Schwert. Darf ich es kurz sehen?", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; versucht, die gegnerische Waffe mit einer knappen Drehung aus der Hand zu hebeln.*", "Haltung bewahren. Auch wenn keiner mehr zusieht. Mal sehen, ob Ihr auch ohne Waffe so gesprächig seid.", "*richtet das abgewetzte Wappen auf dem Schild aus; versucht, den Griff der gegnerischen Waffe abzufangen und aus der Linie zu drehen.*" },
        INTIMIDATING_SHOUT = { "Eine Stimme muss manchmal ein ganzes Banner ersetzen. Lauft, solange Ihr noch wisst, wohin!", "*richtet das abgewetzte Wappen auf dem Schild aus; schleudert einen wilden Schrei über die Köpfe der Gegner hinweg.*", "Ein Schlachtplan lebt länger, wenn ihn jemand verteidigt. Das war die freundliche Warnung. Die zweite kommt mit Stahl.", "*prüft mit kurzem Blick die Stellung der Verbündeten; schlägt donnernd gegen den Schild und bleckt die Zähne.*" },
        CHALLENGING_SHOUT = { "Eine Stimme muss manchmal ein ganzes Banner ersetzen. ALLE ZU MIR! Ich habe Platz für Euren ganzen Ärger!", "*prüft mit kurzem Blick die Stellung der Verbündeten; reißt beide Arme auseinander und fordert die feindliche Reihe heraus.*", "Unter dieser Rüstung steckt noch ein Versprechen. Lasst die anderen in Ruhe. Ich bin heute Euer Problem!", "*strafft einen Lederriemen am Unterarm; schlägt mehrmals auf den Schild und brüllt die Gegner an.*" },
        SLAM = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Das ist kein Hammer. Es fühlt sich gleich aber so an.", "*strafft einen Lederriemen am Unterarm; holt über die Schulter aus und lässt den Stahl mit voller Kraft niederfahren.*", "Die anderen verlassen sich auf mich. Ich werde sie nicht enttäuschen. Lieber ein sauberer Treffer als fünf halbe.", "*nickt einem Kameraden knapp zu; lässt die Waffe nach kurzem Zögern mit dem ganzen Gewicht folgen.*" },
        DEVASTATE = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Schon locker? Dann lösen wir den Rest auch noch.", "*nickt einem Kameraden knapp zu; schlägt hart auf eine bereits angeschlagene Stelle der Rüstung.*", "Haltung bewahren. Auch wenn keiner mehr zusieht. Ich sehe, der Schmied hat an der falschen Stelle gespart.", "*setzt den Helm mit routiniertem Griff gerade; klopft prüfend gegen die offene Fuge und setzt entschlossen nach.*" },
        SHIELD_SLAM = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Ein Schild kann auch Türen schließen. Auf Nasenhöhe.", "*setzt den Helm mit routiniertem Griff gerade; reißt den Schild aus der Deckung und stößt dessen Kante kraftvoll nach vorn.*", "Ein Schlachtplan lebt länger, wenn ihn jemand verteidigt. Wer sagt, Verteidigung sei höflich?", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; macht einen kurzen Satz vorwärts und lässt den Schild sprechen.*" },
        CONCUSSION_BLOW = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Ich versuche, Euch aus dem Takt zu bringen.", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; versucht, einen schweren Hieb in die Lücke zwischen zwei Bewegungen zu führen.*", "Unter dieser Rüstung steckt noch ein Versprechen. Ich versuche, allen einen Augenblick Ruhe zu verschaffen.", "*richtet das abgewetzte Wappen auf dem Schild aus; verkürzt den Griff und schwingt mit überraschender Wucht.*" },
        VICTORY_RUSH = { "Befehle sind gut. Vorangehen ist besser. Einer weniger. Die anderen stehen noch.", "*richtet das abgewetzte Wappen auf dem Schild aus; nutzt den gewonnenen Atemzug, richtet sich auf und prescht weiter.*", "Die anderen verlassen sich auf mich. Ich werde sie nicht enttäuschen. Feiern können wir später. Da bewegt sich noch etwas.", "*prüft mit kurzem Blick die Stellung der Verbündeten; klopft sich einmal auf die Brust und setzt sofort nach.*" },
        BATTLE_STANCE = { "Erst das Gelände lesen, dann den Angriff führen. Zwischen Mut und Dummheit liegen manchmal nur zwei Fußbreit.", "*prüft mit kurzem Blick die Stellung der Verbündeten; setzt die Stiefel schulterbreit auf und lässt die Waffe locker kreisen.*", "Haltung bewahren. Auch wenn keiner mehr zusieht. Ich bleibe beweglich. Der Rest darf sich entscheiden.", "*strafft einen Lederriemen am Unterarm; wiegt das Gewicht zwischen Schildarm und Waffenhand aus.*" },
        DEFENSIVE_STANCE = { "Die Linie gehört uns, solange wir zusammenstehen. Wer an meine Leute will, muss zuerst meinen Schild überzeugen.", "*strafft einen Lederriemen am Unterarm; stellt die Beine breit und hält den Schild vor die Verbündeten.*", "Ein Schlachtplan lebt länger, wenn ihn jemand verteidigt. Heute gewinnt nicht, wer am lautesten brüllt.", "*nickt einem Kameraden knapp zu; senkt den Schwerpunkt und wird hinter der Deckung nahezu unbeweglich.*" },
        BERSERKER_STANCE = { "Zorn ohne Disziplin trifft die Falschen. Wer behauptet, Wut mache blind, hat nie richtig hingesehen.", "*nickt einem Kameraden knapp zu; atmet tief ein, hebt das Kinn und nimmt eine wilde Haltung ein.*", "Unter dieser Rüstung steckt noch ein Versprechen. Die Welt wird plötzlich sehr einfach: vorwärts.", "*setzt den Helm mit routiniertem Griff gerade; lockert die Schultern, lässt die Waffe sinken und reißt sie schlagartig hoch.*" },
        PIERCING_HOWL = { "Eine Stimme muss manchmal ein ganzes Banner ersetzen. Wenn Ihr den Ruf hört, seid Ihr schon zu nah.", "*setzt den Helm mit routiniertem Griff gerade; heult so durchdringend, dass die Stimmen umher für einen Moment verstummen.*", "Die anderen verlassen sich auf mich. Ich werde sie nicht enttäuschen. Nein, das war kein Wolfsrudel. Nur ich.", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; wirft den Kopf zurück und lässt einen rauen, langen Laut los.*" },
        SPEARING_STRIKE = { "Die Ausbildung war streng. Jetzt zahlt sie sich aus. Die Lücke ist schmal. Meine Spitze nicht.", "*fährt mit dem Daumen über eine alte Kerbe im Schwertgriff; führt die Waffe mit einem einzigen geraden Schritt nach vorn.*", "Haltung bewahren. Auch wenn keiner mehr zusieht. Rüstung ist stark. Winkel sind stärker.", "*richtet das abgewetzte Wappen auf dem Schild aus; dreht das Handgelenk, zielt auf die Schwachstelle und stößt vor.*" },
        TACTICAL_MASTERY = { "Erst das Gelände lesen, dann den Angriff führen. Der Unterschied zwischen Mut und Übermut ist eine gute Fußstellung.", "*richtet das abgewetzte Wappen auf dem Schild aus; verändert unmerklich den Stand und bewahrt die Übersicht.*", "Ein Schlachtplan lebt länger, wenn ihn jemand verteidigt. Ein Schlachtfeld ist kein Würfelspiel. Es wird gelesen.", "*prüft mit kurzem Blick die Stellung der Verbündeten; mustert Wege, Gegner und Rückzugsräume, ohne die Waffe zu senken.*" },
    },
    DWARF = {
        HEROIC_STRIKE = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Wisst Ihr, warum meine Waffe so schwer ist? Sie widerspricht selten.", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; verlegt das Gewicht auf den vorderen Fuß und führt einen wuchtigen Hieb.*", "Nachher reden wir bei einem Humpen darüber. Vielleicht. Es gibt Argumente, die brauchen keinen zweiten Satz.", "*spuckt entschlossen in die behandschuhten Hände; schiebt die Schulter nach und lässt den Stahl sprechen.*" },
        CHARGE = { "Der Weg ist kurz, die Rechnung einfach: Ihr steht im Weg!", "*senkt die gepanzerte Schulter und stürmt mit donnernden Stiefeln vor.*", "Ein Amboss beschwert sich auch nicht, wenn man ordentlich trifft. Ich komme! Das ist keine Warnung, sondern eine Wegbeschreibung!", "*rückt den Helm tief über die buschigen Brauen; prescht mit einem lauten Scheppern durch die Lücke in der Reihe.*" },
        REND = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Rüstungsnähte sind kleine Geheimnisse. Ich bin neugierig.", "*rückt den Helm tief über die buschigen Brauen; führt die Schneide schräg über eine schlecht geschützte Stelle.*", "Wacklige Knie? Nicht in dieser Familie. Ein Schneider wäre entsetzt. Ich bin zufrieden.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; zieht die Klinge rasch zurück und sucht die nächste Öffnung.*" },
        HAMSTRING = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Weglaufen? Das ist ein Plan mit Schwächen.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; taucht tief unter der gegnerischen Deckung hindurch.*", "Der Stein erinnert sich an jeden, der vor ihm nachgab. Ich schlage nicht gern zweimal hinterher. Einmal genügt.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; führt die Waffe knapp über den Boden und richtet sich sofort wieder auf.*" },
        THUNDER_CLAP = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Wenn der Boden bebt, brauchen wir keinen Trommler mehr.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; stampft mit solcher Wucht auf, dass Staub vom Boden springt.*", "Nachher reden wir bei einem Humpen darüber. Vielleicht. Hört Ihr das? Die Erde erhebt Einspruch.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; reißt die Arme auseinander und lässt einen dumpfen Schlag durch die Reihen grollen.*" },
        CLEAVE = { "Mein Großvater nannte das gesunden Bergverstand. Wer nebeneinander antritt, teilt sich auch die Probleme.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; schwingt die Waffe in einem breiten Bogen quer durch den Kampfraum.*", "Ein Amboss beschwert sich auch nicht, wenn man ordentlich trifft. Ich hoffe, Ihr habt alle genug Abstand. Ich nicht.", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; dreht auf der Ferse und nimmt den Schwung in den nächsten Bogen mit.*" },
        EXECUTE = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Ich habe Euch jede Gelegenheit zum Rückzug gelassen.", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; wartet einen Herzschlag ab und führt dann einen endgültig wirkenden Hieb.*", "Wacklige Knie? Nicht in dieser Familie. Jetzt wird nicht mehr verhandelt.", "*spuckt entschlossen in die behandschuhten Hände; fasst den Griff fester und schließt die letzte Lücke.*" },
        SUNDER_ARMOR = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Schöner Harnisch. Schade um die Nieten.", "*spuckt entschlossen in die behandschuhten Hände; setzt die Waffe gezielt an einer lockeren Rüstungskante an.*", "Der Stein erinnert sich an jeden, der vor ihm nachgab. Teurer Stahl ist noch keine gute Deckung.", "*rückt den Helm tief über die buschigen Brauen; zieht mit der Schneide eine Linie entlang einer Naht im Metall.*" },
        SHIELD_BLOCK = { "Ein Fels fragt nicht, wie stark der Sturm ist. Da müsst Ihr schon anklopfen. Der Schild bleibt zu.", "*rückt den Helm tief über die buschigen Brauen; dreht die Schildkante in den kommenden Schlag und federt ihn ab.*", "Nachher reden wir bei einem Humpen darüber. Vielleicht. Ein gutes Schild hört zu, bevor es antwortet.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; stemmt die Stiefel in den Boden und lässt die Deckung nicht nachgeben.*" },
        SHIELD_BASH = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Psst. Mal sehen, ob ich Euren Zauber unterbrechen kann.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; rammt die Schildfläche nach vorn, genau zwischen zwei Silben.*", "Ein Amboss beschwert sich auch nicht, wenn man ordentlich trifft. Meine Antwort auf Magie hat einen Holzgriff.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; rückt einen Schritt heran und stößt unvermittelt mit dem Schild zu.*" },
        TAUNT = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Hier drüben! Der Ärger hat heute meinen Namen.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; klopft mit dem Schwertknauf dreimal provokant auf den Schild.*", "Wacklige Knie? Nicht in dieser Familie. Die anderen haben Wichtigeres zu tun. Ich nicht.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; tritt demonstrativ aus der Reihe und winkt die Gegner heran.*" },
        BATTLE_SHOUT = { "Wer nach dem Kampf noch steht, kriegt mein letztes Fass. Also fast.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; schlägt den Schwertknauf im Takt gegen den Schildrand.*", "Der Stein erinnert sich an jeden, der vor ihm nachgab. Ihr habt Beine zum Stehen und Herzen zum Durchhalten. Nutzt beides!", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; richtet sich vor den Verbündeten auf und hebt die Klinge hoch.*" },
        DEMORALIZING_SHOUT = { "Wer das in der Taverne nicht hört, ist selbst schuld! Die Ersten von Euch zittern schon. Die Letzten merken es gleich!", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; lässt einen tiefen, rauen Schlachtruf aus voller Brust erschallen.*", "Nachher reden wir bei einem Humpen darüber. Vielleicht. Schaut Euch um. Für wen wollt Ihr eigentlich noch kämpfen?", "*spuckt entschlossen in die behandschuhten Hände; zeigt mit der Klinge auf die wankende feindliche Linie.*" },
        REVENGE = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Danke für die Gelegenheit. Die kommt sofort zurück.", "*spuckt entschlossen in die behandschuhten Hände; lenkt die Waffe ab und fährt in die entstandene Lücke.*", "Ein Amboss beschwert sich auch nicht, wenn man ordentlich trifft. Ich vergesse Gesichter. Schläge nicht.", "*rückt den Helm tief über die buschigen Brauen; dreht sich aus der Abwehr direkt in den Gegenangriff.*" },
        OVERPOWER = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Da war eine Lücke. Ihr habt sie mir geschenkt.", "*rückt den Helm tief über die buschigen Brauen; gleitet an der vorbeigehenden Waffe vorbei und nutzt den offenen Winkel.*", "Wacklige Knie? Nicht in dieser Familie. Wer danebenhaut, lädt mich ein.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; nutzt eine missratene Bewegung für einen schnellen Gegenstoß.*" },
        MORTAL_STRIKE = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Ich spare mir den zweiten Versuch.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; nimmt die Waffe fest in beide Hände und legt den ganzen Körper in einen einzigen Schlag.*", "Der Stein erinnert sich an jeden, der vor ihm nachgab. Manche Duelle enden mit einem Satz. Dieses nicht.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; schreitet voran und führt den Stahl mit unerbittlicher Präzision.*" },
        WHIRLWIND = { "Mein Großvater nannte das gesunden Bergverstand. Stellt Euch ruhig im Kreis auf. Es ist praktisch.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; dreht sich mitsamt der Waffe durch eine Schneise im Gedränge.*", "Nachher reden wir bei einem Humpen darüber. Vielleicht. Ich teile gern. Heute Stahl.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; lässt die Klinge in weitem Schwung ringsum singen.*" },
        BLOODTHIRST = { "Der Zorn sitzt tief. Ungefähr auf Bierfasshöhe. Der Puls wird schneller. Die Hand bleibt ruhig.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; atmet scharf aus, reißt die Waffe hoch und setzt unerbittlich nach.*", "Ein Amboss beschwert sich auch nicht, wenn man ordentlich trifft. Nur weil ich zornig bin, bin ich noch lange nicht ungenau.", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; treibt mit wilden Augen, aber kontrolliertem Griff den Angriff voran.*" },
        INTERCEPT = { "Diese Stiefel kennen nur eine Richtung: vorwärts. Ein Vorsprung ist nur geliehene Zeit.", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; stürzt seitlich aus dem Kampfgetümmel und schneidet den Weg ab.*", "Wacklige Knie? Nicht in dieser Familie. Ihr rennt? Wie aufmerksam, ich wollte mich ohnehin bewegen.", "*spuckt entschlossen in die behandschuhten Hände; stößt sich aus dem Stand ab und landet mitten in der Fluchtlinie.*" },
        PUMMEL = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Zu viele Worte. Zu wenig Deckung.", "*spuckt entschlossen in die behandschuhten Hände; stört die Zauberbewegung mit einem raschen, gezielten Stoß.*", "Der Stein erinnert sich an jeden, der vor ihm nachgab. Wolltet Ihr noch etwas sagen? Nein? Gut.", "*rückt den Helm tief über die buschigen Brauen; bringt den gegnerischen Arm mit einem knappen Schlag aus dem Takt.*" },
        SWEEPING_STRIKES = { "Mein Großvater nannte das gesunden Bergverstand. Wenn schon Arbeit, dann richtig.", "*rückt den Helm tief über die buschigen Brauen; lässt den ersten Hieb in einen zweiten Bogen übergehen.*", "Nachher reden wir bei einem Humpen darüber. Vielleicht. Mehrere Gegner? Spart Wege.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; nimmt den Schwung nicht zurück, sondern führt ihn durch das Getümmel weiter.*" },
        DEATH_WISH = { "Der Zorn sitzt tief. Ungefähr auf Bierfasshöhe. Die Vernunft hat gesprochen. Ich habe ihr widersprochen.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; lockert den Griff für einen Augenblick und stürzt sich entschlossen nach vorn.*", "Ein Amboss beschwert sich auch nicht, wenn man ordentlich trifft. Ich weiß, was ich riskiere. Die anderen vielleicht nicht.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; wirft einen letzten Blick auf die eigene Deckung und entscheidet sich für den Angriff.*" },
        RECKLESSNESS = { "Der Zorn sitzt tief. Ungefähr auf Bierfasshöhe. Vorsicht war gestern. Heute wird gehandelt.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; verliert jede Zurückhaltung, ohne die Waffe aus der Hand zu lassen.*", "Wacklige Knie? Nicht in dieser Familie. Morgen darf man mich dafür ausschimpfen. Wenn wir ein Morgen haben.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; setzt den ganzen Körper in eine wilde Folge von Angriffen.*" },
        LAST_STAND = { "Ein Fels fragt nicht, wie stark der Sturm ist. Bis hierher und keinen Schritt weiter.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; stemmt sich mühsam auf und hebt den Schild noch einmal.*", "Der Stein erinnert sich an jeden, der vor ihm nachgab. Ich stehe noch. Das muss als Antwort genügen.", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; stellt sich trotz zitternder Beine erneut schützend in die Bresche.*" },
        SHIELD_WALL = { "Diese Mauer ist älter als Euer Stammbaum und hält besser!", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; zieht das Schild dicht heran und verhakt die Schulter in der Linie.*", "Nachher reden wir bei einem Humpen darüber. Vielleicht. Wer durch mich hindurch will, braucht einen langen Atem.", "*spuckt entschlossen in die behandschuhten Hände; schließt die letzte Lücke zwischen Schild und Rüstung.*" },
        RETALIATION = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Wer austeilt, muss das Echo mögen.", "*spuckt entschlossen in die behandschuhten Hände; öffnet die Deckung einen Spalt und beantwortet jeden Angriff mit Stahl.*", "Ein Amboss beschwert sich auch nicht, wenn man ordentlich trifft. Kommt nur. Ich habe für jeden einen Augenblick übrig.", "*rückt den Helm tief über die buschigen Brauen; legt die Füße breit und wartet auf die ersten ungeduldigen Hiebe.*" },
        MOCKING_BLOW = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Seid Ihr tatsächlich gefährlich oder nur besonders laut?", "*rückt den Helm tief über die buschigen Brauen; lässt die Spitze absichtlich zu tief sinken und lockt den Gegner näher.*", "Wacklige Knie? Nicht in dieser Familie. Oh, verzeiht. Ich hatte Euch für einen Übungsgegner gehalten.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; setzt einen frechen Hieb und grinst hinter dem Schild hervor.*" },
        BERSERKER_RAGE = { "Beim Amboss! Wer hat mein letztes Bier ausgetrunken?", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; schüttelt die Schultern aus, als würde eine unsichtbare Last abfallen.*", "Der Stein erinnert sich an jeden, der vor ihm nachgab. Meine Furcht darf draußen warten. Meine Wut kommt mit.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; stößt die Luft aus, strafft den Nacken und hält den Blick fest.*" },
        BLOODRAGE = { "Der Zorn sitzt tief. Ungefähr auf Bierfasshöhe. Schmerz ist eine Nachricht. Ich antworte später.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; schlägt die Faust gegen die Brust und sammelt neuen Kampfeswillen.*", "Nachher reden wir bei einem Humpen darüber. Vielleicht. Das Herz schlägt. Mehr muss es gerade nicht erklären.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; beißt die Zähne zusammen und spannt die Schultern unter der Rüstung.*" },
        DISARM = { "Euer Schwert ist hübsch. Mein Schmied hätte es trotzdem gerichtet.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; versucht, die gegnerische Waffe mit einer knappen Drehung aus der Hand zu hebeln.*", "Ein Amboss beschwert sich auch nicht, wenn man ordentlich trifft. Mal sehen, ob Ihr auch ohne Waffe so gesprächig seid.", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; versucht, den Griff der gegnerischen Waffe abzufangen und aus der Linie zu drehen.*" },
        INTIMIDATING_SHOUT = { "Wer das in der Taverne nicht hört, ist selbst schuld! Lauft, solange Ihr noch wisst, wohin!", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; schleudert einen wilden Schrei über die Köpfe der Gegner hinweg.*", "Wacklige Knie? Nicht in dieser Familie. Das war die freundliche Warnung. Die zweite kommt mit Stahl.", "*spuckt entschlossen in die behandschuhten Hände; schlägt donnernd gegen den Schild und bleckt die Zähne.*" },
        CHALLENGING_SHOUT = { "Wer das in der Taverne nicht hört, ist selbst schuld! ALLE ZU MIR! Ich habe Platz für Euren ganzen Ärger!", "*spuckt entschlossen in die behandschuhten Hände; reißt beide Arme auseinander und fordert die feindliche Reihe heraus.*", "Der Stein erinnert sich an jeden, der vor ihm nachgab. Lasst die anderen in Ruhe. Ich bin heute Euer Problem!", "*rückt den Helm tief über die buschigen Brauen; schlägt mehrmals auf den Schild und brüllt die Gegner an.*" },
        SLAM = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Das ist kein Hammer. Es fühlt sich gleich aber so an.", "*rückt den Helm tief über die buschigen Brauen; holt über die Schulter aus und lässt den Stahl mit voller Kraft niederfahren.*", "Nachher reden wir bei einem Humpen darüber. Vielleicht. Lieber ein sauberer Treffer als fünf halbe.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; lässt die Waffe nach kurzem Zögern mit dem ganzen Gewicht folgen.*" },
        DEVASTATE = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Schon locker? Dann lösen wir den Rest auch noch.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; schlägt hart auf eine bereits angeschlagene Stelle der Rüstung.*", "Ein Amboss beschwert sich auch nicht, wenn man ordentlich trifft. Ich sehe, der Schmied hat an der falschen Stelle gespart.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; klopft prüfend gegen die offene Fuge und setzt entschlossen nach.*" },
        SHIELD_SLAM = { "Dieser Schild hat mehr Kämpfe gesehen als Ihr Winter. Jetzt sieht er Euch.", "*reißt den Schild aus der Deckung und rammt den Rand nach vorn.*", "Wacklige Knie? Nicht in dieser Familie. Wer sagt, Verteidigung sei höflich?", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; macht einen kurzen Satz vorwärts und lässt den Schild sprechen.*" },
        CONCUSSION_BLOW = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Ich versuche, Euch aus dem Takt zu bringen.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; versucht, einen schweren Hieb in die Lücke zwischen zwei Bewegungen zu führen.*", "Der Stein erinnert sich an jeden, der vor ihm nachgab. Ich versuche, allen einen Augenblick Ruhe zu verschaffen.", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; verkürzt den Griff und schwingt mit überraschender Wucht.*" },
        VICTORY_RUSH = { "Diese Stiefel kennen nur eine Richtung: vorwärts. Einer weniger. Die anderen stehen noch.", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; nutzt den gewonnenen Atemzug, richtet sich auf und prescht weiter.*", "Nachher reden wir bei einem Humpen darüber. Vielleicht. Feiern können wir später. Da bewegt sich noch etwas.", "*spuckt entschlossen in die behandschuhten Hände; klopft sich einmal auf die Brust und setzt sofort nach.*" },
        BATTLE_STANCE = { "Mein Großvater nannte das gesunden Bergverstand. Zwischen Mut und Dummheit liegen manchmal nur zwei Fußbreit.", "*spuckt entschlossen in die behandschuhten Hände; setzt die Stiefel schulterbreit auf und lässt die Waffe locker kreisen.*", "Ein Amboss beschwert sich auch nicht, wenn man ordentlich trifft. Ich bleibe beweglich. Der Rest darf sich entscheiden.", "*rückt den Helm tief über die buschigen Brauen; wiegt das Gewicht zwischen Schildarm und Waffenhand aus.*" },
        DEFENSIVE_STANCE = { "Ein Fels fragt nicht, wie stark der Sturm ist. Wer an meine Leute will, muss zuerst meinen Schild überzeugen.", "*rückt den Helm tief über die buschigen Brauen; stellt die Beine breit und hält den Schild vor die Verbündeten.*", "Wacklige Knie? Nicht in dieser Familie. Heute gewinnt nicht, wer am lautesten brüllt.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; senkt den Schwerpunkt und wird hinter der Deckung nahezu unbeweglich.*" },
        BERSERKER_STANCE = { "Der Zorn sitzt tief. Ungefähr auf Bierfasshöhe. Wer behauptet, Wut mache blind, hat nie richtig hingesehen.", "*stemmt die Stiefel wie gegen einen Hang im Gebirge; atmet tief ein, hebt das Kinn und nimmt eine wilde Haltung ein.*", "Der Stein erinnert sich an jeden, der vor ihm nachgab. Die Welt wird plötzlich sehr einfach: vorwärts.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; lockert die Schultern, lässt die Waffe sinken und reißt sie schlagartig hoch.*" },
        PIERCING_HOWL = { "Wer das in der Taverne nicht hört, ist selbst schuld! Wenn Ihr den Ruf hört, seid Ihr schon zu nah.", "*streicht sich eine verirrte Bartsträhne aus dem Gesicht; heult so durchdringend, dass die Stimmen umher für einen Moment verstummen.*", "Nachher reden wir bei einem Humpen darüber. Vielleicht. Nein, das war kein Wolfsrudel. Nur ich.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; wirft den Kopf zurück und lässt einen rauen, langen Laut los.*" },
        SPEARING_STRIKE = { "Beim Bart meiner Großmutter, jetzt wird gearbeitet! Die Lücke ist schmal. Meine Spitze nicht.", "*schlägt mit dem Waffenknauf gegen die eigene Brustplatte; führt die Waffe mit einem einzigen geraden Schritt nach vorn.*", "Ein Amboss beschwert sich auch nicht, wenn man ordentlich trifft. Rüstung ist stark. Winkel sind stärker.", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; dreht das Handgelenk, zielt auf die Schwachstelle und stößt vor.*" },
        TACTICAL_MASTERY = { "Mein Großvater nannte das gesunden Bergverstand. Der Unterschied zwischen Mut und Übermut ist eine gute Fußstellung.", "*klopft mit dem Knöchel gegen den verbeulten Schildrand; verändert unmerklich den Stand und bewahrt die Übersicht.*", "Wacklige Knie? Nicht in dieser Familie. Ein Schlachtfeld ist kein Würfelspiel. Es wird gelesen.", "*spuckt entschlossen in die behandschuhten Hände; mustert Wege, Gegner und Rückzugsräume, ohne die Waffe zu senken.*" },
    },
    NIGHTELF = {
        HEROIC_STRIKE = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Wisst Ihr, warum meine Waffe so schwer ist? Sie widerspricht selten.", "*legt kurz zwei Finger an eine alte Blattgravur; verlegt das Gewicht auf den vorderen Fuß und führt einen wuchtigen Hieb.*", "Die Nacht hat längere Erinnerungen als diese Fehde. Es gibt Argumente, die brauchen keinen zweiten Satz.", "*lässt den Atem in einer lautlosen Bewegung entweichen; schiebt die Schulter nach und lässt den Stahl sprechen.*" },
        CHARGE = { "Der Pfad wird sichtbar, wenn man auf den Wind hört. Wenn der Weg versperrt ist, nehme ich eben den direkten.", "*lässt den Atem in einer lautlosen Bewegung entweichen; senkt die Schulter, stößt sich ab und wirbelt Staub auf.*", "Ich kämpfe nicht gegen das Gleichgewicht, sondern für es. Ich komme! Das ist keine Warnung, sondern eine Wegbeschreibung!", "*passt den Stand dem unebenen Boden an; prescht mit einem lauten Scheppern durch die Lücke in der Reihe.*" },
        REND = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Rüstungsnähte sind kleine Geheimnisse. Ich bin neugierig.", "*passt den Stand dem unebenen Boden an; führt die Schneide schräg über eine schlecht geschützte Stelle.*", "Selbst ein fallender Baum wählt seinen Weg. Ein Schneider wäre entsetzt. Ich bin zufrieden.", "*neigt den Kopf, als würde ein ferner Wald antworten; zieht die Klinge rasch zurück und sucht die nächste Öffnung.*" },
        HAMSTRING = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Weglaufen? Das ist ein Plan mit Schwächen.", "*neigt den Kopf, als würde ein ferner Wald antworten; taucht tief unter der gegnerischen Deckung hindurch.*", "Es gibt Kämpfe, die enden erst, wenn die Stille zurückkehrt. Ich schlage nicht gern zweimal hinterher. Einmal genügt.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; führt die Waffe knapp über den Boden und richtet sich sofort wieder auf.*" },
        THUNDER_CLAP = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Wenn der Boden bebt, brauchen wir keinen Trommler mehr.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; stampft mit solcher Wucht auf, dass Staub vom Boden springt.*", "Die Nacht hat längere Erinnerungen als diese Fehde. Hört Ihr das? Die Erde erhebt Einspruch.", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; reißt die Arme auseinander und lässt einen dumpfen Schlag durch die Reihen grollen.*" },
        CLEAVE = { "Geduld ist die längste Waffe, die ich trage. Wer nebeneinander antritt, teilt sich auch die Probleme.", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; schwingt die Waffe in einem breiten Bogen quer durch den Kampfraum.*", "Ich kämpfe nicht gegen das Gleichgewicht, sondern für es. Ich hoffe, Ihr habt alle genug Abstand. Ich nicht.", "*legt kurz zwei Finger an eine alte Blattgravur; dreht auf der Ferse und nimmt den Schwung in den nächsten Bogen mit.*" },
        EXECUTE = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Ich habe Euch jede Gelegenheit zum Rückzug gelassen.", "*legt kurz zwei Finger an eine alte Blattgravur; wartet einen Herzschlag ab und führt dann einen endgültig wirkenden Hieb.*", "Selbst ein fallender Baum wählt seinen Weg. Jetzt wird nicht mehr verhandelt.", "*lässt den Atem in einer lautlosen Bewegung entweichen; fasst den Griff fester und schließt die letzte Lücke.*" },
        SUNDER_ARMOR = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Schöner Harnisch. Schade um die Nieten.", "*lässt den Atem in einer lautlosen Bewegung entweichen; setzt die Waffe gezielt an einer lockeren Rüstungskante an.*", "Es gibt Kämpfe, die enden erst, wenn die Stille zurückkehrt. Teurer Stahl ist noch keine gute Deckung.", "*passt den Stand dem unebenen Boden an; zieht mit der Schneide eine Linie entlang einer Naht im Metall.*" },
        SHIELD_BLOCK = { "Die Eiche bewegt sich nicht, weil der Wind unhöflich wird.", "*passt den Stand dem unebenen Boden an; dreht die Schildkante in den kommenden Schlag und federt ihn ab.*", "Die Nacht hat längere Erinnerungen als diese Fehde. Ein gutes Schild hört zu, bevor es antwortet.", "*neigt den Kopf, als würde ein ferner Wald antworten; stemmt die Stiefel in den Boden und lässt die Deckung nicht nachgeben.*" },
        SHIELD_BASH = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Psst. Mal sehen, ob ich Euren Zauber unterbrechen kann.", "*neigt den Kopf, als würde ein ferner Wald antworten; rammt die Schildfläche nach vorn, genau zwischen zwei Silben.*", "Ich kämpfe nicht gegen das Gleichgewicht, sondern für es. Meine Antwort auf Magie hat einen Holzgriff.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; rückt einen Schritt heran und stößt unvermittelt mit dem Schild zu.*" },
        TAUNT = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Hier drüben! Der Ärger hat heute meinen Namen.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; klopft mit dem Schwertknauf dreimal provokant auf den Schild.*", "Selbst ein fallender Baum wählt seinen Weg. Die anderen haben Wichtigeres zu tun. Ich nicht.", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; tritt demonstrativ aus der Reihe und winkt die Gegner heran.*" },
        BATTLE_SHOUT = { "Mein Ruf trägt durch das Dunkel der Wälder. Schultern hoch, Reihen schließen! Heute fällt hier niemand allein!", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; schlägt den Schwertknauf im Takt gegen den Schildrand.*", "Es gibt Kämpfe, die enden erst, wenn die Stille zurückkehrt. Ihr habt Beine zum Stehen und Herzen zum Durchhalten. Nutzt beides!", "*legt kurz zwei Finger an eine alte Blattgravur; richtet sich vor den Verbündeten auf und hebt die Klinge hoch.*" },
        DEMORALIZING_SHOUT = { "Mein Ruf trägt durch das Dunkel der Wälder. Die Ersten von Euch zittern schon. Die Letzten merken es gleich!", "*legt kurz zwei Finger an eine alte Blattgravur; lässt einen tiefen, rauen Schlachtruf aus voller Brust erschallen.*", "Die Nacht hat längere Erinnerungen als diese Fehde. Schaut Euch um. Für wen wollt Ihr eigentlich noch kämpfen?", "*lässt den Atem in einer lautlosen Bewegung entweichen; zeigt mit der Klinge auf die wankende feindliche Linie.*" },
        REVENGE = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Danke für die Gelegenheit. Die kommt sofort zurück.", "*lässt den Atem in einer lautlosen Bewegung entweichen; lenkt die Waffe ab und fährt in die entstandene Lücke.*", "Ich kämpfe nicht gegen das Gleichgewicht, sondern für es. Ich vergesse Gesichter. Schläge nicht.", "*passt den Stand dem unebenen Boden an; dreht sich aus der Abwehr direkt in den Gegenangriff.*" },
        OVERPOWER = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Da war eine Lücke. Ihr habt sie mir geschenkt.", "*passt den Stand dem unebenen Boden an; gleitet an der vorbeigehenden Waffe vorbei und nutzt den offenen Winkel.*", "Selbst ein fallender Baum wählt seinen Weg. Wer danebenhaut, lädt mich ein.", "*neigt den Kopf, als würde ein ferner Wald antworten; nutzt eine missratene Bewegung für einen schnellen Gegenstoß.*" },
        MORTAL_STRIKE = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Ich spare mir den zweiten Versuch.", "*neigt den Kopf, als würde ein ferner Wald antworten; nimmt die Waffe fest in beide Hände und legt den ganzen Körper in einen einzigen Schlag.*", "Es gibt Kämpfe, die enden erst, wenn die Stille zurückkehrt. Manche Duelle enden mit einem Satz. Dieses nicht.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; schreitet voran und führt den Stahl mit unerbittlicher Präzision.*" },
        WHIRLWIND = { "Der Herbstwind fragt keine Blätter nach Erlaubnis.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; dreht sich mitsamt der Waffe durch eine Schneise im Gedränge.*", "Die Nacht hat längere Erinnerungen als diese Fehde. Ich teile gern. Heute Stahl.", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; lässt die Klinge in weitem Schwung ringsum singen.*" },
        BLOODTHIRST = { "Die Wildnis kennt den Zorn, aber auch seine Grenzen. Der Puls wird schneller. Die Hand bleibt ruhig.", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; atmet scharf aus, reißt die Waffe hoch und setzt unerbittlich nach.*", "Ich kämpfe nicht gegen das Gleichgewicht, sondern für es. Nur weil ich zornig bin, bin ich noch lange nicht ungenau.", "*legt kurz zwei Finger an eine alte Blattgravur; treibt mit wilden Augen, aber kontrolliertem Griff den Angriff voran.*" },
        INTERCEPT = { "Der Pfad wird sichtbar, wenn man auf den Wind hört. Ein Vorsprung ist nur geliehene Zeit.", "*legt kurz zwei Finger an eine alte Blattgravur; stürzt seitlich aus dem Kampfgetümmel und schneidet den Weg ab.*", "Selbst ein fallender Baum wählt seinen Weg. Ihr rennt? Wie aufmerksam, ich wollte mich ohnehin bewegen.", "*lässt den Atem in einer lautlosen Bewegung entweichen; stößt sich aus dem Stand ab und landet mitten in der Fluchtlinie.*" },
        PUMMEL = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Zu viele Worte. Zu wenig Deckung.", "*lässt den Atem in einer lautlosen Bewegung entweichen; stört die Zauberbewegung mit einem raschen, gezielten Stoß.*", "Es gibt Kämpfe, die enden erst, wenn die Stille zurückkehrt. Wolltet Ihr noch etwas sagen? Nein? Gut.", "*passt den Stand dem unebenen Boden an; bringt den gegnerischen Arm mit einem knappen Schlag aus dem Takt.*" },
        SWEEPING_STRIKES = { "Geduld ist die längste Waffe, die ich trage. Wenn schon Arbeit, dann richtig.", "*passt den Stand dem unebenen Boden an; lässt den ersten Hieb in einen zweiten Bogen übergehen.*", "Die Nacht hat längere Erinnerungen als diese Fehde. Mehrere Gegner? Spart Wege.", "*neigt den Kopf, als würde ein ferner Wald antworten; nimmt den Schwung nicht zurück, sondern führt ihn durch das Getümmel weiter.*" },
        DEATH_WISH = { "Die Wildnis kennt den Zorn, aber auch seine Grenzen. Die Vernunft hat gesprochen. Ich habe ihr widersprochen.", "*neigt den Kopf, als würde ein ferner Wald antworten; lockert den Griff für einen Augenblick und stürzt sich entschlossen nach vorn.*", "Ich kämpfe nicht gegen das Gleichgewicht, sondern für es. Ich weiß, was ich riskiere. Die anderen vielleicht nicht.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; wirft einen letzten Blick auf die eigene Deckung und entscheidet sich für den Angriff.*" },
        RECKLESSNESS = { "Die Wildnis kennt den Zorn, aber auch seine Grenzen. Vorsicht war gestern. Heute wird gehandelt.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; verliert jede Zurückhaltung, ohne die Waffe aus der Hand zu lassen.*", "Selbst ein fallender Baum wählt seinen Weg. Morgen darf man mich dafür ausschimpfen. Wenn wir ein Morgen haben.", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; setzt den ganzen Körper in eine wilde Folge von Angriffen.*" },
        LAST_STAND = { "Alte Wurzeln lassen sich nicht leicht herausreißen. Bis hierher und keinen Schritt weiter.", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; stemmt sich mühsam auf und hebt den Schild noch einmal.*", "Es gibt Kämpfe, die enden erst, wenn die Stille zurückkehrt. Ich stehe noch. Das muss als Antwort genügen.", "*legt kurz zwei Finger an eine alte Blattgravur; stellt sich trotz zitternder Beine erneut schützend in die Bresche.*" },
        SHIELD_WALL = { "Alte Wurzeln lassen sich nicht leicht herausreißen. Hinter mir. Keine Heldentaten auf eigene Rechnung!", "*legt kurz zwei Finger an eine alte Blattgravur; zieht das Schild dicht heran und verhakt die Schulter in der Linie.*", "Die Nacht hat längere Erinnerungen als diese Fehde. Wer durch mich hindurch will, braucht einen langen Atem.", "*lässt den Atem in einer lautlosen Bewegung entweichen; schließt die letzte Lücke zwischen Schild und Rüstung.*" },
        RETALIATION = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Wer austeilt, muss das Echo mögen.", "*lässt den Atem in einer lautlosen Bewegung entweichen; öffnet die Deckung einen Spalt und beantwortet jeden Angriff mit Stahl.*", "Ich kämpfe nicht gegen das Gleichgewicht, sondern für es. Kommt nur. Ich habe für jeden einen Augenblick übrig.", "*passt den Stand dem unebenen Boden an; legt die Füße breit und wartet auf die ersten ungeduldigen Hiebe.*" },
        MOCKING_BLOW = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Seid Ihr tatsächlich gefährlich oder nur besonders laut?", "*passt den Stand dem unebenen Boden an; lässt die Spitze absichtlich zu tief sinken und lockt den Gegner näher.*", "Selbst ein fallender Baum wählt seinen Weg. Oh, verzeiht. Ich hatte Euch für einen Übungsgegner gehalten.", "*neigt den Kopf, als würde ein ferner Wald antworten; setzt einen frechen Hieb und grinst hinter dem Schild hervor.*" },
        BERSERKER_RAGE = { "Die Wildnis kennt den Zorn, aber auch seine Grenzen. Angst? Die hat heute keinen Platz in meinem Kopf.", "*neigt den Kopf, als würde ein ferner Wald antworten; schüttelt die Schultern aus, als würde eine unsichtbare Last abfallen.*", "Es gibt Kämpfe, die enden erst, wenn die Stille zurückkehrt. Meine Furcht darf draußen warten. Meine Wut kommt mit.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; stößt die Luft aus, strafft den Nacken und hält den Blick fest.*" },
        BLOODRAGE = { "Die Wildnis kennt den Zorn, aber auch seine Grenzen. Schmerz ist eine Nachricht. Ich antworte später.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; schlägt die Faust gegen die Brust und sammelt neuen Kampfeswillen.*", "Die Nacht hat längere Erinnerungen als diese Fehde. Das Herz schlägt. Mehr muss es gerade nicht erklären.", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; beißt die Zähne zusammen und spannt die Schultern unter der Rüstung.*" },
        DISARM = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Ihr habt ein schönes Schwert. Darf ich es kurz sehen?", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; versucht, die gegnerische Waffe mit einer knappen Drehung aus der Hand zu hebeln.*", "Ich kämpfe nicht gegen das Gleichgewicht, sondern für es. Mal sehen, ob Ihr auch ohne Waffe so gesprächig seid.", "*legt kurz zwei Finger an eine alte Blattgravur; versucht, den Griff der gegnerischen Waffe abzufangen und aus der Linie zu drehen.*" },
        INTIMIDATING_SHOUT = { "Mein Ruf trägt durch das Dunkel der Wälder. Lauft, solange Ihr noch wisst, wohin!", "*legt kurz zwei Finger an eine alte Blattgravur; schleudert einen wilden Schrei über die Köpfe der Gegner hinweg.*", "Selbst ein fallender Baum wählt seinen Weg. Das war die freundliche Warnung. Die zweite kommt mit Stahl.", "*lässt den Atem in einer lautlosen Bewegung entweichen; schlägt donnernd gegen den Schild und bleckt die Zähne.*" },
        CHALLENGING_SHOUT = { "Mein Ruf trägt durch das Dunkel der Wälder. ALLE ZU MIR! Ich habe Platz für Euren ganzen Ärger!", "*lässt den Atem in einer lautlosen Bewegung entweichen; reißt beide Arme auseinander und fordert die feindliche Reihe heraus.*", "Es gibt Kämpfe, die enden erst, wenn die Stille zurückkehrt. Lasst die anderen in Ruhe. Ich bin heute Euer Problem!", "*passt den Stand dem unebenen Boden an; schlägt mehrmals auf den Schild und brüllt die Gegner an.*" },
        SLAM = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Das ist kein Hammer. Es fühlt sich gleich aber so an.", "*passt den Stand dem unebenen Boden an; holt über die Schulter aus und lässt den Stahl mit voller Kraft niederfahren.*", "Die Nacht hat längere Erinnerungen als diese Fehde. Lieber ein sauberer Treffer als fünf halbe.", "*neigt den Kopf, als würde ein ferner Wald antworten; lässt die Waffe nach kurzem Zögern mit dem ganzen Gewicht folgen.*" },
        DEVASTATE = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Schon locker? Dann lösen wir den Rest auch noch.", "*neigt den Kopf, als würde ein ferner Wald antworten; schlägt hart auf eine bereits angeschlagene Stelle der Rüstung.*", "Ich kämpfe nicht gegen das Gleichgewicht, sondern für es. Ich sehe, der Schmied hat an der falschen Stelle gespart.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; klopft prüfend gegen die offene Fuge und setzt entschlossen nach.*" },
        SHIELD_SLAM = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Ein Schild kann auch Türen schließen. Auf Nasenhöhe.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; reißt den Schild aus der Deckung und stößt dessen Kante kraftvoll nach vorn.*", "Selbst ein fallender Baum wählt seinen Weg. Wer sagt, Verteidigung sei höflich?", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; macht einen kurzen Satz vorwärts und lässt den Schild sprechen.*" },
        CONCUSSION_BLOW = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Ich versuche, Euch aus dem Takt zu bringen.", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; versucht, einen schweren Hieb in die Lücke zwischen zwei Bewegungen zu führen.*", "Es gibt Kämpfe, die enden erst, wenn die Stille zurückkehrt. Ich versuche, allen einen Augenblick Ruhe zu verschaffen.", "*legt kurz zwei Finger an eine alte Blattgravur; verkürzt den Griff und schwingt mit überraschender Wucht.*" },
        VICTORY_RUSH = { "Der Pfad wird sichtbar, wenn man auf den Wind hört. Einer weniger. Die anderen stehen noch.", "*legt kurz zwei Finger an eine alte Blattgravur; nutzt den gewonnenen Atemzug, richtet sich auf und prescht weiter.*", "Die Nacht hat längere Erinnerungen als diese Fehde. Feiern können wir später. Da bewegt sich noch etwas.", "*lässt den Atem in einer lautlosen Bewegung entweichen; klopft sich einmal auf die Brust und setzt sofort nach.*" },
        BATTLE_STANCE = { "Geduld ist die längste Waffe, die ich trage. Zwischen Mut und Dummheit liegen manchmal nur zwei Fußbreit.", "*lässt den Atem in einer lautlosen Bewegung entweichen; setzt die Stiefel schulterbreit auf und lässt die Waffe locker kreisen.*", "Ich kämpfe nicht gegen das Gleichgewicht, sondern für es. Ich bleibe beweglich. Der Rest darf sich entscheiden.", "*passt den Stand dem unebenen Boden an; wiegt das Gewicht zwischen Schildarm und Waffenhand aus.*" },
        DEFENSIVE_STANCE = { "Alte Wurzeln lassen sich nicht leicht herausreißen. Wer an meine Leute will, muss zuerst meinen Schild überzeugen.", "*passt den Stand dem unebenen Boden an; stellt die Beine breit und hält den Schild vor die Verbündeten.*", "Selbst ein fallender Baum wählt seinen Weg. Heute gewinnt nicht, wer am lautesten brüllt.", "*neigt den Kopf, als würde ein ferner Wald antworten; senkt den Schwerpunkt und wird hinter der Deckung nahezu unbeweglich.*" },
        BERSERKER_STANCE = { "Die Wildnis kennt den Zorn, aber auch seine Grenzen. Wer behauptet, Wut mache blind, hat nie richtig hingesehen.", "*neigt den Kopf, als würde ein ferner Wald antworten; atmet tief ein, hebt das Kinn und nimmt eine wilde Haltung ein.*", "Es gibt Kämpfe, die enden erst, wenn die Stille zurückkehrt. Die Welt wird plötzlich sehr einfach: vorwärts.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; lockert die Schultern, lässt die Waffe sinken und reißt sie schlagartig hoch.*" },
        PIERCING_HOWL = { "Hört die Nacht. Diesmal erhebt sie meine Stimme.", "*gleitet ohne unnötiges Geräusch einen Schritt zur Seite; heult so durchdringend, dass die Stimmen umher für einen Moment verstummen.*", "Die Nacht hat längere Erinnerungen als diese Fehde. Nein, das war kein Wolfsrudel. Nur ich.", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; wirft den Kopf zurück und lässt einen rauen, langen Laut los.*" },
        SPEARING_STRIKE = { "Auch in einer Schlacht gibt es den Augenblick zwischen zwei Blättern. Die Lücke ist schmal. Meine Spitze nicht.", "*richtet die Klinge nach einem flüchtigen Blick zum Himmel aus; führt die Waffe mit einem einzigen geraden Schritt nach vorn.*", "Ich kämpfe nicht gegen das Gleichgewicht, sondern für es. Rüstung ist stark. Winkel sind stärker.", "*legt kurz zwei Finger an eine alte Blattgravur; dreht das Handgelenk, zielt auf die Schwachstelle und stößt vor.*" },
        TACTICAL_MASTERY = { "Manchmal gewinnt der Baum, der zuerst nachgibt.", "*legt kurz zwei Finger an eine alte Blattgravur; verändert unmerklich den Stand und bewahrt die Übersicht.*", "Selbst ein fallender Baum wählt seinen Weg. Ein Schlachtfeld ist kein Würfelspiel. Es wird gelesen.", "*lässt den Atem in einer lautlosen Bewegung entweichen; mustert Wege, Gegner und Rückzugsräume, ohne die Waffe zu senken.*" },
    },
    DRAENEI = {
        HEROIC_STRIKE = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Wisst Ihr, warum meine Waffe so schwer ist? Sie widerspricht selten.", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; verlegt das Gewicht auf den vorderen Fuß und führt einen wuchtigen Hieb.*", "Für jedes Leben hinter mir stehe ich einen Herzschlag länger. Es gibt Argumente, die brauchen keinen zweiten Satz.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; schiebt die Schulter nach und lässt den Stahl sprechen.*" },
        CHARGE = { "Jeder Schritt ist ein Versprechen an die Zurückgelassenen. Wenn der Weg versperrt ist, nehme ich eben den direkten.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; senkt die Schulter, stößt sich ab und wirbelt Staub auf.*", "Das Licht schenkt Orientierung. Handeln muss ich selbst. Ich komme! Das ist keine Warnung, sondern eine Wegbeschreibung!", "*richtet den Schild vor den Verbündeten aus; prescht mit einem lauten Scheppern durch die Lücke in der Reihe.*" },
        REND = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Rüstungsnähte sind kleine Geheimnisse. Ich bin neugierig.", "*richtet den Schild vor den Verbündeten aus; führt die Schneide schräg über eine schlecht geschützte Stelle.*", "Die Erinnerung an verlorene Welten macht meine Entschlossenheit schwer. Ein Schneider wäre entsetzt. Ich bin zufrieden.", "*atmet tief und findet zu einer ruhigen Mitte; zieht die Klinge rasch zurück und sucht die nächste Öffnung.*" },
        HAMSTRING = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Weglaufen? Das ist ein Plan mit Schwächen.", "*atmet tief und findet zu einer ruhigen Mitte; taucht tief unter der gegnerischen Deckung hindurch.*", "Ich suche keinen Ruhm, sondern einen sicheren Weg nach Hause. Ich schlage nicht gern zweimal hinterher. Einmal genügt.", "*prüft den Stand der Hufe auf dem Boden; führt die Waffe knapp über den Boden und richtet sich sofort wieder auf.*" },
        THUNDER_CLAP = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Wenn der Boden bebt, brauchen wir keinen Trommler mehr.", "*prüft den Stand der Hufe auf dem Boden; stampft mit solcher Wucht auf, dass Staub vom Boden springt.*", "Für jedes Leben hinter mir stehe ich einen Herzschlag länger. Hört Ihr das? Die Erde erhebt Einspruch.", "*legt eine Hand an ein altes Familienabzeichen; reißt die Arme auseinander und lässt einen dumpfen Schlag durch die Reihen grollen.*" },
        CLEAVE = { "Ein klarer Geist kann den schlimmsten Sturm bestehen. Wer nebeneinander antritt, teilt sich auch die Probleme.", "*legt eine Hand an ein altes Familienabzeichen; schwingt die Waffe in einem breiten Bogen quer durch den Kampfraum.*", "Das Licht schenkt Orientierung. Handeln muss ich selbst. Ich hoffe, Ihr habt alle genug Abstand. Ich nicht.", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; dreht auf der Ferse und nimmt den Schwung in den nächsten Bogen mit.*" },
        EXECUTE = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Ich habe Euch jede Gelegenheit zum Rückzug gelassen.", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; wartet einen Herzschlag ab und führt dann einen endgültig wirkenden Hieb.*", "Die Erinnerung an verlorene Welten macht meine Entschlossenheit schwer. Jetzt wird nicht mehr verhandelt.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; fasst den Griff fester und schließt die letzte Lücke.*" },
        SUNDER_ARMOR = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Schöner Harnisch. Schade um die Nieten.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; setzt die Waffe gezielt an einer lockeren Rüstungskante an.*", "Ich suche keinen Ruhm, sondern einen sicheren Weg nach Hause. Teurer Stahl ist noch keine gute Deckung.", "*richtet den Schild vor den Verbündeten aus; zieht mit der Schneide eine Linie entlang einer Naht im Metall.*" },
        SHIELD_BLOCK = { "Standhaftigkeit beginnt dort, wo andere Schutz suchen. Da müsst Ihr schon anklopfen. Der Schild bleibt zu.", "*richtet den Schild vor den Verbündeten aus; dreht die Schildkante in den kommenden Schlag und federt ihn ab.*", "Für jedes Leben hinter mir stehe ich einen Herzschlag länger. Ein gutes Schild hört zu, bevor es antwortet.", "*atmet tief und findet zu einer ruhigen Mitte; stemmt die Stiefel in den Boden und lässt die Deckung nicht nachgeben.*" },
        SHIELD_BASH = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Psst. Mal sehen, ob ich Euren Zauber unterbrechen kann.", "*atmet tief und findet zu einer ruhigen Mitte; rammt die Schildfläche nach vorn, genau zwischen zwei Silben.*", "Das Licht schenkt Orientierung. Handeln muss ich selbst. Meine Antwort auf Magie hat einen Holzgriff.", "*prüft den Stand der Hufe auf dem Boden; rückt einen Schritt heran und stößt unvermittelt mit dem Schild zu.*" },
        TAUNT = { "Die Schwachen sind kein Ziel. Versucht es an mir.", "*prüft den Stand der Hufe auf dem Boden; klopft mit dem Schwertknauf dreimal provokant auf den Schild.*", "Die Erinnerung an verlorene Welten macht meine Entschlossenheit schwer. Die anderen haben Wichtigeres zu tun. Ich nicht.", "*legt eine Hand an ein altes Familienabzeichen; tritt demonstrativ aus der Reihe und winkt die Gegner heran.*" },
        BATTLE_SHOUT = { "Ihr seid nicht allein. Kein einziger von Euch!", "*legt eine Hand an ein altes Familienabzeichen; schlägt den Schwertknauf im Takt gegen den Schildrand.*", "Ich suche keinen Ruhm, sondern einen sicheren Weg nach Hause. Ihr habt Beine zum Stehen und Herzen zum Durchhalten. Nutzt beides!", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; richtet sich vor den Verbündeten auf und hebt die Klinge hoch.*" },
        DEMORALIZING_SHOUT = { "Meine Stimme soll Hoffnung tragen, nicht nur Furcht. Die Ersten von Euch zittern schon. Die Letzten merken es gleich!", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; lässt einen tiefen, rauen Schlachtruf aus voller Brust erschallen.*", "Für jedes Leben hinter mir stehe ich einen Herzschlag länger. Schaut Euch um. Für wen wollt Ihr eigentlich noch kämpfen?", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; zeigt mit der Klinge auf die wankende feindliche Linie.*" },
        REVENGE = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Danke für die Gelegenheit. Die kommt sofort zurück.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; lenkt die Waffe ab und fährt in die entstandene Lücke.*", "Das Licht schenkt Orientierung. Handeln muss ich selbst. Ich vergesse Gesichter. Schläge nicht.", "*richtet den Schild vor den Verbündeten aus; dreht sich aus der Abwehr direkt in den Gegenangriff.*" },
        OVERPOWER = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Da war eine Lücke. Ihr habt sie mir geschenkt.", "*richtet den Schild vor den Verbündeten aus; gleitet an der vorbeigehenden Waffe vorbei und nutzt den offenen Winkel.*", "Die Erinnerung an verlorene Welten macht meine Entschlossenheit schwer. Wer danebenhaut, lädt mich ein.", "*atmet tief und findet zu einer ruhigen Mitte; nutzt eine missratene Bewegung für einen schnellen Gegenstoß.*" },
        MORTAL_STRIKE = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Ich spare mir den zweiten Versuch.", "*atmet tief und findet zu einer ruhigen Mitte; nimmt die Waffe fest in beide Hände und legt den ganzen Körper in einen einzigen Schlag.*", "Ich suche keinen Ruhm, sondern einen sicheren Weg nach Hause. Manche Duelle enden mit einem Satz. Dieses nicht.", "*prüft den Stand der Hufe auf dem Boden; schreitet voran und führt den Stahl mit unerbittlicher Präzision.*" },
        WHIRLWIND = { "Ein klarer Geist kann den schlimmsten Sturm bestehen. Stellt Euch ruhig im Kreis auf. Es ist praktisch.", "*prüft den Stand der Hufe auf dem Boden; dreht sich mitsamt der Waffe durch eine Schneise im Gedränge.*", "Für jedes Leben hinter mir stehe ich einen Herzschlag länger. Ich teile gern. Heute Stahl.", "*legt eine Hand an ein altes Familienabzeichen; lässt die Klinge in weitem Schwung ringsum singen.*" },
        BLOODTHIRST = { "Selbst jetzt darf der Zorn nicht Herr über meinen Willen sein. Der Puls wird schneller. Die Hand bleibt ruhig.", "*legt eine Hand an ein altes Familienabzeichen; atmet scharf aus, reißt die Waffe hoch und setzt unerbittlich nach.*", "Das Licht schenkt Orientierung. Handeln muss ich selbst. Nur weil ich zornig bin, bin ich noch lange nicht ungenau.", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; treibt mit wilden Augen, aber kontrolliertem Griff den Angriff voran.*" },
        INTERCEPT = { "Jeder Schritt ist ein Versprechen an die Zurückgelassenen. Ein Vorsprung ist nur geliehene Zeit.", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; stürzt seitlich aus dem Kampfgetümmel und schneidet den Weg ab.*", "Die Erinnerung an verlorene Welten macht meine Entschlossenheit schwer. Ihr rennt? Wie aufmerksam, ich wollte mich ohnehin bewegen.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; stößt sich aus dem Stand ab und landet mitten in der Fluchtlinie.*" },
        PUMMEL = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Zu viele Worte. Zu wenig Deckung.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; stört die Zauberbewegung mit einem raschen, gezielten Stoß.*", "Ich suche keinen Ruhm, sondern einen sicheren Weg nach Hause. Wolltet Ihr noch etwas sagen? Nein? Gut.", "*richtet den Schild vor den Verbündeten aus; bringt den gegnerischen Arm mit einem knappen Schlag aus dem Takt.*" },
        SWEEPING_STRIKES = { "Ein klarer Geist kann den schlimmsten Sturm bestehen. Wenn schon Arbeit, dann richtig.", "*richtet den Schild vor den Verbündeten aus; lässt den ersten Hieb in einen zweiten Bogen übergehen.*", "Für jedes Leben hinter mir stehe ich einen Herzschlag länger. Mehrere Gegner? Spart Wege.", "*atmet tief und findet zu einer ruhigen Mitte; nimmt den Schwung nicht zurück, sondern führt ihn durch das Getümmel weiter.*" },
        DEATH_WISH = { "Selbst jetzt darf der Zorn nicht Herr über meinen Willen sein. Die Vernunft hat gesprochen. Ich habe ihr widersprochen.", "*atmet tief und findet zu einer ruhigen Mitte; lockert den Griff für einen Augenblick und stürzt sich entschlossen nach vorn.*", "Das Licht schenkt Orientierung. Handeln muss ich selbst. Ich weiß, was ich riskiere. Die anderen vielleicht nicht.", "*prüft den Stand der Hufe auf dem Boden; wirft einen letzten Blick auf die eigene Deckung und entscheidet sich für den Angriff.*" },
        RECKLESSNESS = { "Selbst jetzt darf der Zorn nicht Herr über meinen Willen sein. Vorsicht war gestern. Heute wird gehandelt.", "*prüft den Stand der Hufe auf dem Boden; verliert jede Zurückhaltung, ohne die Waffe aus der Hand zu lassen.*", "Die Erinnerung an verlorene Welten macht meine Entschlossenheit schwer. Morgen darf man mich dafür ausschimpfen. Wenn wir ein Morgen haben.", "*legt eine Hand an ein altes Familienabzeichen; setzt den ganzen Körper in eine wilde Folge von Angriffen.*" },
        LAST_STAND = { "Ich habe Welten fallen sehen. Diese Stellung bleibt stehen.", "*legt eine Hand an ein altes Familienabzeichen; stemmt sich mühsam auf und hebt den Schild noch einmal.*", "Ich suche keinen Ruhm, sondern einen sicheren Weg nach Hause. Ich stehe noch. Das muss als Antwort genügen.", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; stellt sich trotz zitternder Beine erneut schützend in die Bresche.*" },
        SHIELD_WALL = { "Kein Flüchtling hinter mir soll heute wieder fliehen müssen.", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; zieht das Schild dicht heran und verhakt die Schulter in der Linie.*", "Für jedes Leben hinter mir stehe ich einen Herzschlag länger. Wer durch mich hindurch will, braucht einen langen Atem.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; schließt die letzte Lücke zwischen Schild und Rüstung.*" },
        RETALIATION = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Wer austeilt, muss das Echo mögen.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; öffnet die Deckung einen Spalt und beantwortet jeden Angriff mit Stahl.*", "Das Licht schenkt Orientierung. Handeln muss ich selbst. Kommt nur. Ich habe für jeden einen Augenblick übrig.", "*richtet den Schild vor den Verbündeten aus; legt die Füße breit und wartet auf die ersten ungeduldigen Hiebe.*" },
        MOCKING_BLOW = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Seid Ihr tatsächlich gefährlich oder nur besonders laut?", "*richtet den Schild vor den Verbündeten aus; lässt die Spitze absichtlich zu tief sinken und lockt den Gegner näher.*", "Die Erinnerung an verlorene Welten macht meine Entschlossenheit schwer. Oh, verzeiht. Ich hatte Euch für einen Übungsgegner gehalten.", "*atmet tief und findet zu einer ruhigen Mitte; setzt einen frechen Hieb und grinst hinter dem Schild hervor.*" },
        BERSERKER_RAGE = { "Selbst jetzt darf der Zorn nicht Herr über meinen Willen sein. Angst? Die hat heute keinen Platz in meinem Kopf.", "*atmet tief und findet zu einer ruhigen Mitte; schüttelt die Schultern aus, als würde eine unsichtbare Last abfallen.*", "Ich suche keinen Ruhm, sondern einen sicheren Weg nach Hause. Meine Furcht darf draußen warten. Meine Wut kommt mit.", "*prüft den Stand der Hufe auf dem Boden; stößt die Luft aus, strafft den Nacken und hält den Blick fest.*" },
        BLOODRAGE = { "Selbst jetzt darf der Zorn nicht Herr über meinen Willen sein. Schmerz ist eine Nachricht. Ich antworte später.", "*prüft den Stand der Hufe auf dem Boden; schlägt die Faust gegen die Brust und sammelt neuen Kampfeswillen.*", "Für jedes Leben hinter mir stehe ich einen Herzschlag länger. Das Herz schlägt. Mehr muss es gerade nicht erklären.", "*legt eine Hand an ein altes Familienabzeichen; beißt die Zähne zusammen und spannt die Schultern unter der Rüstung.*" },
        DISARM = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Ihr habt ein schönes Schwert. Darf ich es kurz sehen?", "*legt eine Hand an ein altes Familienabzeichen; versucht, die gegnerische Waffe mit einer knappen Drehung aus der Hand zu hebeln.*", "Das Licht schenkt Orientierung. Handeln muss ich selbst. Mal sehen, ob Ihr auch ohne Waffe so gesprächig seid.", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; versucht, den Griff der gegnerischen Waffe abzufangen und aus der Linie zu drehen.*" },
        INTIMIDATING_SHOUT = { "Meine Stimme soll Hoffnung tragen, nicht nur Furcht. Lauft, solange Ihr noch wisst, wohin!", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; schleudert einen wilden Schrei über die Köpfe der Gegner hinweg.*", "Die Erinnerung an verlorene Welten macht meine Entschlossenheit schwer. Das war die freundliche Warnung. Die zweite kommt mit Stahl.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; schlägt donnernd gegen den Schild und bleckt die Zähne.*" },
        CHALLENGING_SHOUT = { "Meine Stimme soll Hoffnung tragen, nicht nur Furcht. ALLE ZU MIR! Ich habe Platz für Euren ganzen Ärger!", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; reißt beide Arme auseinander und fordert die feindliche Reihe heraus.*", "Ich suche keinen Ruhm, sondern einen sicheren Weg nach Hause. Lasst die anderen in Ruhe. Ich bin heute Euer Problem!", "*richtet den Schild vor den Verbündeten aus; schlägt mehrmals auf den Schild und brüllt die Gegner an.*" },
        SLAM = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Das ist kein Hammer. Es fühlt sich gleich aber so an.", "*richtet den Schild vor den Verbündeten aus; holt über die Schulter aus und lässt den Stahl mit voller Kraft niederfahren.*", "Für jedes Leben hinter mir stehe ich einen Herzschlag länger. Lieber ein sauberer Treffer als fünf halbe.", "*atmet tief und findet zu einer ruhigen Mitte; lässt die Waffe nach kurzem Zögern mit dem ganzen Gewicht folgen.*" },
        DEVASTATE = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Schon locker? Dann lösen wir den Rest auch noch.", "*atmet tief und findet zu einer ruhigen Mitte; schlägt hart auf eine bereits angeschlagene Stelle der Rüstung.*", "Das Licht schenkt Orientierung. Handeln muss ich selbst. Ich sehe, der Schmied hat an der falschen Stelle gespart.", "*prüft den Stand der Hufe auf dem Boden; klopft prüfend gegen die offene Fuge und setzt entschlossen nach.*" },
        SHIELD_SLAM = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Ein Schild kann auch Türen schließen. Auf Nasenhöhe.", "*prüft den Stand der Hufe auf dem Boden; reißt den Schild aus der Deckung und stößt dessen Kante kraftvoll nach vorn.*", "Die Erinnerung an verlorene Welten macht meine Entschlossenheit schwer. Wer sagt, Verteidigung sei höflich?", "*legt eine Hand an ein altes Familienabzeichen; macht einen kurzen Satz vorwärts und lässt den Schild sprechen.*" },
        CONCUSSION_BLOW = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Ich versuche, Euch aus dem Takt zu bringen.", "*legt eine Hand an ein altes Familienabzeichen; versucht, einen schweren Hieb in die Lücke zwischen zwei Bewegungen zu führen.*", "Ich suche keinen Ruhm, sondern einen sicheren Weg nach Hause. Ich versuche, allen einen Augenblick Ruhe zu verschaffen.", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; verkürzt den Griff und schwingt mit überraschender Wucht.*" },
        VICTORY_RUSH = { "Jeder Schritt ist ein Versprechen an die Zurückgelassenen. Einer weniger. Die anderen stehen noch.", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; nutzt den gewonnenen Atemzug, richtet sich auf und prescht weiter.*", "Für jedes Leben hinter mir stehe ich einen Herzschlag länger. Feiern können wir später. Da bewegt sich noch etwas.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; klopft sich einmal auf die Brust und setzt sofort nach.*" },
        BATTLE_STANCE = { "Ein klarer Geist kann den schlimmsten Sturm bestehen. Zwischen Mut und Dummheit liegen manchmal nur zwei Fußbreit.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; setzt die Stiefel schulterbreit auf und lässt die Waffe locker kreisen.*", "Das Licht schenkt Orientierung. Handeln muss ich selbst. Ich bleibe beweglich. Der Rest darf sich entscheiden.", "*richtet den Schild vor den Verbündeten aus; wiegt das Gewicht zwischen Schildarm und Waffenhand aus.*" },
        DEFENSIVE_STANCE = { "Standhaftigkeit beginnt dort, wo andere Schutz suchen. Wer an meine Leute will, muss zuerst meinen Schild überzeugen.", "*richtet den Schild vor den Verbündeten aus; stellt die Beine breit und hält den Schild vor die Verbündeten.*", "Die Erinnerung an verlorene Welten macht meine Entschlossenheit schwer. Heute gewinnt nicht, wer am lautesten brüllt.", "*atmet tief und findet zu einer ruhigen Mitte; senkt den Schwerpunkt und wird hinter der Deckung nahezu unbeweglich.*" },
        BERSERKER_STANCE = { "Selbst jetzt darf der Zorn nicht Herr über meinen Willen sein. Wer behauptet, Wut mache blind, hat nie richtig hingesehen.", "*atmet tief und findet zu einer ruhigen Mitte; atmet tief ein, hebt das Kinn und nimmt eine wilde Haltung ein.*", "Ich suche keinen Ruhm, sondern einen sicheren Weg nach Hause. Die Welt wird plötzlich sehr einfach: vorwärts.", "*prüft den Stand der Hufe auf dem Boden; lockert die Schultern, lässt die Waffe sinken und reißt sie schlagartig hoch.*" },
        PIERCING_HOWL = { "Meine Stimme soll Hoffnung tragen, nicht nur Furcht. Wenn Ihr den Ruf hört, seid Ihr schon zu nah.", "*prüft den Stand der Hufe auf dem Boden; heult so durchdringend, dass die Stimmen umher für einen Moment verstummen.*", "Für jedes Leben hinter mir stehe ich einen Herzschlag länger. Nein, das war kein Wolfsrudel. Nur ich.", "*legt eine Hand an ein altes Familienabzeichen; wirft den Kopf zurück und lässt einen rauen, langen Laut los.*" },
        SPEARING_STRIKE = { "Es soll kein Triumph über Schwächere werden, sondern Schutz für die Meinen. Die Lücke ist schmal. Meine Spitze nicht.", "*legt eine Hand an ein altes Familienabzeichen; führt die Waffe mit einem einzigen geraden Schritt nach vorn.*", "Das Licht schenkt Orientierung. Handeln muss ich selbst. Rüstung ist stark. Winkel sind stärker.", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; dreht das Handgelenk, zielt auf die Schwachstelle und stößt vor.*" },
        TACTICAL_MASTERY = { "Ein klarer Geist kann den schlimmsten Sturm bestehen. Der Unterschied zwischen Mut und Übermut ist eine gute Fußstellung.", "*berührt kurz ein kleines Erinnerungszeichen an der Rüstung; verändert unmerklich den Stand und bewahrt die Übersicht.*", "Die Erinnerung an verlorene Welten macht meine Entschlossenheit schwer. Ein Schlachtfeld ist kein Würfelspiel. Es wird gelesen.", "*senkt die Hörner und verlagert das Gewicht gleichmäßig; mustert Wege, Gegner und Rückzugsräume, ohne die Waffe zu senken.*" },
    },
    ORC = {
        HEROIC_STRIKE = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Wisst Ihr, warum meine Waffe so schwer ist? Sie widerspricht selten.", "*schlägt die Faust gegen eine alte Clanmarkierung; verlegt das Gewicht auf den vorderen Fuß und führt einen wuchtigen Hieb.*", "Ich werde nicht hinter anderen stehen und sie allein lassen. Es gibt Argumente, die brauchen keinen zweiten Satz.", "*zeigt die Hauer in einem entschlossenen Grinsen; schiebt die Schulter nach und lässt den Stahl sprechen.*" },
        CHARGE = { "Für den Clan! Keiner weicht, solange ich noch stehe!", "*stößt einen rauen Kampfruf aus und bricht durch die erste Lücke.*", "Meine Axt kennt die Wahrheit über Prahlerei. Ich komme! Das ist keine Warnung, sondern eine Wegbeschreibung!", "*stemmt die Füße fest in den aufgewühlten Boden; prescht mit einem lauten Scheppern durch die Lücke in der Reihe.*" },
        REND = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Rüstungsnähte sind kleine Geheimnisse. Ich bin neugierig.", "*stemmt die Füße fest in den aufgewühlten Boden; führt die Schneide schräg über eine schlecht geschützte Stelle.*", "Ein Krieger ohne Verantwortung ist nur ein lauter Narr. Ein Schneider wäre entsetzt. Ich bin zufrieden.", "*fährt mit dem Daumen über eine Kerbe am Waffenstiel; zieht die Klinge rasch zurück und sucht die nächste Öffnung.*" },
        HAMSTRING = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Weglaufen? Das ist ein Plan mit Schwächen.", "*fährt mit dem Daumen über eine Kerbe am Waffenstiel; taucht tief unter der gegnerischen Deckung hindurch.*", "Die Ahnen sollen an meinem Stand erkennen, wer ich bin. Ich schlage nicht gern zweimal hinterher. Einmal genügt.", "*stößt einen kurzen rauen Atemlaut aus; führt die Waffe knapp über den Boden und richtet sich sofort wieder auf.*" },
        THUNDER_CLAP = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Wenn der Boden bebt, brauchen wir keinen Trommler mehr.", "*stößt einen kurzen rauen Atemlaut aus; stampft mit solcher Wucht auf, dass Staub vom Boden springt.*", "Ich werde nicht hinter anderen stehen und sie allein lassen. Hört Ihr das? Die Erde erhebt Einspruch.", "*strafft den Lederwickel um den Griff der Waffe; reißt die Arme auseinander und lässt einen dumpfen Schlag durch die Reihen grollen.*" },
        CLEAVE = { "Die Ahnen loben keinen Sieg, den Dummheit erkauft. Wer nebeneinander antritt, teilt sich auch die Probleme.", "*strafft den Lederwickel um den Griff der Waffe; schwingt die Waffe in einem breiten Bogen quer durch den Kampfraum.*", "Meine Axt kennt die Wahrheit über Prahlerei. Ich hoffe, Ihr habt alle genug Abstand. Ich nicht.", "*schlägt die Faust gegen eine alte Clanmarkierung; dreht auf der Ferse und nimmt den Schwung in den nächsten Bogen mit.*" },
        EXECUTE = { "Euer Kampf ist zu Ende. Ich werde nicht damit prahlen.", "*fasst die Waffe mit beiden Händen und vollendet den Hieb.*", "Ein Krieger ohne Verantwortung ist nur ein lauter Narr. Jetzt wird nicht mehr verhandelt.", "*zeigt die Hauer in einem entschlossenen Grinsen; fasst den Griff fester und schließt die letzte Lücke.*" },
        SUNDER_ARMOR = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Schöner Harnisch. Schade um die Nieten.", "*zeigt die Hauer in einem entschlossenen Grinsen; setzt die Waffe gezielt an einer lockeren Rüstungskante an.*", "Die Ahnen sollen an meinem Stand erkennen, wer ich bin. Teurer Stahl ist noch keine gute Deckung.", "*stemmt die Füße fest in den aufgewühlten Boden; zieht mit der Schneide eine Linie entlang einer Naht im Metall.*" },
        SHIELD_BLOCK = { "Meine Schulter weicht nicht, solange hinter mir einer atmet.", "*stemmt die Füße fest in den aufgewühlten Boden; dreht die Schildkante in den kommenden Schlag und federt ihn ab.*", "Ich werde nicht hinter anderen stehen und sie allein lassen. Ein gutes Schild hört zu, bevor es antwortet.", "*fährt mit dem Daumen über eine Kerbe am Waffenstiel; stemmt die Stiefel in den Boden und lässt die Deckung nicht nachgeben.*" },
        SHIELD_BASH = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Psst. Mal sehen, ob ich Euren Zauber unterbrechen kann.", "*fährt mit dem Daumen über eine Kerbe am Waffenstiel; rammt die Schildfläche nach vorn, genau zwischen zwei Silben.*", "Meine Axt kennt die Wahrheit über Prahlerei. Meine Antwort auf Magie hat einen Holzgriff.", "*stößt einen kurzen rauen Atemlaut aus; rückt einen Schritt heran und stößt unvermittelt mit dem Schild zu.*" },
        TAUNT = { "Seht mir in die Augen. Ehre kennt keinen Hinterhalt.", "*stößt einen kurzen rauen Atemlaut aus; klopft mit dem Schwertknauf dreimal provokant auf den Schild.*", "Ein Krieger ohne Verantwortung ist nur ein lauter Narr. Die anderen haben Wichtigeres zu tun. Ich nicht.", "*strafft den Lederwickel um den Griff der Waffe; tritt demonstrativ aus der Reihe und winkt die Gegner heran.*" },
        BATTLE_SHOUT = { "FÜR DEN CLAN! Für die, die neben uns stehen!", "*strafft den Lederwickel um den Griff der Waffe; schlägt den Schwertknauf im Takt gegen den Schildrand.*", "Die Ahnen sollen an meinem Stand erkennen, wer ich bin. Ihr habt Beine zum Stehen und Herzen zum Durchhalten. Nutzt beides!", "*schlägt die Faust gegen eine alte Clanmarkierung; richtet sich vor den Verbündeten auf und hebt die Klinge hoch.*" },
        DEMORALIZING_SHOUT = { "Der Clan soll meine Stimme bis zum letzten Krieger hören! Die Ersten von Euch zittern schon. Die Letzten merken es gleich!", "*schlägt die Faust gegen eine alte Clanmarkierung; lässt einen tiefen, rauen Schlachtruf aus voller Brust erschallen.*", "Ich werde nicht hinter anderen stehen und sie allein lassen. Schaut Euch um. Für wen wollt Ihr eigentlich noch kämpfen?", "*zeigt die Hauer in einem entschlossenen Grinsen; zeigt mit der Klinge auf die wankende feindliche Linie.*" },
        REVENGE = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Danke für die Gelegenheit. Die kommt sofort zurück.", "*zeigt die Hauer in einem entschlossenen Grinsen; lenkt die Waffe ab und fährt in die entstandene Lücke.*", "Meine Axt kennt die Wahrheit über Prahlerei. Ich vergesse Gesichter. Schläge nicht.", "*stemmt die Füße fest in den aufgewühlten Boden; dreht sich aus der Abwehr direkt in den Gegenangriff.*" },
        OVERPOWER = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Da war eine Lücke. Ihr habt sie mir geschenkt.", "*stemmt die Füße fest in den aufgewühlten Boden; gleitet an der vorbeigehenden Waffe vorbei und nutzt den offenen Winkel.*", "Ein Krieger ohne Verantwortung ist nur ein lauter Narr. Wer danebenhaut, lädt mich ein.", "*fährt mit dem Daumen über eine Kerbe am Waffenstiel; nutzt eine missratene Bewegung für einen schnellen Gegenstoß.*" },
        MORTAL_STRIKE = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Ich spare mir den zweiten Versuch.", "*fährt mit dem Daumen über eine Kerbe am Waffenstiel; nimmt die Waffe fest in beide Hände und legt den ganzen Körper in einen einzigen Schlag.*", "Die Ahnen sollen an meinem Stand erkennen, wer ich bin. Manche Duelle enden mit einem Satz. Dieses nicht.", "*stößt einen kurzen rauen Atemlaut aus; schreitet voran und führt den Stahl mit unerbittlicher Präzision.*" },
        WHIRLWIND = { "Die Ahnen loben keinen Sieg, den Dummheit erkauft. Stellt Euch ruhig im Kreis auf. Es ist praktisch.", "*stößt einen kurzen rauen Atemlaut aus; dreht sich mitsamt der Waffe durch eine Schneise im Gedränge.*", "Ich werde nicht hinter anderen stehen und sie allein lassen. Ich teile gern. Heute Stahl.", "*strafft den Lederwickel um den Griff der Waffe; lässt die Klinge in weitem Schwung ringsum singen.*" },
        BLOODTHIRST = { "Mein Zorn ist heiß. Meine Absicht bleibt klar. Der Puls wird schneller. Die Hand bleibt ruhig.", "*strafft den Lederwickel um den Griff der Waffe; atmet scharf aus, reißt die Waffe hoch und setzt unerbittlich nach.*", "Meine Axt kennt die Wahrheit über Prahlerei. Nur weil ich zornig bin, bin ich noch lange nicht ungenau.", "*schlägt die Faust gegen eine alte Clanmarkierung; treibt mit wilden Augen, aber kontrolliertem Griff den Angriff voran.*" },
        INTERCEPT = { "Wer Mut hat, wartet nicht auf den zweiten Ruf. Ein Vorsprung ist nur geliehene Zeit.", "*schlägt die Faust gegen eine alte Clanmarkierung; stürzt seitlich aus dem Kampfgetümmel und schneidet den Weg ab.*", "Ein Krieger ohne Verantwortung ist nur ein lauter Narr. Ihr rennt? Wie aufmerksam, ich wollte mich ohnehin bewegen.", "*zeigt die Hauer in einem entschlossenen Grinsen; stößt sich aus dem Stand ab und landet mitten in der Fluchtlinie.*" },
