        SHIELD_WALL = { "Eine gebrochene Reihe ist eine gebrochene Pflicht. Hinter mir. Keine Heldentaten auf eigene Rechnung!", "*schlägt die Faust gegen eine alte Clanmarkierung; zieht das Schild dicht heran und verhakt die Schulter in der Linie.*", "Ich werde nicht hinter anderen stehen und sie allein lassen. Wer durch mich hindurch will, braucht einen langen Atem.", "*zeigt die Hauer in einem entschlossenen Grinsen; schließt die letzte Lücke zwischen Schild und Rüstung.*" },
        RETALIATION = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Wer austeilt, muss das Echo mögen.", "*zeigt die Hauer in einem entschlossenen Grinsen; öffnet die Deckung einen Spalt und beantwortet jeden Angriff mit Stahl.*", "Meine Axt kennt die Wahrheit über Prahlerei. Kommt nur. Ich habe für jeden einen Augenblick übrig.", "*stemmt die Füße fest in den aufgewühlten Boden; legt die Füße breit und wartet auf die ersten ungeduldigen Hiebe.*" },
        MOCKING_BLOW = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Seid Ihr tatsächlich gefährlich oder nur besonders laut?", "*stemmt die Füße fest in den aufgewühlten Boden; lässt die Spitze absichtlich zu tief sinken und lockt den Gegner näher.*", "Ein Krieger ohne Verantwortung ist nur ein lauter Narr. Oh, verzeiht. Ich hatte Euch für einen Übungsgegner gehalten.", "*fährt mit dem Daumen über eine Kerbe am Waffenstiel; setzt einen frechen Hieb und grinst hinter dem Schild hervor.*" },
        BERSERKER_RAGE = { "Mein Zorn ist heiß. Meine Absicht bleibt klar. Angst? Die hat heute keinen Platz in meinem Kopf.", "*fährt mit dem Daumen über eine Kerbe am Waffenstiel; schüttelt die Schultern aus, als würde eine unsichtbare Last abfallen.*", "Die Ahnen sollen an meinem Stand erkennen, wer ich bin. Meine Furcht darf draußen warten. Meine Wut kommt mit.", "*stößt einen kurzen rauen Atemlaut aus; stößt die Luft aus, strafft den Nacken und hält den Blick fest.*" },
        BLOODRAGE = { "Mein Zorn ist heiß. Meine Absicht bleibt klar. Schmerz ist eine Nachricht. Ich antworte später.", "*stößt einen kurzen rauen Atemlaut aus; schlägt die Faust gegen die Brust und sammelt neuen Kampfeswillen.*", "Ich werde nicht hinter anderen stehen und sie allein lassen. Das Herz schlägt. Mehr muss es gerade nicht erklären.", "*strafft den Lederwickel um den Griff der Waffe; beißt die Zähne zusammen und spannt die Schultern unter der Rüstung.*" },
        DISARM = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Ihr habt ein schönes Schwert. Darf ich es kurz sehen?", "*strafft den Lederwickel um den Griff der Waffe; versucht, die gegnerische Waffe mit einer knappen Drehung aus der Hand zu hebeln.*", "Meine Axt kennt die Wahrheit über Prahlerei. Mal sehen, ob Ihr auch ohne Waffe so gesprächig seid.", "*schlägt die Faust gegen eine alte Clanmarkierung; versucht, den Griff der gegnerischen Waffe abzufangen und aus der Linie zu drehen.*" },
        INTIMIDATING_SHOUT = { "Der Clan soll meine Stimme bis zum letzten Krieger hören! Lauft, solange Ihr noch wisst, wohin!", "*schlägt die Faust gegen eine alte Clanmarkierung; schleudert einen wilden Schrei über die Köpfe der Gegner hinweg.*", "Ein Krieger ohne Verantwortung ist nur ein lauter Narr. Das war die freundliche Warnung. Die zweite kommt mit Stahl.", "*zeigt die Hauer in einem entschlossenen Grinsen; schlägt donnernd gegen den Schild und bleckt die Zähne.*" },
        CHALLENGING_SHOUT = { "Der Clan soll meine Stimme bis zum letzten Krieger hören! ALLE ZU MIR! Ich habe Platz für Euren ganzen Ärger!", "*zeigt die Hauer in einem entschlossenen Grinsen; reißt beide Arme auseinander und fordert die feindliche Reihe heraus.*", "Die Ahnen sollen an meinem Stand erkennen, wer ich bin. Lasst die anderen in Ruhe. Ich bin heute Euer Problem!", "*stemmt die Füße fest in den aufgewühlten Boden; schlägt mehrmals auf den Schild und brüllt die Gegner an.*" },
        SLAM = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Das ist kein Hammer. Es fühlt sich gleich aber so an.", "*stemmt die Füße fest in den aufgewühlten Boden; holt über die Schulter aus und lässt den Stahl mit voller Kraft niederfahren.*", "Ich werde nicht hinter anderen stehen und sie allein lassen. Lieber ein sauberer Treffer als fünf halbe.", "*fährt mit dem Daumen über eine Kerbe am Waffenstiel; lässt die Waffe nach kurzem Zögern mit dem ganzen Gewicht folgen.*" },
        DEVASTATE = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Schon locker? Dann lösen wir den Rest auch noch.", "*fährt mit dem Daumen über eine Kerbe am Waffenstiel; schlägt hart auf eine bereits angeschlagene Stelle der Rüstung.*", "Meine Axt kennt die Wahrheit über Prahlerei. Ich sehe, der Schmied hat an der falschen Stelle gespart.", "*stößt einen kurzen rauen Atemlaut aus; klopft prüfend gegen die offene Fuge und setzt entschlossen nach.*" },
        SHIELD_SLAM = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Ein Schild kann auch Türen schließen. Auf Nasenhöhe.", "*stößt einen kurzen rauen Atemlaut aus; reißt den Schild aus der Deckung und stößt dessen Kante kraftvoll nach vorn.*", "Ein Krieger ohne Verantwortung ist nur ein lauter Narr. Wer sagt, Verteidigung sei höflich?", "*strafft den Lederwickel um den Griff der Waffe; macht einen kurzen Satz vorwärts und lässt den Schild sprechen.*" },
        CONCUSSION_BLOW = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Ich versuche, Euch aus dem Takt zu bringen.", "*strafft den Lederwickel um den Griff der Waffe; versucht, einen schweren Hieb in die Lücke zwischen zwei Bewegungen zu führen.*", "Die Ahnen sollen an meinem Stand erkennen, wer ich bin. Ich versuche, allen einen Augenblick Ruhe zu verschaffen.", "*schlägt die Faust gegen eine alte Clanmarkierung; verkürzt den Griff und schwingt mit überraschender Wucht.*" },
        VICTORY_RUSH = { "Wer Mut hat, wartet nicht auf den zweiten Ruf. Einer weniger. Die anderen stehen noch.", "*schlägt die Faust gegen eine alte Clanmarkierung; nutzt den gewonnenen Atemzug, richtet sich auf und prescht weiter.*", "Ich werde nicht hinter anderen stehen und sie allein lassen. Feiern können wir später. Da bewegt sich noch etwas.", "*zeigt die Hauer in einem entschlossenen Grinsen; klopft sich einmal auf die Brust und setzt sofort nach.*" },
        BATTLE_STANCE = { "Die Ahnen loben keinen Sieg, den Dummheit erkauft. Zwischen Mut und Dummheit liegen manchmal nur zwei Fußbreit.", "*zeigt die Hauer in einem entschlossenen Grinsen; setzt die Stiefel schulterbreit auf und lässt die Waffe locker kreisen.*", "Meine Axt kennt die Wahrheit über Prahlerei. Ich bleibe beweglich. Der Rest darf sich entscheiden.", "*stemmt die Füße fest in den aufgewühlten Boden; wiegt das Gewicht zwischen Schildarm und Waffenhand aus.*" },
        DEFENSIVE_STANCE = { "Eine gebrochene Reihe ist eine gebrochene Pflicht. Wer an meine Leute will, muss zuerst meinen Schild überzeugen.", "*stemmt die Füße fest in den aufgewühlten Boden; stellt die Beine breit und hält den Schild vor die Verbündeten.*", "Ein Krieger ohne Verantwortung ist nur ein lauter Narr. Heute gewinnt nicht, wer am lautesten brüllt.", "*fährt mit dem Daumen über eine Kerbe am Waffenstiel; senkt den Schwerpunkt und wird hinter der Deckung nahezu unbeweglich.*" },
        BERSERKER_STANCE = { "Mein Zorn ist heiß. Meine Absicht bleibt klar. Wer behauptet, Wut mache blind, hat nie richtig hingesehen.", "*fährt mit dem Daumen über eine Kerbe am Waffenstiel; atmet tief ein, hebt das Kinn und nimmt eine wilde Haltung ein.*", "Die Ahnen sollen an meinem Stand erkennen, wer ich bin. Die Welt wird plötzlich sehr einfach: vorwärts.", "*stößt einen kurzen rauen Atemlaut aus; lockert die Schultern, lässt die Waffe sinken und reißt sie schlagartig hoch.*" },
        PIERCING_HOWL = { "Der Clan soll meine Stimme bis zum letzten Krieger hören! Wenn Ihr den Ruf hört, seid Ihr schon zu nah.", "*stößt einen kurzen rauen Atemlaut aus; heult so durchdringend, dass die Stimmen umher für einen Moment verstummen.*", "Ich werde nicht hinter anderen stehen und sie allein lassen. Nein, das war kein Wolfsrudel. Nur ich.", "*strafft den Lederwickel um den Griff der Waffe; wirft den Kopf zurück und lässt einen rauen, langen Laut los.*" },
        SPEARING_STRIKE = { "Ehre verdient man nicht mit Reden, sondern mit Taten. Die Lücke ist schmal. Meine Spitze nicht.", "*strafft den Lederwickel um den Griff der Waffe; führt die Waffe mit einem einzigen geraden Schritt nach vorn.*", "Meine Axt kennt die Wahrheit über Prahlerei. Rüstung ist stark. Winkel sind stärker.", "*schlägt die Faust gegen eine alte Clanmarkierung; dreht das Handgelenk, zielt auf die Schwachstelle und stößt vor.*" },
        TACTICAL_MASTERY = { "Die Ahnen loben keinen Sieg, den Dummheit erkauft. Der Unterschied zwischen Mut und Übermut ist eine gute Fußstellung.", "*schlägt die Faust gegen eine alte Clanmarkierung; verändert unmerklich den Stand und bewahrt die Übersicht.*", "Ein Krieger ohne Verantwortung ist nur ein lauter Narr. Ein Schlachtfeld ist kein Würfelspiel. Es wird gelesen.", "*zeigt die Hauer in einem entschlossenen Grinsen; mustert Wege, Gegner und Rückzugsräume, ohne die Waffe zu senken.*" },
    },
    TROLL = {
        HEROIC_STRIKE = { "Die Loa mögen aufpassen, hier wird's lebhaft. Wisst Ihr, warum meine Waffe so schwer ist? Sie widerspricht selten.", "*berührt einen kleinen Talisman am Gürtel; verlegt das Gewicht auf den vorderen Fuß und führt einen wuchtigen Hieb.*", "Das ist ein guter Tag für eine neue Geschichte, heh. Es gibt Argumente, die brauchen keinen zweiten Satz.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; schiebt die Schulter nach und lässt den Stahl sprechen.*" },
        CHARGE = { "Meine Füße kennen Wege, die andere nicht mal sehen. Wenn der Weg versperrt ist, nehme ich eben den direkten.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; senkt die Schulter, stößt sich ab und wirbelt Staub auf.*", "Wenn die Loa grinsen, grinse ich zurück. Ich komme! Das ist keine Warnung, sondern eine Wegbeschreibung!", "*streift den Daumen über eine geschnitzte Ahnenmarke; prescht mit einem lauten Scheppern durch die Lücke in der Reihe.*" },
        REND = { "Die Loa mögen aufpassen, hier wird's lebhaft. Rüstungsnähte sind kleine Geheimnisse. Ich bin neugierig.", "*streift den Daumen über eine geschnitzte Ahnenmarke; führt die Schneide schräg über eine schlecht geschützte Stelle.*", "Manche nennen es Glück. Ich nenne es Übung. Ein Schneider wäre entsetzt. Ich bin zufrieden.", "*grinst schief und legt das Gewicht nach vorn; zieht die Klinge rasch zurück und sucht die nächste Öffnung.*" },
        HAMSTRING = { "Die Loa mögen aufpassen, hier wird's lebhaft. Weglaufen? Das ist ein Plan mit Schwächen.", "*grinst schief und legt das Gewicht nach vorn; taucht tief unter der gegnerischen Deckung hindurch.*", "Die Ahnen sehen alles. Besonders die lustigen Fehler. Ich schlage nicht gern zweimal hinterher. Einmal genügt.", "*klopft mit zwei Fingern einen schnellen Takt; führt die Waffe knapp über den Boden und richtet sich sofort wieder auf.*" },
        THUNDER_CLAP = { "Die Loa mögen aufpassen, hier wird's lebhaft. Wenn der Boden bebt, brauchen wir keinen Trommler mehr.", "*klopft mit zwei Fingern einen schnellen Takt; stampft mit solcher Wucht auf, dass Staub vom Boden springt.*", "Das ist ein guter Tag für eine neue Geschichte, heh. Hört Ihr das? Die Erde erhebt Einspruch.", "*zieht eine kleine Knochenperle unter der Rüstung hervor; reißt die Arme auseinander und lässt einen dumpfen Schlag durch die Reihen grollen.*" },
        CLEAVE = { "Der alte Hexendoktor hätte dazu nur gelacht. Wer nebeneinander antritt, teilt sich auch die Probleme.", "*zieht eine kleine Knochenperle unter der Rüstung hervor; schwingt die Waffe in einem breiten Bogen quer durch den Kampfraum.*", "Wenn die Loa grinsen, grinse ich zurück. Ich hoffe, Ihr habt alle genug Abstand. Ich nicht.", "*berührt einen kleinen Talisman am Gürtel; dreht auf der Ferse und nimmt den Schwung in den nächsten Bogen mit.*" },
        EXECUTE = { "Die Loa mögen aufpassen, hier wird's lebhaft. Ich habe Euch jede Gelegenheit zum Rückzug gelassen.", "*berührt einen kleinen Talisman am Gürtel; wartet einen Herzschlag ab und führt dann einen endgültig wirkenden Hieb.*", "Manche nennen es Glück. Ich nenne es Übung. Jetzt wird nicht mehr verhandelt.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; fasst den Griff fester und schließt die letzte Lücke.*" },
        SUNDER_ARMOR = { "Die Loa mögen aufpassen, hier wird's lebhaft. Schöner Harnisch. Schade um die Nieten.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; setzt die Waffe gezielt an einer lockeren Rüstungskante an.*", "Die Ahnen sehen alles. Besonders die lustigen Fehler. Teurer Stahl ist noch keine gute Deckung.", "*streift den Daumen über eine geschnitzte Ahnenmarke; zieht mit der Schneide eine Linie entlang einer Naht im Metall.*" },
        SHIELD_BLOCK = { "Auch ein Troll weiß, wann man stehen bleiben muss. Da müsst Ihr schon anklopfen. Der Schild bleibt zu.", "*streift den Daumen über eine geschnitzte Ahnenmarke; dreht die Schildkante in den kommenden Schlag und federt ihn ab.*", "Das ist ein guter Tag für eine neue Geschichte, heh. Ein gutes Schild hört zu, bevor es antwortet.", "*grinst schief und legt das Gewicht nach vorn; stemmt die Stiefel in den Boden und lässt die Deckung nicht nachgeben.*" },
        SHIELD_BASH = { "Die Loa mögen aufpassen, hier wird's lebhaft. Psst. Mal sehen, ob ich Euren Zauber unterbrechen kann.", "*grinst schief und legt das Gewicht nach vorn; rammt die Schildfläche nach vorn, genau zwischen zwei Silben.*", "Wenn die Loa grinsen, grinse ich zurück. Meine Antwort auf Magie hat einen Holzgriff.", "*klopft mit zwei Fingern einen schnellen Takt; rückt einen Schritt heran und stößt unvermittelt mit dem Schild zu.*" },
        TAUNT = { "Die Loa mögen aufpassen, hier wird's lebhaft. Hier drüben! Der Ärger hat heute meinen Namen.", "*klopft mit zwei Fingern einen schnellen Takt; klopft mit dem Schwertknauf dreimal provokant auf den Schild.*", "Manche nennen es Glück. Ich nenne es Übung. Die anderen haben Wichtigeres zu tun. Ich nicht.", "*zieht eine kleine Knochenperle unter der Rüstung hervor; tritt demonstrativ aus der Reihe und winkt die Gegner heran.*" },
        BATTLE_SHOUT = { "Die Ahnen hören mit, also macht ordentlich Lärm! Schultern hoch, Reihen schließen! Heute fällt hier niemand allein!", "*zieht eine kleine Knochenperle unter der Rüstung hervor; schlägt den Schwertknauf im Takt gegen den Schildrand.*", "Die Ahnen sehen alles. Besonders die lustigen Fehler. Ihr habt Beine zum Stehen und Herzen zum Durchhalten. Nutzt beides!", "*berührt einen kleinen Talisman am Gürtel; richtet sich vor den Verbündeten auf und hebt die Klinge hoch.*" },
        DEMORALIZING_SHOUT = { "Die Ahnen hören mit, also macht ordentlich Lärm! Die Ersten von Euch zittern schon. Die Letzten merken es gleich!", "*berührt einen kleinen Talisman am Gürtel; lässt einen tiefen, rauen Schlachtruf aus voller Brust erschallen.*", "Das ist ein guter Tag für eine neue Geschichte, heh. Schaut Euch um. Für wen wollt Ihr eigentlich noch kämpfen?", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; zeigt mit der Klinge auf die wankende feindliche Linie.*" },
        REVENGE = { "Die Loa mögen aufpassen, hier wird's lebhaft. Danke für die Gelegenheit. Die kommt sofort zurück.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; lenkt die Waffe ab und fährt in die entstandene Lücke.*", "Wenn die Loa grinsen, grinse ich zurück. Ich vergesse Gesichter. Schläge nicht.", "*streift den Daumen über eine geschnitzte Ahnenmarke; dreht sich aus der Abwehr direkt in den Gegenangriff.*" },
        OVERPOWER = { "Die Loa mögen aufpassen, hier wird's lebhaft. Da war eine Lücke. Ihr habt sie mir geschenkt.", "*streift den Daumen über eine geschnitzte Ahnenmarke; gleitet an der vorbeigehenden Waffe vorbei und nutzt den offenen Winkel.*", "Manche nennen es Glück. Ich nenne es Übung. Wer danebenhaut, lädt mich ein.", "*grinst schief und legt das Gewicht nach vorn; nutzt eine missratene Bewegung für einen schnellen Gegenstoß.*" },
        MORTAL_STRIKE = { "Die Loa mögen aufpassen, hier wird's lebhaft. Ich spare mir den zweiten Versuch.", "*grinst schief und legt das Gewicht nach vorn; nimmt die Waffe fest in beide Hände und legt den ganzen Körper in einen einzigen Schlag.*", "Die Ahnen sehen alles. Besonders die lustigen Fehler. Manche Duelle enden mit einem Satz. Dieses nicht.", "*klopft mit zwei Fingern einen schnellen Takt; schreitet voran und führt den Stahl mit unerbittlicher Präzision.*" },
        WHIRLWIND = { "Der alte Hexendoktor hätte dazu nur gelacht. Stellt Euch ruhig im Kreis auf. Es ist praktisch.", "*klopft mit zwei Fingern einen schnellen Takt; dreht sich mitsamt der Waffe durch eine Schneise im Gedränge.*", "Das ist ein guter Tag für eine neue Geschichte, heh. Ich teile gern. Heute Stahl.", "*zieht eine kleine Knochenperle unter der Rüstung hervor; lässt die Klinge in weitem Schwung ringsum singen.*" },
        BLOODTHIRST = { "Die Trommel im Herzen schlägt heute schneller. Der Puls wird schneller. Die Hand bleibt ruhig.", "*zieht eine kleine Knochenperle unter der Rüstung hervor; atmet scharf aus, reißt die Waffe hoch und setzt unerbittlich nach.*", "Wenn die Loa grinsen, grinse ich zurück. Nur weil ich zornig bin, bin ich noch lange nicht ungenau.", "*berührt einen kleinen Talisman am Gürtel; treibt mit wilden Augen, aber kontrolliertem Griff den Angriff voran.*" },
        INTERCEPT = { "Nicht weglaufen, mon. Ich bin gleich da!", "*berührt einen kleinen Talisman am Gürtel; stürzt seitlich aus dem Kampfgetümmel und schneidet den Weg ab.*", "Manche nennen es Glück. Ich nenne es Übung. Ihr rennt? Wie aufmerksam, ich wollte mich ohnehin bewegen.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; stößt sich aus dem Stand ab und landet mitten in der Fluchtlinie.*" },
        PUMMEL = { "Die Loa mögen aufpassen, hier wird's lebhaft. Zu viele Worte. Zu wenig Deckung.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; stört die Zauberbewegung mit einem raschen, gezielten Stoß.*", "Die Ahnen sehen alles. Besonders die lustigen Fehler. Wolltet Ihr noch etwas sagen? Nein? Gut.", "*streift den Daumen über eine geschnitzte Ahnenmarke; bringt den gegnerischen Arm mit einem knappen Schlag aus dem Takt.*" },
        SWEEPING_STRIKES = { "Der alte Hexendoktor hätte dazu nur gelacht. Wenn schon Arbeit, dann richtig.", "*streift den Daumen über eine geschnitzte Ahnenmarke; lässt den ersten Hieb in einen zweiten Bogen übergehen.*", "Das ist ein guter Tag für eine neue Geschichte, heh. Mehrere Gegner? Spart Wege.", "*grinst schief und legt das Gewicht nach vorn; nimmt den Schwung nicht zurück, sondern führt ihn durch das Getümmel weiter.*" },
        DEATH_WISH = { "Die Trommel im Herzen schlägt heute schneller. Die Vernunft hat gesprochen. Ich habe ihr widersprochen.", "*grinst schief und legt das Gewicht nach vorn; lockert den Griff für einen Augenblick und stürzt sich entschlossen nach vorn.*", "Wenn die Loa grinsen, grinse ich zurück. Ich weiß, was ich riskiere. Die anderen vielleicht nicht.", "*klopft mit zwei Fingern einen schnellen Takt; wirft einen letzten Blick auf die eigene Deckung und entscheidet sich für den Angriff.*" },
        RECKLESSNESS = { "Die Trommel im Herzen schlägt heute schneller. Vorsicht war gestern. Heute wird gehandelt.", "*klopft mit zwei Fingern einen schnellen Takt; verliert jede Zurückhaltung, ohne die Waffe aus der Hand zu lassen.*", "Manche nennen es Glück. Ich nenne es Übung. Morgen darf man mich dafür ausschimpfen. Wenn wir ein Morgen haben.", "*zieht eine kleine Knochenperle unter der Rüstung hervor; setzt den ganzen Körper in eine wilde Folge von Angriffen.*" },
        LAST_STAND = { "Auch ein Troll weiß, wann man stehen bleiben muss. Bis hierher und keinen Schritt weiter.", "*zieht eine kleine Knochenperle unter der Rüstung hervor; stemmt sich mühsam auf und hebt den Schild noch einmal.*", "Die Ahnen sehen alles. Besonders die lustigen Fehler. Ich stehe noch. Das muss als Antwort genügen.", "*berührt einen kleinen Talisman am Gürtel; stellt sich trotz zitternder Beine erneut schützend in die Bresche.*" },
        SHIELD_WALL = { "Auch ein Troll weiß, wann man stehen bleiben muss. Hinter mir. Keine Heldentaten auf eigene Rechnung!", "*berührt einen kleinen Talisman am Gürtel; zieht das Schild dicht heran und verhakt die Schulter in der Linie.*", "Das ist ein guter Tag für eine neue Geschichte, heh. Wer durch mich hindurch will, braucht einen langen Atem.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; schließt die letzte Lücke zwischen Schild und Rüstung.*" },
        RETALIATION = { "Die Loa mögen aufpassen, hier wird's lebhaft. Wer austeilt, muss das Echo mögen.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; öffnet die Deckung einen Spalt und beantwortet jeden Angriff mit Stahl.*", "Wenn die Loa grinsen, grinse ich zurück. Kommt nur. Ich habe für jeden einen Augenblick übrig.", "*streift den Daumen über eine geschnitzte Ahnenmarke; legt die Füße breit und wartet auf die ersten ungeduldigen Hiebe.*" },
        MOCKING_BLOW = { "Heh! War das Euer bester Schlag? Die Loa werden lachen.", "*streift den Daumen über eine geschnitzte Ahnenmarke; lässt die Spitze absichtlich zu tief sinken und lockt den Gegner näher.*", "Manche nennen es Glück. Ich nenne es Übung. Oh, verzeiht. Ich hatte Euch für einen Übungsgegner gehalten.", "*grinst schief und legt das Gewicht nach vorn; setzt einen frechen Hieb und grinst hinter dem Schild hervor.*" },
        BERSERKER_RAGE = { "Die Trommel im Herzen schlägt heute schneller. Angst? Die hat heute keinen Platz in meinem Kopf.", "*grinst schief und legt das Gewicht nach vorn; schüttelt die Schultern aus, als würde eine unsichtbare Last abfallen.*", "Die Ahnen sehen alles. Besonders die lustigen Fehler. Meine Furcht darf draußen warten. Meine Wut kommt mit.", "*klopft mit zwei Fingern einen schnellen Takt; stößt die Luft aus, strafft den Nacken und hält den Blick fest.*" },
        BLOODRAGE = { "Die Trommel im Herzen schlägt heute schneller. Schmerz ist eine Nachricht. Ich antworte später.", "*klopft mit zwei Fingern einen schnellen Takt; schlägt die Faust gegen die Brust und sammelt neuen Kampfeswillen.*", "Das ist ein guter Tag für eine neue Geschichte, heh. Das Herz schlägt. Mehr muss es gerade nicht erklären.", "*zieht eine kleine Knochenperle unter der Rüstung hervor; beißt die Zähne zusammen und spannt die Schultern unter der Rüstung.*" },
        DISARM = { "Die Loa mögen aufpassen, hier wird's lebhaft. Ihr habt ein schönes Schwert. Darf ich es kurz sehen?", "*zieht eine kleine Knochenperle unter der Rüstung hervor; versucht, die gegnerische Waffe mit einer knappen Drehung aus der Hand zu hebeln.*", "Wenn die Loa grinsen, grinse ich zurück. Mal sehen, ob Ihr auch ohne Waffe so gesprächig seid.", "*berührt einen kleinen Talisman am Gürtel; versucht, den Griff der gegnerischen Waffe abzufangen und aus der Linie zu drehen.*" },
        INTIMIDATING_SHOUT = { "Die Ahnen hören mit, also macht ordentlich Lärm! Lauft, solange Ihr noch wisst, wohin!", "*berührt einen kleinen Talisman am Gürtel; schleudert einen wilden Schrei über die Köpfe der Gegner hinweg.*", "Manche nennen es Glück. Ich nenne es Übung. Das war die freundliche Warnung. Die zweite kommt mit Stahl.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; schlägt donnernd gegen den Schild und bleckt die Zähne.*" },
        CHALLENGING_SHOUT = { "Die Ahnen hören mit, also macht ordentlich Lärm! ALLE ZU MIR! Ich habe Platz für Euren ganzen Ärger!", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; reißt beide Arme auseinander und fordert die feindliche Reihe heraus.*", "Die Ahnen sehen alles. Besonders die lustigen Fehler. Lasst die anderen in Ruhe. Ich bin heute Euer Problem!", "*streift den Daumen über eine geschnitzte Ahnenmarke; schlägt mehrmals auf den Schild und brüllt die Gegner an.*" },
        SLAM = { "Die Loa mögen aufpassen, hier wird's lebhaft. Das ist kein Hammer. Es fühlt sich gleich aber so an.", "*streift den Daumen über eine geschnitzte Ahnenmarke; holt über die Schulter aus und lässt den Stahl mit voller Kraft niederfahren.*", "Das ist ein guter Tag für eine neue Geschichte, heh. Lieber ein sauberer Treffer als fünf halbe.", "*grinst schief und legt das Gewicht nach vorn; lässt die Waffe nach kurzem Zögern mit dem ganzen Gewicht folgen.*" },
        DEVASTATE = { "Die Loa mögen aufpassen, hier wird's lebhaft. Schon locker? Dann lösen wir den Rest auch noch.", "*grinst schief und legt das Gewicht nach vorn; schlägt hart auf eine bereits angeschlagene Stelle der Rüstung.*", "Wenn die Loa grinsen, grinse ich zurück. Ich sehe, der Schmied hat an der falschen Stelle gespart.", "*klopft mit zwei Fingern einen schnellen Takt; klopft prüfend gegen die offene Fuge und setzt entschlossen nach.*" },
        SHIELD_SLAM = { "Die Loa mögen aufpassen, hier wird's lebhaft. Ein Schild kann auch Türen schließen. Auf Nasenhöhe.", "*klopft mit zwei Fingern einen schnellen Takt; reißt den Schild aus der Deckung und stößt dessen Kante kraftvoll nach vorn.*", "Manche nennen es Glück. Ich nenne es Übung. Wer sagt, Verteidigung sei höflich?", "*zieht eine kleine Knochenperle unter der Rüstung hervor; macht einen kurzen Satz vorwärts und lässt den Schild sprechen.*" },
        CONCUSSION_BLOW = { "Die Loa mögen aufpassen, hier wird's lebhaft. Ich versuche, Euch aus dem Takt zu bringen.", "*zieht eine kleine Knochenperle unter der Rüstung hervor; versucht, einen schweren Hieb in die Lücke zwischen zwei Bewegungen zu führen.*", "Die Ahnen sehen alles. Besonders die lustigen Fehler. Ich versuche, allen einen Augenblick Ruhe zu verschaffen.", "*berührt einen kleinen Talisman am Gürtel; verkürzt den Griff und schwingt mit überraschender Wucht.*" },
        VICTORY_RUSH = { "Heh! Einer für die Ahnen, der nächste für mich!", "*berührt einen kleinen Talisman am Gürtel; nutzt den gewonnenen Atemzug, richtet sich auf und prescht weiter.*", "Das ist ein guter Tag für eine neue Geschichte, heh. Feiern können wir später. Da bewegt sich noch etwas.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; klopft sich einmal auf die Brust und setzt sofort nach.*" },
        BATTLE_STANCE = { "Der alte Hexendoktor hätte dazu nur gelacht. Zwischen Mut und Dummheit liegen manchmal nur zwei Fußbreit.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; setzt die Stiefel schulterbreit auf und lässt die Waffe locker kreisen.*", "Wenn die Loa grinsen, grinse ich zurück. Ich bleibe beweglich. Der Rest darf sich entscheiden.", "*streift den Daumen über eine geschnitzte Ahnenmarke; wiegt das Gewicht zwischen Schildarm und Waffenhand aus.*" },
        DEFENSIVE_STANCE = { "Auch ein Troll weiß, wann man stehen bleiben muss. Wer an meine Leute will, muss zuerst meinen Schild überzeugen.", "*streift den Daumen über eine geschnitzte Ahnenmarke; stellt die Beine breit und hält den Schild vor die Verbündeten.*", "Manche nennen es Glück. Ich nenne es Übung. Heute gewinnt nicht, wer am lautesten brüllt.", "*grinst schief und legt das Gewicht nach vorn; senkt den Schwerpunkt und wird hinter der Deckung nahezu unbeweglich.*" },
        BERSERKER_STANCE = { "Die Trommel im Herzen schlägt heute schneller. Wer behauptet, Wut mache blind, hat nie richtig hingesehen.", "*grinst schief und legt das Gewicht nach vorn; atmet tief ein, hebt das Kinn und nimmt eine wilde Haltung ein.*", "Die Ahnen sehen alles. Besonders die lustigen Fehler. Die Welt wird plötzlich sehr einfach: vorwärts.", "*klopft mit zwei Fingern einen schnellen Takt; lockert die Schultern, lässt die Waffe sinken und reißt sie schlagartig hoch.*" },
        PIERCING_HOWL = { "Das war kein Wolf, mon. Nur mein schlechter Morgengesang.", "*klopft mit zwei Fingern einen schnellen Takt; heult so durchdringend, dass die Stimmen umher für einen Moment verstummen.*", "Das ist ein guter Tag für eine neue Geschichte, heh. Nein, das war kein Wolfsrudel. Nur ich.", "*zieht eine kleine Knochenperle unter der Rüstung hervor; wirft den Kopf zurück und lässt einen rauen, langen Laut los.*" },
        SPEARING_STRIKE = { "Die Loa mögen aufpassen, hier wird's lebhaft. Die Lücke ist schmal. Meine Spitze nicht.", "*zieht eine kleine Knochenperle unter der Rüstung hervor; führt die Waffe mit einem einzigen geraden Schritt nach vorn.*", "Wenn die Loa grinsen, grinse ich zurück. Rüstung ist stark. Winkel sind stärker.", "*berührt einen kleinen Talisman am Gürtel; dreht das Handgelenk, zielt auf die Schwachstelle und stößt vor.*" },
        TACTICAL_MASTERY = { "Der alte Hexendoktor hätte dazu nur gelacht. Der Unterschied zwischen Mut und Übermut ist eine gute Fußstellung.", "*berührt einen kleinen Talisman am Gürtel; verändert unmerklich den Stand und bewahrt die Übersicht.*", "Manche nennen es Glück. Ich nenne es Übung. Ein Schlachtfeld ist kein Würfelspiel. Es wird gelesen.", "*wiegt den Körper für einen Atemzug im Trommelrhythmus; mustert Wege, Gegner und Rückzugsräume, ohne die Waffe zu senken.*" },
    },
    TAUREN = {
        HEROIC_STRIKE = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Wisst Ihr, warum meine Waffe so schwer ist? Sie widerspricht selten.", "*senkt die Hörner mit ernster Ruhe; verlegt das Gewicht auf den vorderen Fuß und führt einen wuchtigen Hieb.*", "Die Erdenmutter kennt meine Gründe. Es gibt Argumente, die brauchen keinen zweiten Satz.", "*verankert beide Hufe im Boden; schiebt die Schulter nach und lässt den Stahl sprechen.*" },
        CHARGE = { "Wenn die Herde zieht, hält kein Zaun sie auf. Wenn der Weg versperrt ist, nehme ich eben den direkten.", "*verankert beide Hufe im Boden; senkt die Schulter, stößt sich ab und wirbelt Staub auf.*", "Stärke gehört dem, der sie zum Schutz anderer einsetzt. Ich komme! Das ist keine Warnung, sondern eine Wegbeschreibung!", "*berührt die geflochtene Erinnerung am Waffenstiel; prescht mit einem lauten Scheppern durch die Lücke in der Reihe.*" },
        REND = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Rüstungsnähte sind kleine Geheimnisse. Ich bin neugierig.", "*berührt die geflochtene Erinnerung am Waffenstiel; führt die Schneide schräg über eine schlecht geschützte Stelle.*", "Mein Atem bleibt ruhig. Der Boden unter mir nicht. Ein Schneider wäre entsetzt. Ich bin zufrieden.", "*atmet langsam durch die Nüstern; zieht die Klinge rasch zurück und sucht die nächste Öffnung.*" },
        HAMSTRING = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Weglaufen? Das ist ein Plan mit Schwächen.", "*atmet langsam durch die Nüstern; taucht tief unter der gegnerischen Deckung hindurch.*", "Wer die Ebene versteht, weiß, wann es Zeit ist zu stehen. Ich schlage nicht gern zweimal hinterher. Einmal genügt.", "*neigt den Kopf einen Augenblick zur Erde; führt die Waffe knapp über den Boden und richtet sich sofort wieder auf.*" },
        THUNDER_CLAP = { "Der Donner erinnert sich an jeden Schritt über die Ebene.", "*neigt den Kopf einen Augenblick zur Erde; stampft mit solcher Wucht auf, dass Staub vom Boden springt.*", "Die Erdenmutter kennt meine Gründe. Hört Ihr das? Die Erde erhebt Einspruch.", "*rückt ein mit Federn geschmücktes Band zurecht; reißt die Arme auseinander und lässt einen dumpfen Schlag durch die Reihen grollen.*" },
        CLEAVE = { "Eile ist nicht dasselbe wie Entschlossenheit. Wer nebeneinander antritt, teilt sich auch die Probleme.", "*rückt ein mit Federn geschmücktes Band zurecht; schwingt die Waffe in einem breiten Bogen quer durch den Kampfraum.*", "Stärke gehört dem, der sie zum Schutz anderer einsetzt. Ich hoffe, Ihr habt alle genug Abstand. Ich nicht.", "*senkt die Hörner mit ernster Ruhe; dreht auf der Ferse und nimmt den Schwung in den nächsten Bogen mit.*" },
        EXECUTE = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Ich habe Euch jede Gelegenheit zum Rückzug gelassen.", "*senkt die Hörner mit ernster Ruhe; wartet einen Herzschlag ab und führt dann einen endgültig wirkenden Hieb.*", "Mein Atem bleibt ruhig. Der Boden unter mir nicht. Jetzt wird nicht mehr verhandelt.", "*verankert beide Hufe im Boden; fasst den Griff fester und schließt die letzte Lücke.*" },
        SUNDER_ARMOR = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Schöner Harnisch. Schade um die Nieten.", "*verankert beide Hufe im Boden; setzt die Waffe gezielt an einer lockeren Rüstungskante an.*", "Wer die Ebene versteht, weiß, wann es Zeit ist zu stehen. Teurer Stahl ist noch keine gute Deckung.", "*berührt die geflochtene Erinnerung am Waffenstiel; zieht mit der Schneide eine Linie entlang einer Naht im Metall.*" },
        SHIELD_BLOCK = { "Ein Berg weicht nicht für das erste Gewitter. Da müsst Ihr schon anklopfen. Der Schild bleibt zu.", "*berührt die geflochtene Erinnerung am Waffenstiel; dreht die Schildkante in den kommenden Schlag und federt ihn ab.*", "Die Erdenmutter kennt meine Gründe. Ein gutes Schild hört zu, bevor es antwortet.", "*atmet langsam durch die Nüstern; stemmt die Stiefel in den Boden und lässt die Deckung nicht nachgeben.*" },
        SHIELD_BASH = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Psst. Mal sehen, ob ich Euren Zauber unterbrechen kann.", "*atmet langsam durch die Nüstern; rammt die Schildfläche nach vorn, genau zwischen zwei Silben.*", "Stärke gehört dem, der sie zum Schutz anderer einsetzt. Meine Antwort auf Magie hat einen Holzgriff.", "*neigt den Kopf einen Augenblick zur Erde; rückt einen Schritt heran und stößt unvermittelt mit dem Schild zu.*" },
        TAUNT = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Hier drüben! Der Ärger hat heute meinen Namen.", "*neigt den Kopf einen Augenblick zur Erde; klopft mit dem Schwertknauf dreimal provokant auf den Schild.*", "Mein Atem bleibt ruhig. Der Boden unter mir nicht. Die anderen haben Wichtigeres zu tun. Ich nicht.", "*rückt ein mit Federn geschmücktes Band zurecht; tritt demonstrativ aus der Reihe und winkt die Gegner heran.*" },
        BATTLE_SHOUT = { "Möge der Wind unsere Entschlossenheit über die Ebene tragen. Schultern hoch, Reihen schließen! Heute fällt hier niemand allein!", "*rückt ein mit Federn geschmücktes Band zurecht; schlägt den Schwertknauf im Takt gegen den Schildrand.*", "Wer die Ebene versteht, weiß, wann es Zeit ist zu stehen. Ihr habt Beine zum Stehen und Herzen zum Durchhalten. Nutzt beides!", "*senkt die Hörner mit ernster Ruhe; richtet sich vor den Verbündeten auf und hebt die Klinge hoch.*" },
        DEMORALIZING_SHOUT = { "Möge der Wind unsere Entschlossenheit über die Ebene tragen. Die Ersten von Euch zittern schon. Die Letzten merken es gleich!", "*senkt die Hörner mit ernster Ruhe; lässt einen tiefen, rauen Schlachtruf aus voller Brust erschallen.*", "Die Erdenmutter kennt meine Gründe. Schaut Euch um. Für wen wollt Ihr eigentlich noch kämpfen?", "*verankert beide Hufe im Boden; zeigt mit der Klinge auf die wankende feindliche Linie.*" },
        REVENGE = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Danke für die Gelegenheit. Die kommt sofort zurück.", "*verankert beide Hufe im Boden; lenkt die Waffe ab und fährt in die entstandene Lücke.*", "Stärke gehört dem, der sie zum Schutz anderer einsetzt. Ich vergesse Gesichter. Schläge nicht.", "*berührt die geflochtene Erinnerung am Waffenstiel; dreht sich aus der Abwehr direkt in den Gegenangriff.*" },
        OVERPOWER = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Da war eine Lücke. Ihr habt sie mir geschenkt.", "*berührt die geflochtene Erinnerung am Waffenstiel; gleitet an der vorbeigehenden Waffe vorbei und nutzt den offenen Winkel.*", "Mein Atem bleibt ruhig. Der Boden unter mir nicht. Wer danebenhaut, lädt mich ein.", "*atmet langsam durch die Nüstern; nutzt eine missratene Bewegung für einen schnellen Gegenstoß.*" },
        MORTAL_STRIKE = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Ich spare mir den zweiten Versuch.", "*atmet langsam durch die Nüstern; nimmt die Waffe fest in beide Hände und legt den ganzen Körper in einen einzigen Schlag.*", "Wer die Ebene versteht, weiß, wann es Zeit ist zu stehen. Manche Duelle enden mit einem Satz. Dieses nicht.", "*neigt den Kopf einen Augenblick zur Erde; schreitet voran und führt den Stahl mit unerbittlicher Präzision.*" },
        WHIRLWIND = { "Eile ist nicht dasselbe wie Entschlossenheit. Stellt Euch ruhig im Kreis auf. Es ist praktisch.", "*neigt den Kopf einen Augenblick zur Erde; dreht sich mitsamt der Waffe durch eine Schneise im Gedränge.*", "Die Erdenmutter kennt meine Gründe. Ich teile gern. Heute Stahl.", "*rückt ein mit Federn geschmücktes Band zurecht; lässt die Klinge in weitem Schwung ringsum singen.*" },
        BLOODTHIRST = { "Auch die Prärie brennt manchmal, um wieder zu wachsen. Der Puls wird schneller. Die Hand bleibt ruhig.", "*rückt ein mit Federn geschmücktes Band zurecht; atmet scharf aus, reißt die Waffe hoch und setzt unerbittlich nach.*", "Stärke gehört dem, der sie zum Schutz anderer einsetzt. Nur weil ich zornig bin, bin ich noch lange nicht ungenau.", "*senkt die Hörner mit ernster Ruhe; treibt mit wilden Augen, aber kontrolliertem Griff den Angriff voran.*" },
        INTERCEPT = { "Wenn die Herde zieht, hält kein Zaun sie auf. Ein Vorsprung ist nur geliehene Zeit.", "*senkt die Hörner mit ernster Ruhe; stürzt seitlich aus dem Kampfgetümmel und schneidet den Weg ab.*", "Mein Atem bleibt ruhig. Der Boden unter mir nicht. Ihr rennt? Wie aufmerksam, ich wollte mich ohnehin bewegen.", "*verankert beide Hufe im Boden; stößt sich aus dem Stand ab und landet mitten in der Fluchtlinie.*" },
        PUMMEL = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Zu viele Worte. Zu wenig Deckung.", "*verankert beide Hufe im Boden; stört die Zauberbewegung mit einem raschen, gezielten Stoß.*", "Wer die Ebene versteht, weiß, wann es Zeit ist zu stehen. Wolltet Ihr noch etwas sagen? Nein? Gut.", "*berührt die geflochtene Erinnerung am Waffenstiel; bringt den gegnerischen Arm mit einem knappen Schlag aus dem Takt.*" },
        SWEEPING_STRIKES = { "Eile ist nicht dasselbe wie Entschlossenheit. Wenn schon Arbeit, dann richtig.", "*berührt die geflochtene Erinnerung am Waffenstiel; lässt den ersten Hieb in einen zweiten Bogen übergehen.*", "Die Erdenmutter kennt meine Gründe. Mehrere Gegner? Spart Wege.", "*atmet langsam durch die Nüstern; nimmt den Schwung nicht zurück, sondern führt ihn durch das Getümmel weiter.*" },
        DEATH_WISH = { "Auch die Prärie brennt manchmal, um wieder zu wachsen. Die Vernunft hat gesprochen. Ich habe ihr widersprochen.", "*atmet langsam durch die Nüstern; lockert den Griff für einen Augenblick und stürzt sich entschlossen nach vorn.*", "Stärke gehört dem, der sie zum Schutz anderer einsetzt. Ich weiß, was ich riskiere. Die anderen vielleicht nicht.", "*neigt den Kopf einen Augenblick zur Erde; wirft einen letzten Blick auf die eigene Deckung und entscheidet sich für den Angriff.*" },
        RECKLESSNESS = { "Auch die Prärie brennt manchmal, um wieder zu wachsen. Vorsicht war gestern. Heute wird gehandelt.", "*neigt den Kopf einen Augenblick zur Erde; verliert jede Zurückhaltung, ohne die Waffe aus der Hand zu lassen.*", "Mein Atem bleibt ruhig. Der Boden unter mir nicht. Morgen darf man mich dafür ausschimpfen. Wenn wir ein Morgen haben.", "*rückt ein mit Federn geschmücktes Band zurecht; setzt den ganzen Körper in eine wilde Folge von Angriffen.*" },
        LAST_STAND = { "Solange die Erde mich trägt, trägt sie auch meinen Eid.", "*rückt ein mit Federn geschmücktes Band zurecht; stemmt sich mühsam auf und hebt den Schild noch einmal.*", "Wer die Ebene versteht, weiß, wann es Zeit ist zu stehen. Ich stehe noch. Das muss als Antwort genügen.", "*senkt die Hörner mit ernster Ruhe; stellt sich trotz zitternder Beine erneut schützend in die Bresche.*" },
        SHIELD_WALL = { "Hinter meinem Schild dürfen die Jungen weiteratmen.", "*senkt die Hörner mit ernster Ruhe; zieht das Schild dicht heran und verhakt die Schulter in der Linie.*", "Die Erdenmutter kennt meine Gründe. Wer durch mich hindurch will, braucht einen langen Atem.", "*verankert beide Hufe im Boden; schließt die letzte Lücke zwischen Schild und Rüstung.*" },
        RETALIATION = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Wer austeilt, muss das Echo mögen.", "*verankert beide Hufe im Boden; öffnet die Deckung einen Spalt und beantwortet jeden Angriff mit Stahl.*", "Stärke gehört dem, der sie zum Schutz anderer einsetzt. Kommt nur. Ich habe für jeden einen Augenblick übrig.", "*berührt die geflochtene Erinnerung am Waffenstiel; legt die Füße breit und wartet auf die ersten ungeduldigen Hiebe.*" },
        MOCKING_BLOW = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Seid Ihr tatsächlich gefährlich oder nur besonders laut?", "*berührt die geflochtene Erinnerung am Waffenstiel; lässt die Spitze absichtlich zu tief sinken und lockt den Gegner näher.*", "Mein Atem bleibt ruhig. Der Boden unter mir nicht. Oh, verzeiht. Ich hatte Euch für einen Übungsgegner gehalten.", "*atmet langsam durch die Nüstern; setzt einen frechen Hieb und grinst hinter dem Schild hervor.*" },
        BERSERKER_RAGE = { "Auch die Prärie brennt manchmal, um wieder zu wachsen. Angst? Die hat heute keinen Platz in meinem Kopf.", "*atmet langsam durch die Nüstern; schüttelt die Schultern aus, als würde eine unsichtbare Last abfallen.*", "Wer die Ebene versteht, weiß, wann es Zeit ist zu stehen. Meine Furcht darf draußen warten. Meine Wut kommt mit.", "*neigt den Kopf einen Augenblick zur Erde; stößt die Luft aus, strafft den Nacken und hält den Blick fest.*" },
        BLOODRAGE = { "Auch die Prärie brennt manchmal, um wieder zu wachsen. Schmerz ist eine Nachricht. Ich antworte später.", "*neigt den Kopf einen Augenblick zur Erde; schlägt die Faust gegen die Brust und sammelt neuen Kampfeswillen.*", "Die Erdenmutter kennt meine Gründe. Das Herz schlägt. Mehr muss es gerade nicht erklären.", "*rückt ein mit Federn geschmücktes Band zurecht; beißt die Zähne zusammen und spannt die Schultern unter der Rüstung.*" },
