        INTIMIDATING_SHOUT = { "Möge der Wind unsere Entschlossenheit über die Ebene tragen. Lauft, solange Ihr noch wisst, wohin!", "*senkt die Hörner mit ernster Ruhe; schleudert einen wilden Schrei über die Köpfe der Gegner hinweg.*", "Mein Atem bleibt ruhig. Der Boden unter mir nicht. Das war die freundliche Warnung. Die zweite kommt mit Stahl.", "*verankert beide Hufe im Boden; schlägt donnernd gegen den Schild und bleckt die Zähne.*" },
