        DEVASTATE = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Schon locker? Dann lösen wir den Rest auch noch.", "*atmet langsam durch die Nüstern; schlägt hart auf eine bereits angeschlagene Stelle der Rüstung.*", "Stärke gehört dem, der sie zum Schutz anderer einsetzt. Ich sehe, der Schmied hat an der falschen Stelle gespart.", "*neigt den Kopf einen Augenblick zur Erde; klopft prüfend gegen die offene Fuge und setzt entschlossen nach.*" },
        SHIELD_SLAM = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Ein Schild kann auch Türen schließen. Auf Nasenhöhe.", "*neigt den Kopf einen Augenblick zur Erde; reißt den Schild aus der Deckung und stößt dessen Kante kraftvoll nach vorn.*", "Mein Atem bleibt ruhig. Der Boden unter mir nicht. Wer sagt, Verteidigung sei höflich?", "*rückt ein mit Federn geschmücktes Band zurecht; macht einen kurzen Satz vorwärts und lässt den Schild sprechen.*" },
        CONCUSSION_BLOW = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Ich versuche, Euch aus dem Takt zu bringen.", "*rückt ein mit Federn geschmücktes Band zurecht; versucht, einen schweren Hieb in die Lücke zwischen zwei Bewegungen zu führen.*", "Wer die Ebene versteht, weiß, wann es Zeit ist zu stehen. Ich versuche, allen einen Augenblick Ruhe zu verschaffen.", "*senkt die Hörner mit ernster Ruhe; verkürzt den Griff und schwingt mit überraschender Wucht.*" },
        VICTORY_RUSH = { "Wenn die Herde zieht, hält kein Zaun sie auf. Einer weniger. Die anderen stehen noch.", "*senkt die Hörner mit ernster Ruhe; nutzt den gewonnenen Atemzug, richtet sich auf und prescht weiter.*", "Die Erdenmutter kennt meine Gründe. Feiern können wir später. Da bewegt sich noch etwas.", "*verankert beide Hufe im Boden; klopft sich einmal auf die Brust und setzt sofort nach.*" },
        BATTLE_STANCE = { "Eile ist nicht dasselbe wie Entschlossenheit. Zwischen Mut und Dummheit liegen manchmal nur zwei Fußbreit.", "*verankert beide Hufe im Boden; setzt die Stiefel schulterbreit auf und lässt die Waffe locker kreisen.*", "Stärke gehört dem, der sie zum Schutz anderer einsetzt. Ich bleibe beweglich. Der Rest darf sich entscheiden.", "*berührt die geflochtene Erinnerung am Waffenstiel; wiegt das Gewicht zwischen Schildarm und Waffenhand aus.*" },
        DEFENSIVE_STANCE = { "Ein Berg weicht nicht für das erste Gewitter. Wer an meine Leute will, muss zuerst meinen Schild überzeugen.", "*berührt die geflochtene Erinnerung am Waffenstiel; stellt die Beine breit und hält den Schild vor die Verbündeten.*", "Mein Atem bleibt ruhig. Der Boden unter mir nicht. Heute gewinnt nicht, wer am lautesten brüllt.", "*atmet langsam durch die Nüstern; senkt den Schwerpunkt und wird hinter der Deckung nahezu unbeweglich.*" },
        BERSERKER_STANCE = { "Auch die Prärie brennt manchmal, um wieder zu wachsen. Wer behauptet, Wut mache blind, hat nie richtig hingesehen.", "*atmet langsam durch die Nüstern; atmet tief ein, hebt das Kinn und nimmt eine wilde Haltung ein.*", "Wer die Ebene versteht, weiß, wann es Zeit ist zu stehen. Die Welt wird plötzlich sehr einfach: vorwärts.", "*neigt den Kopf einen Augenblick zur Erde; lockert die Schultern, lässt die Waffe sinken und reißt sie schlagartig hoch.*" },
        PIERCING_HOWL = { "Möge der Wind unsere Entschlossenheit über die Ebene tragen. Wenn Ihr den Ruf hört, seid Ihr schon zu nah.", "*neigt den Kopf einen Augenblick zur Erde; heult so durchdringend, dass die Stimmen umher für einen Moment verstummen.*", "Die Erdenmutter kennt meine Gründe. Nein, das war kein Wolfsrudel. Nur ich.", "*rückt ein mit Federn geschmücktes Band zurecht; wirft den Kopf zurück und lässt einen rauen, langen Laut los.*" },
        SPEARING_STRIKE = { "Der Donner kommt ohne Hass. So soll auch mein Schlag sein. Die Lücke ist schmal. Meine Spitze nicht.", "*rückt ein mit Federn geschmücktes Band zurecht; führt die Waffe mit einem einzigen geraden Schritt nach vorn.*", "Stärke gehört dem, der sie zum Schutz anderer einsetzt. Rüstung ist stark. Winkel sind stärker.", "*senkt die Hörner mit ernster Ruhe; dreht das Handgelenk, zielt auf die Schwachstelle und stößt vor.*" },
        TACTICAL_MASTERY = { "Eile ist nicht dasselbe wie Entschlossenheit. Der Unterschied zwischen Mut und Übermut ist eine gute Fußstellung.", "*senkt die Hörner mit ernster Ruhe; verändert unmerklich den Stand und bewahrt die Übersicht.*", "Mein Atem bleibt ruhig. Der Boden unter mir nicht. Ein Schlachtfeld ist kein Würfelspiel. Es wird gelesen.", "*verankert beide Hufe im Boden; mustert Wege, Gegner und Rückzugsräume, ohne die Waffe zu senken.*" },
    },
    UNDEAD = {
        HEROIC_STRIKE = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Wisst Ihr, warum meine Waffe so schwer ist? Sie widerspricht selten.", "*rückt einen losen Handschuh über knochige Finger; verlegt das Gewicht auf den vorderen Fuß und führt einen wuchtigen Hieb.*", "Man hat mich für erledigt gehalten. Mehrfach. Es gibt Argumente, die brauchen keinen zweiten Satz.", "*kippt den Kopf, bis es vernehmlich knackt; schiebt die Schulter nach und lässt den Stahl sprechen.*" },
        CHARGE = { "Schneller als mein eigener Verfall. Das muss reichen. Wenn der Weg versperrt ist, nehme ich eben den direkten.", "*kippt den Kopf, bis es vernehmlich knackt; senkt die Schulter, stößt sich ab und wirbelt Staub auf.*", "Mein letzter Atemzug war nicht mein letztes Wort. Ich komme! Das ist keine Warnung, sondern eine Wegbeschreibung!", "*zieht eine alte Naht am Mantel zurecht; prescht mit einem lauten Scheppern durch die Lücke in der Reihe.*" },
        REND = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Rüstungsnähte sind kleine Geheimnisse. Ich bin neugierig.", "*zieht eine alte Naht am Mantel zurecht; führt die Schneide schräg über eine schlecht geschützte Stelle.*", "Knackende Gelenke sind nur ein höflicher Hinweis. Ein Schneider wäre entsetzt. Ich bin zufrieden.", "*wischt Staub von einer rostigen Rüstungsspange; zieht die Klinge rasch zurück und sucht die nächste Öffnung.*" },
        HAMSTRING = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Weglaufen? Das ist ein Plan mit Schwächen.", "*wischt Staub von einer rostigen Rüstungsspange; taucht tief unter der gegnerischen Deckung hindurch.*", "Ich erinnere mich an meine Fehler. Einige tragen jetzt Rüstung. Ich schlage nicht gern zweimal hinterher. Einmal genügt.", "*prüft den Halt einer brüchigen Gelenkbandage; führt die Waffe knapp über den Boden und richtet sich sofort wieder auf.*" },
        THUNDER_CLAP = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Wenn der Boden bebt, brauchen wir keinen Trommler mehr.", "*prüft den Halt einer brüchigen Gelenkbandage; stampft mit solcher Wucht auf, dass Staub vom Boden springt.*", "Man hat mich für erledigt gehalten. Mehrfach. Hört Ihr das? Die Erde erhebt Einspruch.", "*lässt ein trockenes, kurzes Lachen hören; reißt die Arme auseinander und lässt einen dumpfen Schlag durch die Reihen grollen.*" },
        CLEAVE = { "Ohne Herzschlag bleibt erstaunlich viel Zeit zum Nachdenken. Wer nebeneinander antritt, teilt sich auch die Probleme.", "*lässt ein trockenes, kurzes Lachen hören; schwingt die Waffe in einem breiten Bogen quer durch den Kampfraum.*", "Mein letzter Atemzug war nicht mein letztes Wort. Ich hoffe, Ihr habt alle genug Abstand. Ich nicht.", "*rückt einen losen Handschuh über knochige Finger; dreht auf der Ferse und nimmt den Schwung in den nächsten Bogen mit.*" },
        EXECUTE = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Ich habe Euch jede Gelegenheit zum Rückzug gelassen.", "*rückt einen losen Handschuh über knochige Finger; wartet einen Herzschlag ab und führt dann einen endgültig wirkenden Hieb.*", "Knackende Gelenke sind nur ein höflicher Hinweis. Jetzt wird nicht mehr verhandelt.", "*kippt den Kopf, bis es vernehmlich knackt; fasst den Griff fester und schließt die letzte Lücke.*" },
        SUNDER_ARMOR = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Schöner Harnisch. Schade um die Nieten.", "*kippt den Kopf, bis es vernehmlich knackt; setzt die Waffe gezielt an einer lockeren Rüstungskante an.*", "Ich erinnere mich an meine Fehler. Einige tragen jetzt Rüstung. Teurer Stahl ist noch keine gute Deckung.", "*zieht eine alte Naht am Mantel zurecht; zieht mit der Schneide eine Linie entlang einer Naht im Metall.*" },
        SHIELD_BLOCK = { "Was schon begraben wurde, lässt sich schwer einschüchtern. Da müsst Ihr schon anklopfen. Der Schild bleibt zu.", "*zieht eine alte Naht am Mantel zurecht; dreht die Schildkante in den kommenden Schlag und federt ihn ab.*", "Man hat mich für erledigt gehalten. Mehrfach. Ein gutes Schild hört zu, bevor es antwortet.", "*wischt Staub von einer rostigen Rüstungsspange; stemmt die Stiefel in den Boden und lässt die Deckung nicht nachgeben.*" },
        SHIELD_BASH = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Psst. Mal sehen, ob ich Euren Zauber unterbrechen kann.", "*wischt Staub von einer rostigen Rüstungsspange; rammt die Schildfläche nach vorn, genau zwischen zwei Silben.*", "Mein letzter Atemzug war nicht mein letztes Wort. Meine Antwort auf Magie hat einen Holzgriff.", "*prüft den Halt einer brüchigen Gelenkbandage; rückt einen Schritt heran und stößt unvermittelt mit dem Schild zu.*" },
        TAUNT = { "Ihr wollt einen Albtraum? Ich bin bereits aufgestanden.", "*prüft den Halt einer brüchigen Gelenkbandage; klopft mit dem Schwertknauf dreimal provokant auf den Schild.*", "Knackende Gelenke sind nur ein höflicher Hinweis. Die anderen haben Wichtigeres zu tun. Ich nicht.", "*lässt ein trockenes, kurzes Lachen hören; tritt demonstrativ aus der Reihe und winkt die Gegner heran.*" },
        BATTLE_SHOUT = { "Meine Stimme klingt etwas hohl. Die Drohung nicht. Schultern hoch, Reihen schließen! Heute fällt hier niemand allein!", "*lässt ein trockenes, kurzes Lachen hören; schlägt den Schwertknauf im Takt gegen den Schildrand.*", "Ich erinnere mich an meine Fehler. Einige tragen jetzt Rüstung. Ihr habt Beine zum Stehen und Herzen zum Durchhalten. Nutzt beides!", "*rückt einen losen Handschuh über knochige Finger; richtet sich vor den Verbündeten auf und hebt die Klinge hoch.*" },
        DEMORALIZING_SHOUT = { "Meine Stimme klingt etwas hohl. Die Drohung nicht. Die Ersten von Euch zittern schon. Die Letzten merken es gleich!", "*rückt einen losen Handschuh über knochige Finger; lässt einen tiefen, rauen Schlachtruf aus voller Brust erschallen.*", "Man hat mich für erledigt gehalten. Mehrfach. Schaut Euch um. Für wen wollt Ihr eigentlich noch kämpfen?", "*kippt den Kopf, bis es vernehmlich knackt; zeigt mit der Klinge auf die wankende feindliche Linie.*" },
        REVENGE = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Danke für die Gelegenheit. Die kommt sofort zurück.", "*kippt den Kopf, bis es vernehmlich knackt; lenkt die Waffe ab und fährt in die entstandene Lücke.*", "Mein letzter Atemzug war nicht mein letztes Wort. Ich vergesse Gesichter. Schläge nicht.", "*zieht eine alte Naht am Mantel zurecht; dreht sich aus der Abwehr direkt in den Gegenangriff.*" },
        OVERPOWER = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Da war eine Lücke. Ihr habt sie mir geschenkt.", "*zieht eine alte Naht am Mantel zurecht; gleitet an der vorbeigehenden Waffe vorbei und nutzt den offenen Winkel.*", "Knackende Gelenke sind nur ein höflicher Hinweis. Wer danebenhaut, lädt mich ein.", "*wischt Staub von einer rostigen Rüstungsspange; nutzt eine missratene Bewegung für einen schnellen Gegenstoß.*" },
        MORTAL_STRIKE = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Ich spare mir den zweiten Versuch.", "*wischt Staub von einer rostigen Rüstungsspange; nimmt die Waffe fest in beide Hände und legt den ganzen Körper in einen einzigen Schlag.*", "Ich erinnere mich an meine Fehler. Einige tragen jetzt Rüstung. Manche Duelle enden mit einem Satz. Dieses nicht.", "*prüft den Halt einer brüchigen Gelenkbandage; schreitet voran und führt den Stahl mit unerbittlicher Präzision.*" },
        WHIRLWIND = { "Ohne Herzschlag bleibt erstaunlich viel Zeit zum Nachdenken. Stellt Euch ruhig im Kreis auf. Es ist praktisch.", "*prüft den Halt einer brüchigen Gelenkbandage; dreht sich mitsamt der Waffe durch eine Schneise im Gedränge.*", "Man hat mich für erledigt gehalten. Mehrfach. Ich teile gern. Heute Stahl.", "*lässt ein trockenes, kurzes Lachen hören; lässt die Klinge in weitem Schwung ringsum singen.*" },
        BLOODTHIRST = { "Meine Geduld ist vor Jahren mit mir gestorben. Der Puls wird schneller. Die Hand bleibt ruhig.", "*lässt ein trockenes, kurzes Lachen hören; atmet scharf aus, reißt die Waffe hoch und setzt unerbittlich nach.*", "Mein letzter Atemzug war nicht mein letztes Wort. Nur weil ich zornig bin, bin ich noch lange nicht ungenau.", "*rückt einen losen Handschuh über knochige Finger; treibt mit wilden Augen, aber kontrolliertem Griff den Angriff voran.*" },
        INTERCEPT = { "Schneller als mein eigener Verfall. Das muss reichen. Ein Vorsprung ist nur geliehene Zeit.", "*rückt einen losen Handschuh über knochige Finger; stürzt seitlich aus dem Kampfgetümmel und schneidet den Weg ab.*", "Knackende Gelenke sind nur ein höflicher Hinweis. Ihr rennt? Wie aufmerksam, ich wollte mich ohnehin bewegen.", "*kippt den Kopf, bis es vernehmlich knackt; stößt sich aus dem Stand ab und landet mitten in der Fluchtlinie.*" },
        PUMMEL = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Zu viele Worte. Zu wenig Deckung.", "*kippt den Kopf, bis es vernehmlich knackt; stört die Zauberbewegung mit einem raschen, gezielten Stoß.*", "Ich erinnere mich an meine Fehler. Einige tragen jetzt Rüstung. Wolltet Ihr noch etwas sagen? Nein? Gut.", "*zieht eine alte Naht am Mantel zurecht; bringt den gegnerischen Arm mit einem knappen Schlag aus dem Takt.*" },
        SWEEPING_STRIKES = { "Ohne Herzschlag bleibt erstaunlich viel Zeit zum Nachdenken. Wenn schon Arbeit, dann richtig.", "*zieht eine alte Naht am Mantel zurecht; lässt den ersten Hieb in einen zweiten Bogen übergehen.*", "Man hat mich für erledigt gehalten. Mehrfach. Mehrere Gegner? Spart Wege.", "*wischt Staub von einer rostigen Rüstungsspange; nimmt den Schwung nicht zurück, sondern führt ihn durch das Getümmel weiter.*" },
        DEATH_WISH = { "Meine Geduld ist vor Jahren mit mir gestorben. Die Vernunft hat gesprochen. Ich habe ihr widersprochen.", "*wischt Staub von einer rostigen Rüstungsspange; lockert den Griff für einen Augenblick und stürzt sich entschlossen nach vorn.*", "Mein letzter Atemzug war nicht mein letztes Wort. Ich weiß, was ich riskiere. Die anderen vielleicht nicht.", "*prüft den Halt einer brüchigen Gelenkbandage; wirft einen letzten Blick auf die eigene Deckung und entscheidet sich für den Angriff.*" },
        RECKLESSNESS = { "Meine Geduld ist vor Jahren mit mir gestorben. Vorsicht war gestern. Heute wird gehandelt.", "*prüft den Halt einer brüchigen Gelenkbandage; verliert jede Zurückhaltung, ohne die Waffe aus der Hand zu lassen.*", "Knackende Gelenke sind nur ein höflicher Hinweis. Morgen darf man mich dafür ausschimpfen. Wenn wir ein Morgen haben.", "*lässt ein trockenes, kurzes Lachen hören; setzt den ganzen Körper in eine wilde Folge von Angriffen.*" },
        LAST_STAND = { "Ich liege nicht wieder auf dem Boden, ohne dass es sich lohnt.", "*lässt ein trockenes, kurzes Lachen hören; stemmt sich mühsam auf und hebt den Schild noch einmal.*", "Ich erinnere mich an meine Fehler. Einige tragen jetzt Rüstung. Ich stehe noch. Das muss als Antwort genügen.", "*rückt einen losen Handschuh über knochige Finger; stellt sich trotz zitternder Beine erneut schützend in die Bresche.*" },
        SHIELD_WALL = { "Was schon begraben wurde, lässt sich schwer einschüchtern. Hinter mir. Keine Heldentaten auf eigene Rechnung!", "*rückt einen losen Handschuh über knochige Finger; zieht das Schild dicht heran und verhakt die Schulter in der Linie.*", "Man hat mich für erledigt gehalten. Mehrfach. Wer durch mich hindurch will, braucht einen langen Atem.", "*kippt den Kopf, bis es vernehmlich knackt; schließt die letzte Lücke zwischen Schild und Rüstung.*" },
        RETALIATION = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Wer austeilt, muss das Echo mögen.", "*kippt den Kopf, bis es vernehmlich knackt; öffnet die Deckung einen Spalt und beantwortet jeden Angriff mit Stahl.*", "Mein letzter Atemzug war nicht mein letztes Wort. Kommt nur. Ich habe für jeden einen Augenblick übrig.", "*zieht eine alte Naht am Mantel zurecht; legt die Füße breit und wartet auf die ersten ungeduldigen Hiebe.*" },
        MOCKING_BLOW = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Seid Ihr tatsächlich gefährlich oder nur besonders laut?", "*zieht eine alte Naht am Mantel zurecht; lässt die Spitze absichtlich zu tief sinken und lockt den Gegner näher.*", "Knackende Gelenke sind nur ein höflicher Hinweis. Oh, verzeiht. Ich hatte Euch für einen Übungsgegner gehalten.", "*wischt Staub von einer rostigen Rüstungsspange; setzt einen frechen Hieb und grinst hinter dem Schild hervor.*" },
        BERSERKER_RAGE = { "Meine Geduld ist vor Jahren mit mir gestorben. Angst? Die hat heute keinen Platz in meinem Kopf.", "*wischt Staub von einer rostigen Rüstungsspange; schüttelt die Schultern aus, als würde eine unsichtbare Last abfallen.*", "Ich erinnere mich an meine Fehler. Einige tragen jetzt Rüstung. Meine Furcht darf draußen warten. Meine Wut kommt mit.", "*prüft den Halt einer brüchigen Gelenkbandage; stößt die Luft aus, strafft den Nacken und hält den Blick fest.*" },
        BLOODRAGE = { "Blut? Von mir? Das nenne ich eine überraschende Entwicklung.", "*prüft den Halt einer brüchigen Gelenkbandage; schlägt die Faust gegen die Brust und sammelt neuen Kampfeswillen.*", "Man hat mich für erledigt gehalten. Mehrfach. Das Herz schlägt. Mehr muss es gerade nicht erklären.", "*lässt ein trockenes, kurzes Lachen hören; beißt die Zähne zusammen und spannt die Schultern unter der Rüstung.*" },
        DISARM = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Ihr habt ein schönes Schwert. Darf ich es kurz sehen?", "*lässt ein trockenes, kurzes Lachen hören; versucht, die gegnerische Waffe mit einer knappen Drehung aus der Hand zu hebeln.*", "Mein letzter Atemzug war nicht mein letztes Wort. Mal sehen, ob Ihr auch ohne Waffe so gesprächig seid.", "*rückt einen losen Handschuh über knochige Finger; versucht, den Griff der gegnerischen Waffe abzufangen und aus der Linie zu drehen.*" },
        INTIMIDATING_SHOUT = { "Meine Stimme klingt etwas hohl. Die Drohung nicht. Lauft, solange Ihr noch wisst, wohin!", "*rückt einen losen Handschuh über knochige Finger; schleudert einen wilden Schrei über die Köpfe der Gegner hinweg.*", "Knackende Gelenke sind nur ein höflicher Hinweis. Das war die freundliche Warnung. Die zweite kommt mit Stahl.", "*kippt den Kopf, bis es vernehmlich knackt; schlägt donnernd gegen den Schild und bleckt die Zähne.*" },
