        BATTLE_STANCE = { "Ohne Herzschlag bleibt erstaunlich viel Zeit zum Nachdenken. Zwischen Mut und Dummheit liegen manchmal nur zwei Fußbreit.", "*kippt den Kopf, bis es vernehmlich knackt; setzt die Stiefel schulterbreit auf und lässt die Waffe locker kreisen.*", "Mein letzter Atemzug war nicht mein letztes Wort. Ich bleibe beweglich. Der Rest darf sich entscheiden.", "*zieht eine alte Naht am Mantel zurecht; wiegt das Gewicht zwischen Schildarm und Waffenhand aus.*" },
        DEFENSIVE_STANCE = { "Was schon begraben wurde, lässt sich schwer einschüchtern. Wer an meine Leute will, muss zuerst meinen Schild überzeugen.", "*zieht eine alte Naht am Mantel zurecht; stellt die Beine breit und hält den Schild vor die Verbündeten.*", "Knackende Gelenke sind nur ein höflicher Hinweis. Heute gewinnt nicht, wer am lautesten brüllt.", "*wischt Staub von einer rostigen Rüstungsspange; senkt den Schwerpunkt und wird hinter der Deckung nahezu unbeweglich.*" },
        BERSERKER_STANCE = { "Meine Geduld ist vor Jahren mit mir gestorben. Wer behauptet, Wut mache blind, hat nie richtig hingesehen.", "*wischt Staub von einer rostigen Rüstungsspange; atmet tief ein, hebt das Kinn und nimmt eine wilde Haltung ein.*", "Ich erinnere mich an meine Fehler. Einige tragen jetzt Rüstung. Die Welt wird plötzlich sehr einfach: vorwärts.", "*prüft den Halt einer brüchigen Gelenkbandage; lockert die Schultern, lässt die Waffe sinken und reißt sie schlagartig hoch.*" },
        PIERCING_HOWL = { "Wenn das meine Nachbarn hören könnten. Ach, die sind tot.", "*prüft den Halt einer brüchigen Gelenkbandage; heult so durchdringend, dass die Stimmen umher für einen Moment verstummen.*", "Man hat mich für erledigt gehalten. Mehrfach. Nein, das war kein Wolfsrudel. Nur ich.", "*lässt ein trockenes, kurzes Lachen hören; wirft den Kopf zurück und lässt einen rauen, langen Laut los.*" },
        SPEARING_STRIKE = { "Ich habe schlechtere Tage erlebt. Der Tod war einer davon. Die Lücke ist schmal. Meine Spitze nicht.", "*lässt ein trockenes, kurzes Lachen hören; führt die Waffe mit einem einzigen geraden Schritt nach vorn.*", "Mein letzter Atemzug war nicht mein letztes Wort. Rüstung ist stark. Winkel sind stärker.", "*rückt einen losen Handschuh über knochige Finger; dreht das Handgelenk, zielt auf die Schwachstelle und stößt vor.*" },
        TACTICAL_MASTERY = { "Ohne Herzschlag bleibt erstaunlich viel Zeit zum Nachdenken. Der Unterschied zwischen Mut und Übermut ist eine gute Fußstellung.", "*rückt einen losen Handschuh über knochige Finger; verändert unmerklich den Stand und bewahrt die Übersicht.*", "Knackende Gelenke sind nur ein höflicher Hinweis. Ein Schlachtfeld ist kein Würfelspiel. Es wird gelesen.", "*kippt den Kopf, bis es vernehmlich knackt; mustert Wege, Gegner und Rückzugsräume, ohne die Waffe zu senken.*" },
    },
    BLOODELF = {
        HEROIC_STRIKE = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Wisst Ihr, warum meine Waffe so schwer ist? Sie widerspricht selten.", "*streicht eine Falte aus dem bestickten Ärmel; verlegt das Gewicht auf den vorderen Fuß und führt einen wuchtigen Hieb.*", "Eine ungeschickte Bewegung wäre mir peinlicher als ein Kratzer. Es gibt Argumente, die brauchen keinen zweiten Satz.", "*richtet den fein gearbeiteten Handschutz aus; schiebt die Schulter nach und lässt den Stahl sprechen.*" },
        CHARGE = { "Wer Stil besitzt, muss nicht langsam sein. Wenn der Weg versperrt ist, nehme ich eben den direkten.", "*richtet den fein gearbeiteten Handschutz aus; senkt die Schulter, stößt sich ab und wirbelt Staub auf.*", "Meine Vorfahren hätten die Haltung bemängelt. Den Mut nicht. Ich komme! Das ist keine Warnung, sondern eine Wegbeschreibung!", "*dreht den Waffenknauf mit geübter Eleganz; prescht mit einem lauten Scheppern durch die Lücke in der Reihe.*" },
        REND = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Rüstungsnähte sind kleine Geheimnisse. Ich bin neugierig.", "*dreht den Waffenknauf mit geübter Eleganz; führt die Schneide schräg über eine schlecht geschützte Stelle.*", "Die Klinge braucht keine Verzierung, nur den richtigen Winkel. Ein Schneider wäre entsetzt. Ich bin zufrieden.", "*hebt das Kinn um einen kaum merklichen Winkel; zieht die Klinge rasch zurück und sucht die nächste Öffnung.*" },
        HAMSTRING = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Weglaufen? Das ist ein Plan mit Schwächen.", "*hebt das Kinn um einen kaum merklichen Winkel; taucht tief unter der gegnerischen Deckung hindurch.*", "Selbst in einem Chaos kann man Würde bewahren. Ich schlage nicht gern zweimal hinterher. Einmal genügt.", "*prüft den Sitz einer verzierten Schulterspange; führt die Waffe knapp über den Boden und richtet sich sofort wieder auf.*" },
        THUNDER_CLAP = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Wenn der Boden bebt, brauchen wir keinen Trommler mehr.", "*prüft den Sitz einer verzierten Schulterspange; stampft mit solcher Wucht auf, dass Staub vom Boden springt.*", "Eine ungeschickte Bewegung wäre mir peinlicher als ein Kratzer. Hört Ihr das? Die Erde erhebt Einspruch.", "*führt die Klinge mit einer sparsamen Handbewegung; reißt die Arme auseinander und lässt einen dumpfen Schlag durch die Reihen grollen.*" },
        CLEAVE = { "Ein Duell ist Geometrie mit Konsequenzen. Wer nebeneinander antritt, teilt sich auch die Probleme.", "*führt die Klinge mit einer sparsamen Handbewegung; schwingt die Waffe in einem breiten Bogen quer durch den Kampfraum.*", "Meine Vorfahren hätten die Haltung bemängelt. Den Mut nicht. Ich hoffe, Ihr habt alle genug Abstand. Ich nicht.", "*streicht eine Falte aus dem bestickten Ärmel; dreht auf der Ferse und nimmt den Schwung in den nächsten Bogen mit.*" },
        EXECUTE = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Ich habe Euch jede Gelegenheit zum Rückzug gelassen.", "*streicht eine Falte aus dem bestickten Ärmel; wartet einen Herzschlag ab und führt dann einen endgültig wirkenden Hieb.*", "Die Klinge braucht keine Verzierung, nur den richtigen Winkel. Jetzt wird nicht mehr verhandelt.", "*richtet den fein gearbeiteten Handschutz aus; fasst den Griff fester und schließt die letzte Lücke.*" },
        SUNDER_ARMOR = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Schöner Harnisch. Schade um die Nieten.", "*richtet den fein gearbeiteten Handschutz aus; setzt die Waffe gezielt an einer lockeren Rüstungskante an.*", "Selbst in einem Chaos kann man Würde bewahren. Teurer Stahl ist noch keine gute Deckung.", "*dreht den Waffenknauf mit geübter Eleganz; zieht mit der Schneide eine Linie entlang einer Naht im Metall.*" },
        SHIELD_BLOCK = { "Eine gerade Haltung hält mehr aus als manche Rüstung. Da müsst Ihr schon anklopfen. Der Schild bleibt zu.", "*dreht den Waffenknauf mit geübter Eleganz; dreht die Schildkante in den kommenden Schlag und federt ihn ab.*", "Eine ungeschickte Bewegung wäre mir peinlicher als ein Kratzer. Ein gutes Schild hört zu, bevor es antwortet.", "*hebt das Kinn um einen kaum merklichen Winkel; stemmt die Stiefel in den Boden und lässt die Deckung nicht nachgeben.*" },
        SHIELD_BASH = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Psst. Mal sehen, ob ich Euren Zauber unterbrechen kann.", "*hebt das Kinn um einen kaum merklichen Winkel; rammt die Schildfläche nach vorn, genau zwischen zwei Silben.*", "Meine Vorfahren hätten die Haltung bemängelt. Den Mut nicht. Meine Antwort auf Magie hat einen Holzgriff.", "*prüft den Sitz einer verzierten Schulterspange; rückt einen Schritt heran und stößt unvermittelt mit dem Schild zu.*" },
        TAUNT = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Hier drüben! Der Ärger hat heute meinen Namen.", "*prüft den Sitz einer verzierten Schulterspange; klopft mit dem Schwertknauf dreimal provokant auf den Schild.*", "Die Klinge braucht keine Verzierung, nur den richtigen Winkel. Die anderen haben Wichtigeres zu tun. Ich nicht.", "*führt die Klinge mit einer sparsamen Handbewegung; tritt demonstrativ aus der Reihe und winkt die Gegner heran.*" },
        BATTLE_SHOUT = { "Auch eine laute Botschaft darf präzise formuliert sein. Schultern hoch, Reihen schließen! Heute fällt hier niemand allein!", "*führt die Klinge mit einer sparsamen Handbewegung; schlägt den Schwertknauf im Takt gegen den Schildrand.*", "Selbst in einem Chaos kann man Würde bewahren. Ihr habt Beine zum Stehen und Herzen zum Durchhalten. Nutzt beides!", "*streicht eine Falte aus dem bestickten Ärmel; richtet sich vor den Verbündeten auf und hebt die Klinge hoch.*" },
        DEMORALIZING_SHOUT = { "Auch eine laute Botschaft darf präzise formuliert sein. Die Ersten von Euch zittern schon. Die Letzten merken es gleich!", "*streicht eine Falte aus dem bestickten Ärmel; lässt einen tiefen, rauen Schlachtruf aus voller Brust erschallen.*", "Eine ungeschickte Bewegung wäre mir peinlicher als ein Kratzer. Schaut Euch um. Für wen wollt Ihr eigentlich noch kämpfen?", "*richtet den fein gearbeiteten Handschutz aus; zeigt mit der Klinge auf die wankende feindliche Linie.*" },
        REVENGE = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Danke für die Gelegenheit. Die kommt sofort zurück.", "*richtet den fein gearbeiteten Handschutz aus; lenkt die Waffe ab und fährt in die entstandene Lücke.*", "Meine Vorfahren hätten die Haltung bemängelt. Den Mut nicht. Ich vergesse Gesichter. Schläge nicht.", "*dreht den Waffenknauf mit geübter Eleganz; dreht sich aus der Abwehr direkt in den Gegenangriff.*" },
        OVERPOWER = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Da war eine Lücke. Ihr habt sie mir geschenkt.", "*dreht den Waffenknauf mit geübter Eleganz; gleitet an der vorbeigehenden Waffe vorbei und nutzt den offenen Winkel.*", "Die Klinge braucht keine Verzierung, nur den richtigen Winkel. Wer danebenhaut, lädt mich ein.", "*hebt das Kinn um einen kaum merklichen Winkel; nutzt eine missratene Bewegung für einen schnellen Gegenstoß.*" },
        MORTAL_STRIKE = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Ich spare mir den zweiten Versuch.", "*hebt das Kinn um einen kaum merklichen Winkel; nimmt die Waffe fest in beide Hände und legt den ganzen Körper in einen einzigen Schlag.*", "Selbst in einem Chaos kann man Würde bewahren. Manche Duelle enden mit einem Satz. Dieses nicht.", "*prüft den Sitz einer verzierten Schulterspange; schreitet voran und führt den Stahl mit unerbittlicher Präzision.*" },
        WHIRLWIND = { "Ein Duell ist Geometrie mit Konsequenzen. Stellt Euch ruhig im Kreis auf. Es ist praktisch.", "*prüft den Sitz einer verzierten Schulterspange; dreht sich mitsamt der Waffe durch eine Schneise im Gedränge.*", "Eine ungeschickte Bewegung wäre mir peinlicher als ein Kratzer. Ich teile gern. Heute Stahl.", "*führt die Klinge mit einer sparsamen Handbewegung; lässt die Klinge in weitem Schwung ringsum singen.*" },
        BLOODTHIRST = { "Wahre Beherrschung zeigt sich erst im Zorn. Der Puls wird schneller. Die Hand bleibt ruhig.", "*führt die Klinge mit einer sparsamen Handbewegung; atmet scharf aus, reißt die Waffe hoch und setzt unerbittlich nach.*", "Meine Vorfahren hätten die Haltung bemängelt. Den Mut nicht. Nur weil ich zornig bin, bin ich noch lange nicht ungenau.", "*streicht eine Falte aus dem bestickten Ärmel; treibt mit wilden Augen, aber kontrolliertem Griff den Angriff voran.*" },
        INTERCEPT = { "Wer Stil besitzt, muss nicht langsam sein. Ein Vorsprung ist nur geliehene Zeit.", "*streicht eine Falte aus dem bestickten Ärmel; stürzt seitlich aus dem Kampfgetümmel und schneidet den Weg ab.*", "Die Klinge braucht keine Verzierung, nur den richtigen Winkel. Ihr rennt? Wie aufmerksam, ich wollte mich ohnehin bewegen.", "*richtet den fein gearbeiteten Handschutz aus; stößt sich aus dem Stand ab und landet mitten in der Fluchtlinie.*" },
        PUMMEL = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Zu viele Worte. Zu wenig Deckung.", "*richtet den fein gearbeiteten Handschutz aus; stört die Zauberbewegung mit einem raschen, gezielten Stoß.*", "Selbst in einem Chaos kann man Würde bewahren. Wolltet Ihr noch etwas sagen? Nein? Gut.", "*dreht den Waffenknauf mit geübter Eleganz; bringt den gegnerischen Arm mit einem knappen Schlag aus dem Takt.*" },
        SWEEPING_STRIKES = { "Ein Duell ist Geometrie mit Konsequenzen. Wenn schon Arbeit, dann richtig.", "*dreht den Waffenknauf mit geübter Eleganz; lässt den ersten Hieb in einen zweiten Bogen übergehen.*", "Eine ungeschickte Bewegung wäre mir peinlicher als ein Kratzer. Mehrere Gegner? Spart Wege.", "*hebt das Kinn um einen kaum merklichen Winkel; nimmt den Schwung nicht zurück, sondern führt ihn durch das Getümmel weiter.*" },
        DEATH_WISH = { "Wahre Beherrschung zeigt sich erst im Zorn. Die Vernunft hat gesprochen. Ich habe ihr widersprochen.", "*hebt das Kinn um einen kaum merklichen Winkel; lockert den Griff für einen Augenblick und stürzt sich entschlossen nach vorn.*", "Meine Vorfahren hätten die Haltung bemängelt. Den Mut nicht. Ich weiß, was ich riskiere. Die anderen vielleicht nicht.", "*prüft den Sitz einer verzierten Schulterspange; wirft einen letzten Blick auf die eigene Deckung und entscheidet sich für den Angriff.*" },
        RECKLESSNESS = { "Vollkommene Eleganz bedeutet nicht immer Zurückhaltung.", "*prüft den Sitz einer verzierten Schulterspange; verliert jede Zurückhaltung, ohne die Waffe aus der Hand zu lassen.*", "Die Klinge braucht keine Verzierung, nur den richtigen Winkel. Morgen darf man mich dafür ausschimpfen. Wenn wir ein Morgen haben.", "*führt die Klinge mit einer sparsamen Handbewegung; setzt den ganzen Körper in eine wilde Folge von Angriffen.*" },
        LAST_STAND = { "Eine gerade Haltung hält mehr aus als manche Rüstung. Bis hierher und keinen Schritt weiter.", "*führt die Klinge mit einer sparsamen Handbewegung; stemmt sich mühsam auf und hebt den Schild noch einmal.*", "Selbst in einem Chaos kann man Würde bewahren. Ich stehe noch. Das muss als Antwort genügen.", "*streicht eine Falte aus dem bestickten Ärmel; stellt sich trotz zitternder Beine erneut schützend in die Bresche.*" },
        SHIELD_WALL = { "Eine gerade Haltung hält mehr aus als manche Rüstung. Hinter mir. Keine Heldentaten auf eigene Rechnung!", "*streicht eine Falte aus dem bestickten Ärmel; zieht das Schild dicht heran und verhakt die Schulter in der Linie.*", "Eine ungeschickte Bewegung wäre mir peinlicher als ein Kratzer. Wer durch mich hindurch will, braucht einen langen Atem.", "*richtet den fein gearbeiteten Handschutz aus; schließt die letzte Lücke zwischen Schild und Rüstung.*" },
        RETALIATION = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Wer austeilt, muss das Echo mögen.", "*richtet den fein gearbeiteten Handschutz aus; öffnet die Deckung einen Spalt und beantwortet jeden Angriff mit Stahl.*", "Meine Vorfahren hätten die Haltung bemängelt. Den Mut nicht. Kommt nur. Ich habe für jeden einen Augenblick übrig.", "*dreht den Waffenknauf mit geübter Eleganz; legt die Füße breit und wartet auf die ersten ungeduldigen Hiebe.*" },
        MOCKING_BLOW = { "Verzeiht, ich hielt Eure Kampftechnik für eine Aufführung.", "*dreht den Waffenknauf mit geübter Eleganz; lässt die Spitze absichtlich zu tief sinken und lockt den Gegner näher.*", "Die Klinge braucht keine Verzierung, nur den richtigen Winkel. Oh, verzeiht. Ich hatte Euch für einen Übungsgegner gehalten.", "*hebt das Kinn um einen kaum merklichen Winkel; setzt einen frechen Hieb und grinst hinter dem Schild hervor.*" },
        BERSERKER_RAGE = { "Wahre Beherrschung zeigt sich erst im Zorn. Angst? Die hat heute keinen Platz in meinem Kopf.", "*hebt das Kinn um einen kaum merklichen Winkel; schüttelt die Schultern aus, als würde eine unsichtbare Last abfallen.*", "Selbst in einem Chaos kann man Würde bewahren. Meine Furcht darf draußen warten. Meine Wut kommt mit.", "*prüft den Sitz einer verzierten Schulterspange; stößt die Luft aus, strafft den Nacken und hält den Blick fest.*" },
        BLOODRAGE = { "Wahre Beherrschung zeigt sich erst im Zorn. Schmerz ist eine Nachricht. Ich antworte später.", "*prüft den Sitz einer verzierten Schulterspange; schlägt die Faust gegen die Brust und sammelt neuen Kampfeswillen.*", "Eine ungeschickte Bewegung wäre mir peinlicher als ein Kratzer. Das Herz schlägt. Mehr muss es gerade nicht erklären.", "*führt die Klinge mit einer sparsamen Handbewegung; beißt die Zähne zusammen und spannt die Schultern unter der Rüstung.*" },
        DISARM = { "Euer Griff ist schrecklich. Ohne Waffe wirkt Ihr gepflegter.", "*führt die Klinge mit einer sparsamen Handbewegung; versucht, die gegnerische Waffe mit einer knappen Drehung aus der Hand zu hebeln.*", "Meine Vorfahren hätten die Haltung bemängelt. Den Mut nicht. Mal sehen, ob Ihr auch ohne Waffe so gesprächig seid.", "*streicht eine Falte aus dem bestickten Ärmel; versucht, den Griff der gegnerischen Waffe abzufangen und aus der Linie zu drehen.*" },
        INTIMIDATING_SHOUT = { "Auch eine laute Botschaft darf präzise formuliert sein. Lauft, solange Ihr noch wisst, wohin!", "*streicht eine Falte aus dem bestickten Ärmel; schleudert einen wilden Schrei über die Köpfe der Gegner hinweg.*", "Die Klinge braucht keine Verzierung, nur den richtigen Winkel. Das war die freundliche Warnung. Die zweite kommt mit Stahl.", "*richtet den fein gearbeiteten Handschutz aus; schlägt donnernd gegen den Schild und bleckt die Zähne.*" },
        CHALLENGING_SHOUT = { "Auch eine laute Botschaft darf präzise formuliert sein. ALLE ZU MIR! Ich habe Platz für Euren ganzen Ärger!", "*richtet den fein gearbeiteten Handschutz aus; reißt beide Arme auseinander und fordert die feindliche Reihe heraus.*", "Selbst in einem Chaos kann man Würde bewahren. Lasst die anderen in Ruhe. Ich bin heute Euer Problem!", "*dreht den Waffenknauf mit geübter Eleganz; schlägt mehrmals auf den Schild und brüllt die Gegner an.*" },
        SLAM = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Das ist kein Hammer. Es fühlt sich gleich aber so an.", "*dreht den Waffenknauf mit geübter Eleganz; holt über die Schulter aus und lässt den Stahl mit voller Kraft niederfahren.*", "Eine ungeschickte Bewegung wäre mir peinlicher als ein Kratzer. Lieber ein sauberer Treffer als fünf halbe.", "*hebt das Kinn um einen kaum merklichen Winkel; lässt die Waffe nach kurzem Zögern mit dem ganzen Gewicht folgen.*" },
        DEVASTATE = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Schon locker? Dann lösen wir den Rest auch noch.", "*hebt das Kinn um einen kaum merklichen Winkel; schlägt hart auf eine bereits angeschlagene Stelle der Rüstung.*", "Meine Vorfahren hätten die Haltung bemängelt. Den Mut nicht. Ich sehe, der Schmied hat an der falschen Stelle gespart.", "*prüft den Sitz einer verzierten Schulterspange; klopft prüfend gegen die offene Fuge und setzt entschlossen nach.*" },
        SHIELD_SLAM = { "Ein sauberer Treffer ist eleganter als jedes Drohwort. Ein Schild kann auch Türen schließen. Auf Nasenhöhe.", "*prüft den Sitz einer verzierten Schulterspange; reißt den Schild aus der Deckung und stößt dessen Kante kraftvoll nach vorn.*", "Die Klinge braucht keine Verzierung, nur den richtigen Winkel. Wer sagt, Verteidigung sei höflich?", "*führt die Klinge mit einer sparsamen Handbewegung; macht einen kurzen Satz vorwärts und lässt den Schild sprechen.*" },
